function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  // Smooth C-infinity periodic scene emphasis windows across 3 scenes (total = 20s)
  const s1Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 1 / 6));
  const s2Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 3 / 6));
  const s3Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 5 / 6));

  const groundY = height * 0.855;
  const viaductY = height * 0.735;

  // 1. Clean Midnight Graphite Modern Sky Background (Zero Glow Effect on Background)
  const skyGrad = ctx.createLinearGradient(0, 0, 0, groundY);
  skyGrad.addColorStop(0, '#060810');
  skyGrad.addColorStop(0.55, '#090C15');
  skyGrad.addColorStop(1, '#0E1424');
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle geometric distant architectural horizon layer strictly below rooftop zones
  ctx.fillStyle = '#0C111E';
  const bgSilhouettes = [
    [0.045, 0.04, 0.56],
    [0.18, 0.05, 0.50],
    [0.35, 0.06, 0.46],
    [0.57, 0.06, 0.48],
    [0.75, 0.05, 0.53],
    [0.905, 0.045, 0.56],
  ];
  for (const [bx, bw, topR] of bgSilhouettes) {
    ctx.fillRect(width * bx, height * topR, width * bw, groundY - height * topR);
  }

  // 2. Clean Atmospheric Grid Arch Dome (Strictly Contained Dome Over Skyline, Zero Canvas Border Strokes)
  const domeCx = width * 0.50;
  const domeCy = height * 0.70;
  const domeRx = width * 0.468;
  const domeRy = height * 0.640;

  function traceAtmosphereDomePath(scale) {
    ctx.beginPath();
    ctx.ellipse(domeCx, domeCy, domeRx * scale, domeRy * scale, 0, Math.PI, TAU);
  }

  // Subtle segmented atmospheric grid ribs inside dome interior
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(domeCx, domeCy, domeRx, domeRy, 0, Math.PI, TAU);
  ctx.lineTo(domeCx - domeRx, domeCy);
  ctx.closePath();
  ctx.clip();

  for (const sc of [1.0, 0.88, 0.76]) {
    traceAtmosphereDomePath(sc);
    ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
    ctx.strokeStyle = `rgba(64, 196, 255, ${(0.08 + 0.14 * s3Weight).toFixed(3)})`;
    ctx.stroke();
  }

  // Radial longitudinal grid ribs across upper dome arch
  for (let i = 1; i <= 7; i++) {
    const a = lerp(Math.PI + 0.12, TAU - 0.12, i / 8);
    ctx.beginPath();
    ctx.moveTo(domeCx + Math.cos(a) * domeRx * 0.76, domeCy + Math.sin(a) * domeRy * 0.76);
    ctx.lineTo(domeCx + Math.cos(a) * domeRx, domeCy + Math.sin(a) * domeRy);
    ctx.lineWidth = Math.max(1.0, minSide * 0.0012);
    ctx.strokeStyle = `rgba(105, 240, 174, ${(0.09 + 0.14 * s3Weight).toFixed(3)})`;
    ctx.stroke();
  }

  // Scene 3 Climate Shield Atmospheric Stabilization Sweep (clean sharp vector sweep inside dome)
  const sweepProgress = u;
  const sweepX = lerp(domeCx - domeRx * 1.05, domeCx + domeRx * 1.05, (sweepProgress * 1) % 1);
  const sweepAlpha = (0.12 + 0.88 * s3Weight) * Math.sin(Math.PI * sweepProgress);
  if (sweepAlpha > 0.01) {
    const ribbonW = width * 0.085;
    const sweepGrad = ctx.createLinearGradient(sweepX - ribbonW, 0, sweepX, 0);
    sweepGrad.addColorStop(0, 'rgba(105, 240, 174, 0)');
    sweepGrad.addColorStop(0.75, `rgba(105, 240, 174, ${(0.10 * sweepAlpha).toFixed(4)})`);
    sweepGrad.addColorStop(1, `rgba(255, 224, 130, ${(0.22 * sweepAlpha).toFixed(4)})`);
    ctx.fillStyle = sweepGrad;
    ctx.fillRect(sweepX - ribbonW, 0, ribbonW, groundY);

    ctx.beginPath();
    ctx.moveTo(sweepX, 0);
    ctx.lineTo(sweepX, groundY);
    ctx.lineWidth = minSide * 0.0022;
    ctx.strokeStyle = `rgba(105, 240, 174, ${(0.55 * sweepAlpha).toFixed(3)})`;
    ctx.stroke();
  }
  ctx.restore();

  // Outer dome frontier crisp accent arc
  traceAtmosphereDomePath(1.0);
  ctx.lineWidth = minSide * 0.0020;
  ctx.strokeStyle = mixColor([36, 78, 122], [105, 240, 174], s3Weight * 0.8);
  ctx.stroke();

  // 3. Elevated Architectural Substructure & Clean Non-Overlapping Eco-Buildings
  // Five buildings separated strictly by clean 0.030*W air plazas; transit bridge piers sit ONLY in gaps!
  const buildings = [
    { id: 0, x0: 0.090, w: 0.105, roofY: 0.460, kind: 'solar_garden', phase: 0.00, cols: 4, rows: 5 },
    { id: 1, x0: 0.225, w: 0.140, roofY: 0.315, kind: 'wind_tower',   phase: 0.16, cols: 5, rows: 9 },
    { id: 2, x0: 0.395, w: 0.200, roofY: 0.240, kind: 'central_eco',  phase: 0.32, cols: 7, rows: 11 },
    { id: 3, x0: 0.625, w: 0.140, roofY: 0.305, kind: 'wind_tower',   phase: 0.48, cols: 5, rows: 9 },
    { id: 4, x0: 0.795, w: 0.110, roofY: 0.455, kind: 'solar_spire',  phase: 0.64, cols: 4, rows: 5 },
  ];

  // Supporting Viaduct Piers placed strictly INSIDE gaps between buildings (zero tower overlap)
  const gapCenters = [0.052, 0.210, 0.380, 0.610, 0.780, 0.945];
  for (const gx of gapCenters) {
    const px = width * gx;
    const pw = minSide * 0.014;
    ctx.fillStyle = '#141C2E';
    ctx.fillRect(px - pw * 0.5, viaductY + minSide * 0.016, pw, groundY - (viaductY + minSide * 0.016));
    ctx.fillStyle = '#243454';
    ctx.fillRect(px - pw * 0.18, viaductY + minSide * 0.016, pw * 0.36, groundY - (viaductY + minSide * 0.016));
  }

  // Helper: Geometric Vector Rooftop Tree (Crisp Multi-Tier Emerald-Sage Foliage, Zero Overlap)
  function drawRoofTree(tx, ty, hSize, energy) {
    const sw = minSide * hSize;
    // Trunk
    ctx.fillStyle = '#1E4D3B';
    ctx.fillRect(tx - sw * 0.07, ty - sw * 0.38, sw * 0.14, sw * 0.38);

    // Dual-layer hexagonal/teardrop botanical crown
    const pulse = 1 + 0.045 * Math.sin(TAU * (u * 3 + energy));
    const r = sw * 0.36 * pulse;
    ctx.beginPath();
    ctx.arc(tx, ty - sw * 0.58, r, 0, TAU);
    ctx.fillStyle = mixColor([26, 128, 86], [105, 240, 174], 0.35 + 0.65 * s2Weight);
    ctx.fill();
    ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
    ctx.strokeStyle = '#69F0AE';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(tx - r * 0.22, ty - sw * 0.64, r * 0.42, 0, TAU);
    ctx.fillStyle = '#B9F6CA';
    ctx.fill();
  }

  // Helper: Vertical Darrieus Eggbeater Wind Turbine (2D Sinusoidal Elliptic Blades)
  function drawDarrieusTurbine(tx, baseY, hSize, spinPhase) {
    const h = minSide * hSize;
    const topY = baseY - h;
    const midY = (baseY + topY) * 0.5;
    const maxRx = h * 0.40;

    // Pedestal & Central Vertical Mast
    roundRectPath(tx - h * 0.16, baseY - h * 0.10, h * 0.32, h * 0.10, minSide * 0.004);
    ctx.fillStyle = '#1C263B';
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(tx, baseY);
    ctx.lineTo(tx, topY);
    ctx.lineWidth = minSide * 0.0036;
    ctx.strokeStyle = '#40C4FF';
    ctx.stroke();

    // Seamless periodic rotation: 10 exact full turns over 20s, smoothly modulated in Scene 2!
    const theta =
      TAU * (10 * u + (3 * (Math.sin(TAU * (u - 0.5)) - Math.sin(-Math.PI))) / TAU) + spinPhase;

    // Draw 3 Curved Darrieus Blades sorted back-to-front via cosine depth
    const blades = [];
    for (let b = 0; b < 3; b++) {
      const a = theta + (b / 3) * TAU;
      blades.push({ sinA: Math.sin(a), cosA: Math.cos(a) });
    }
    blades.sort((a, b) => a.cosA - b.cosA);

    for (const bl of blades) {
      const xOffset = maxRx * bl.sinA;
      const isFront = bl.cosA >= 0;
      ctx.beginPath();
      ctx.moveTo(tx, topY + h * 0.10);
      ctx.quadraticCurveTo(tx + xOffset * 1.45, midY, tx, baseY - h * 0.12);
      ctx.lineWidth = minSide * (isFront ? 0.0036 : 0.0024);
      ctx.strokeStyle = isFront
        ? mixColor([64, 196, 255], [105, 240, 174], s2Weight)
        : '#1D5275';
      ctx.stroke();
    }

    // Center mast top beacon node
    ctx.beginPath();
    ctx.arc(tx, topY, minSide * 0.0045, 0, TAU);
    ctx.fillStyle = '#FFE082';
    ctx.fill();
  }

  // Draw Inter-Building Clean Energy Exchange Bridges strictly across the 0.030*W open gaps!
  const skyBridges = [
    { bA: 0, bB: 1, yR: 0.505 },
    { bA: 1, bB: 2, yR: 0.355 },
    { bA: 2, bB: 3, yR: 0.355 },
    { bA: 3, bB: 4, yR: 0.500 },
  ];
  for (let sb = 0; sb < skyBridges.length; sb++) {
    const br = skyBridges[sb];
    const x1 = width * (buildings[br.bA].x0 + buildings[br.bA].w);
    const x2 = width * buildings[br.bB].x0;
    const by = height * br.yR;

    ctx.beginPath();
    ctx.moveTo(x1, by);
    ctx.lineTo(x2, by);
    ctx.lineWidth = minSide * 0.0055;
    ctx.strokeStyle = '#182438';
    ctx.stroke();

    ctx.lineWidth = minSide * 0.0022;
    ctx.strokeStyle = mixColor([48, 86, 128], [105, 240, 174], s2Weight);
    ctx.stroke();

    // Animated clean energy packet shuttling across gap
    const p = (u * 4 + sb * 0.25) % 1;
    const px = lerp(x1, x2, p);
    ctx.beginPath();
    ctx.arc(px, by, minSide * 0.0036 * Math.sin(Math.PI * p), 0, TAU);
    ctx.fillStyle = '#FFE082';
    ctx.fill();
  }

  // Render the 5 Clean Vertical Eco-Towers
  for (const b of buildings) {
    const bx = width * b.x0;
    const bw = width * b.w;
    // Gentle balanced vertical breath in Scene 1 without breaking alignment or collapsing
    const crownLift = minSide * 0.010 * s1Weight * Math.sin(TAU * (u * 2 - b.phase));
    const roofY = height * b.roofY - crownLift;
    const bh = groundY - roofY;

    // Tower Body Chamfered Top
    ctx.beginPath();
    const ch = minSide * 0.010;
    ctx.moveTo(bx + ch, roofY);
    ctx.lineTo(bx + bw - ch, roofY);
    ctx.lineTo(bx + bw, roofY + ch);
    ctx.lineTo(bx + bw, groundY);
    ctx.lineTo(bx, groundY);
    ctx.lineTo(bx, roofY + ch);
    ctx.closePath();

    const towerGrad = ctx.createLinearGradient(bx, roofY, bx + bw, groundY);
    towerGrad.addColorStop(0, '#162036');
    towerGrad.addColorStop(0.65, '#101829');
    towerGrad.addColorStop(1, '#0B101C');
    ctx.fillStyle = towerGrad;
    ctx.fill();

    ctx.lineWidth = minSide * 0.0020;
    ctx.strokeStyle = mixColor([46, 66, 102], [64, 196, 255], s1Weight * 0.5 + s3Weight * 0.4);
    ctx.stroke();

    // Solar Facade Diagonal Specular Glint Strip (strictly clipped inside building body & above viaduct!)
    ctx.save();
    ctx.beginPath();
    ctx.rect(bx + 2, roofY + ch, bw - 4, viaductY - minSide * 0.032 - (roofY + ch));
    ctx.clip();

    const glintX = lerp(bx - bw * 0.5, bx + bw * 1.5, (u * 2 + b.phase) % 1);
    const glintW = bw * 0.28;
    const gGrad = ctx.createLinearGradient(glintX, roofY, glintX + glintW, viaductY);
    gGrad.addColorStop(0, 'rgba(64, 196, 255, 0)');
    gGrad.addColorStop(0.5, 'rgba(64, 196, 255, 0.08)');
    gGrad.addColorStop(1, 'rgba(64, 196, 255, 0)');
    ctx.fillStyle = gGrad;
    ctx.beginPath();
    ctx.moveTo(glintX, roofY);
    ctx.lineTo(glintX + glintW, roofY);
    ctx.lineTo(glintX + glintW - bw * 0.35, viaductY);
    ctx.lineTo(glintX - bw * 0.35, viaductY);
    ctx.closePath();
    ctx.fill();

    // Clean Responsive Glass & Solar Window Grid (strictly bounded ABOVE viaduct corridor)
    const padX = bw * 0.14;
    const padTop = ch + minSide * 0.018;
    const gridW = bw - padX * 2;
    const gridBot = viaductY - minSide * 0.036;
    const gridH = Math.max(minSide * 0.05, gridBot - (roofY + padTop));

    const colGap = gridW * 0.08;
    const cellW = (gridW - colGap * (b.cols - 1)) / b.cols;
    const rowGap = gridH * 0.06;
    const cellH = (gridH - rowGap * (b.rows - 1)) / b.rows;

    for (let r = 0; r < b.rows; r++) {
      for (let c = 0; c < b.cols; c++) {
        const wx = bx + padX + c * (cellW + colGap);
        const wy = roofY + padTop + r * (cellH + rowGap);
        const wPulse = 0.5 + 0.5 * Math.sin(TAU * (u * 3 - r * 0.11 - c * 0.08 - b.phase));
        const active = clamp01(0.28 + 0.72 * wPulse * (0.45 + 0.55 * Math.max(s1Weight, s3Weight)));

        roundRectPath(wx, wy, cellW, cellH, Math.min(cellW, cellH) * 0.22);
        // Alternating vertical eco-green planter terraces & champagne-gold/sky solar glass panels
        if (b.kind === 'central_eco' && (c === 0 || c === b.cols - 1)) {
          ctx.fillStyle = mixColor([20, 74, 52], [105, 240, 174], clamp01(0.3 + 0.7 * s2Weight * wPulse));
        } else {
          ctx.fillStyle =
            (r + c) % 3 === 0
              ? mixColor([24, 42, 68], [255, 224, 130], active * 0.85)
              : mixColor([18, 34, 58], [64, 196, 255], active * 0.75);
        }
        ctx.fill();
      }
    }
    ctx.restore();

    // Rooftop Architecture Features (Zero overlap, neatly nested on building roofs!)
    const centerTx = bx + bw * 0.5;
    if (b.kind === 'solar_garden') {
      // Slanted rooftop solar collector + twin rooftop trees
      drawRoofTree(bx + bw * 0.28, roofY, 0.065, 0.1);
      drawRoofTree(bx + bw * 0.72, roofY, 0.075, 0.3);
    } else if (b.kind === 'wind_tower') {
      drawDarrieusTurbine(centerTx, roofY, 0.105, b.phase * TAU);
    } else if (b.kind === 'central_eco') {
      // Central stepped conservatory deck + 3 balanced rooftop botanical trees
      roundRectPath(bx + bw * 0.16, roofY - minSide * 0.018, bw * 0.68, minSide * 0.018, minSide * 0.005);
      ctx.fillStyle = '#1E2C45';
      ctx.fill();
      drawRoofTree(bx + bw * 0.26, roofY - minSide * 0.018, 0.068, 0.2);
      drawRoofTree(centerTx, roofY - minSide * 0.018, 0.092, 0.5);
      drawRoofTree(bx + bw * 0.74, roofY - minSide * 0.018, 0.068, 0.8);
    } else if (b.kind === 'solar_spire') {
      // Slanted photovoltaic solar array rack + single tree
      drawRoofTree(bx + bw * 0.30, roofY, 0.065, 0.4);
      ctx.beginPath();
      ctx.moveTo(bx + bw * 0.52, roofY);
      ctx.lineTo(bx + bw * 0.86, roofY);
      ctx.lineTo(bx + bw * 0.86, roofY - minSide * 0.036);
      ctx.closePath();
      ctx.fillStyle = '#25395C';
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(bx + bw * 0.50, roofY - minSide * 0.004);
      ctx.lineTo(bx + bw * 0.88, roofY - minSide * 0.040);
      ctx.lineWidth = minSide * 0.0050;
      ctx.strokeStyle = '#FFE082';
      ctx.stroke();
    }
  }

  // 4. Elevated Autonomous Sky-Transit Viaduct (Clean Horizontal Corridor Along y = viaductY)
  const viaH = minSide * 0.036;
  ctx.fillStyle = '#121A2B';
  ctx.fillRect(0, viaductY - viaH * 0.5, width, viaH);

  ctx.beginPath();
  ctx.moveTo(0, viaductY - viaH * 0.5);
  ctx.lineTo(width, viaductY - viaH * 0.5);
  ctx.moveTo(0, viaductY + viaH * 0.5);
  ctx.lineTo(width, viaductY + viaH * 0.5);
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#2A3B5E';
  ctx.stroke();

  // Dual Transit Guide Rails inside Viaduct (Upper Rail Rightward, Lower Rail Leftward)
  const railUpperY = viaductY - minSide * 0.007;
  const railLowerY = viaductY + minSide * 0.007;
  ctx.lineWidth = Math.max(1.2, minSide * 0.0014);
  ctx.strokeStyle = 'rgba(64, 196, 255, 0.25)';
  ctx.beginPath();
  ctx.moveTo(0, railUpperY);
  ctx.lineTo(width, railUpperY);
  ctx.moveTo(0, railLowerY);
  ctx.lineTo(width, railLowerY);
  ctx.stroke();

  // Seamless Periodic Autonomous Light-Ribbon Transit Capsules (No Human Figures!)
  const capsuleCount = 4;
  for (let i = 0; i < capsuleCount; i++) {
    // Upper lane (Rightward: 2 full screen transits in 20s)
    const pUp = (u * 2 + i / capsuleCount) % 1;
    const ux = lerp(-width * 0.08, width * 1.08, pUp);
    const capW = minSide * 0.068;
    const capH = minSide * 0.0085;

    const uGrad = ctx.createLinearGradient(ux - capW, railUpperY, ux, railUpperY);
    uGrad.addColorStop(0, 'rgba(64, 196, 255, 0)');
    uGrad.addColorStop(1, 'rgba(64, 196, 255, 0.95)');
    roundRectPath(ux - capW, railUpperY - capH * 0.5, capW, capH, capH * 0.5);
    ctx.fillStyle = uGrad;
    ctx.fill();

    // Lower lane (Leftward: 2 full screen transits in 20s)
    const pDn = (u * 2 + i / capsuleCount + 0.125) % 1;
    const lx = lerp(width * 1.08, -width * 0.08, pDn);
    const lGrad = ctx.createLinearGradient(lx + capW, railLowerY, lx, railLowerY);
    lGrad.addColorStop(0, 'rgba(255, 224, 130, 0)');
    lGrad.addColorStop(1, 'rgba(255, 224, 130, 0.95)');
    roundRectPath(lx, railLowerY - capH * 0.5, capW, capH, capH * 0.5);
    ctx.fillStyle = lGrad;
    ctx.fill();
  }

  // 5. Crisp Ground Horizon Datum & Subsurface Clean Smart-Grid Power Foundation
  ctx.fillStyle = '#070A12';
  ctx.fillRect(0, groundY, width, height - groundY);

  ctx.beginPath();
  ctx.moveTo(0, groundY);
  ctx.lineTo(width, groundY);
  ctx.lineWidth = minSide * 0.0035;
  ctx.strokeStyle = mixColor([48, 86, 110], [105, 240, 174], s2Weight * 0.5 + s3Weight * 0.5);
  ctx.stroke();

  // Horizontal clean energy power distribution busbar beneath city towers (y = 0.920*H)
  const busY = height * 0.922;
  ctx.beginPath();
  ctx.moveTo(width * 0.075, busY);
  ctx.lineTo(width * 0.925, busY);
  ctx.lineWidth = minSide * 0.0045;
  ctx.strokeStyle = '#152238';
  ctx.stroke();

  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#40C4FF';
  ctx.stroke();

  for (const b of buildings) {
    const cxTower = width * (b.x0 + b.w * 0.5);
    ctx.beginPath();
    ctx.moveTo(cxTower, groundY);
    ctx.lineTo(cxTower, busY);
    ctx.lineWidth = minSide * 0.0022;
    ctx.strokeStyle = '#2A4B6E';
    ctx.stroke();

    const pulse = 0.5 + 0.5 * Math.sin(TAU * (u * 3 - b.phase));
    ctx.beginPath();
    ctx.arc(cxTower, busY, minSide * 0.0068, 0, TAU);
    ctx.fillStyle = mixColor([40, 96, 132], [105, 240, 174], pulse);
    ctx.fill();
  }

  for (let p = 0; p < 6; p++) {
    const sp = (u * 3 + p / 6) % 1;
    const px = lerp(width * 0.075, width * 0.925, sp);
    ctx.beginPath();
    ctx.arc(px, busY, minSide * 0.0032, 0, TAU);
    ctx.fillStyle = '#FFE082';
    ctx.fill();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function samplePolyline(pts, s) {
    let total = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(len);
      total += len;
    }
    if (total <= 0) return pts[0];
    let target = clamp01(s) * total;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= segLens[i] || i === segLens.length - 1) {
        const local = segLens[i] > 0 ? target / segLens[i] : 0;
        return [
          lerp(pts[i][0], pts[i + 1][0], local),
          lerp(pts[i][1], pts[i + 1][1], local),
        ];
      }
      target -= segLens[i];
    }
    return pts[pts.length - 1];
  }

  // Smooth C-infinity periodic scene emphasis windows across 3 scenes (20s total)
  const s1Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 1 / 6));
  const s2Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 3 / 6));
  const s3Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 5 / 6));

  // 1. Clean Obsidian Tech Dark Modern Background (Zero Background Glow)
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#05060C');
  bgGrad.addColorStop(0.5, '#06070F');
  bgGrad.addColorStop(1, '#04050A');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle floor laboratory plinth bar strictly beneath glasshouse bay
  const floorY = height * 0.915;
  ctx.beginPath();
  ctx.moveTo(width * 0.16, floorY);
  ctx.lineTo(width * 0.84, floorY);
  ctx.lineWidth = minSide * 0.0030;
  ctx.strokeStyle = '#1D223B';
  ctx.stroke();

  // 2. Centered High-Tech Glasshouse Structure (Contained Inside Canvas, Never Touching Screen Borders)
  const cx = width * 0.50;
  const ghLeft = width * 0.215;
  const ghRight = width * 0.785;
  const ghApexY = height * 0.068;
  const ghEaveY = height * 0.145;

  // Glasshouse interior structural silhouette
  ctx.beginPath();
  ctx.moveTo(cx, ghApexY);
  ctx.lineTo(ghRight, ghEaveY);
  ctx.lineTo(ghRight, floorY);
  ctx.lineTo(ghLeft, floorY);
  ctx.lineTo(ghLeft, ghEaveY);
  ctx.closePath();
  const ghFill = ctx.createLinearGradient(0, ghApexY, 0, floorY);
  ghFill.addColorStop(0, '#0B0D1D');
  ghFill.addColorStop(1, '#070914');
  ctx.fillStyle = ghFill;
  ctx.fill();

  ctx.lineWidth = minSide * 0.0028;
  ctx.strokeStyle = mixColor([48, 56, 102], [123, 44, 191], s1Weight * 0.5 + s2Weight * 0.5);
  ctx.stroke();

  // Glasshouse architectural roof trusses
  for (const frac of [0.32, 0.68]) {
    const rx = lerp(ghLeft, ghRight, frac);
    ctx.beginPath();
    ctx.moveTo(cx, ghApexY);
    ctx.lineTo(rx, ghEaveY);
    ctx.lineWidth = minSide * 0.0014;
    ctx.strokeStyle = 'rgba(123, 44, 191, 0.28)';
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(ghLeft, ghEaveY);
  ctx.lineTo(ghRight, ghEaveY);
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = 'rgba(0, 229, 255, 0.24)';
  ctx.stroke();

  // 3. Hydroponic Tower Geometry & Looped Nutrient Piping Network
  const towers = [
    { side: -1, left: width * 0.275, right: width * 0.465 },
    { side: 1,  left: width * 0.535, right: width * 0.725 },
  ];
  const shelves = [
    { ceilingY: height * 0.185, trayY: height * 0.340, phase: 0.00 },
    { ceilingY: height * 0.395, trayY: height * 0.550, phase: 0.14 },
    { ceilingY: height * 0.605, trayY: height * 0.760, phase: 0.28 },
  ];

  const sumpW = width * 0.170;
  const sumpH = height * 0.076;
  const sumpLeft = cx - sumpW * 0.5;
  const sumpTop = height * 0.822;
  const pumpY = sumpTop + sumpH * 0.5;

  const leftDrainX = width * 0.246;
  const rightDrainX = width * 0.754;

  // Transparent Fluid Pipe Helper
  function drawGlassPipe(pts, fillStart, fillEnd) {
    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]);
      else ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.lineWidth = minSide * 0.014;
    ctx.strokeStyle = '#121B36';
    ctx.stroke();

    ctx.lineWidth = minSide * 0.0082;
    ctx.strokeStyle = '#072233';
    ctx.stroke();

    const g = ctx.createLinearGradient(pts[0][0], pts[0][1], pts[pts.length - 1][0], pts[pts.length - 1][1]);
    g.addColorStop(0, fillStart);
    g.addColorStop(1, fillEnd);
    ctx.lineWidth = minSide * 0.0036;
    ctx.strokeStyle = g;
    ctx.stroke();
    ctx.restore();
  }

  // Central Vertical Nutrient Feed Riser Pipe (Sump -> All 3 Tray Levels along clean cx corridor)
  const topTrayFeedY = shelves[0].trayY + minSide * 0.018;
  drawGlassPipe([[cx, sumpTop], [cx, topTrayFeedY]], '#00B8D4', '#00E5FF');

  // Outer Vertical Return Drain Pipes & Bottom Horizontal Return Manifolds back to Sump
  drawGlassPipe(
    [
      [leftDrainX, topTrayFeedY],
      [leftDrainX, pumpY],
      [sumpLeft, pumpY],
    ],
    '#0097A7',
    '#00E5FF'
  );
  drawGlassPipe(
    [
      [rightDrainX, topTrayFeedY],
      [rightDrainX, pumpY],
      [sumpLeft + sumpW, pumpY],
    ],
    '#0097A7',
    '#00E5FF'
  );

  // Horizontal tray feeder pipes connecting Center Riser -> Across Both Trays -> Outer Drains
  const nutrientPaths = [];
  for (let sIdx = 0; sIdx < shelves.length; sIdx++) {
    const py = shelves[sIdx].trayY + minSide * 0.018;
    drawGlassPipe([[cx, py], [leftDrainX, py]], '#00E5FF', '#008BA3');
    drawGlassPipe([[cx, py], [rightDrainX, py]], '#00E5FF', '#008BA3');

    nutrientPaths.push({
      pts: [
        [cx, sumpTop],
        [cx, py],
        [leftDrainX, py],
        [leftDrainX, pumpY],
        [sumpLeft, pumpY],
      ],
      phase: sIdx * 0.22,
    });
    nutrientPaths.push({
      pts: [
        [cx, sumpTop],
        [cx, py],
        [rightDrainX, py],
        [rightDrainX, pumpY],
        [sumpLeft + sumpW, pumpY],
      ],
      phase: sIdx * 0.22 + 0.50,
    });
  }

  // Animated Cyan Nutrient Fluid Pulses & Micro Bubbles Flowing Around Complete Closed Pipe Loop
  for (const np of nutrientPaths) {
    for (let k = 0; k < 2; k++) {
      const p = (u * 3 + np.phase + k * 0.5) % 1;
      const pt = samplePolyline(np.pts, p);
      const sz = minSide * (0.0038 + 0.0014 * s1Weight) * Math.sin(Math.PI * p);
      ctx.beginPath();
      ctx.arc(pt[0], pt[1], sz, 0, TAU);
      ctx.fillStyle = '#84FFFF';
      ctx.fill();
    }
  }

  // Central Reservoir Sump & Active Dual-Impeller Pump Housing
  chamferRectPath(sumpLeft, sumpTop, sumpW, sumpH, minSide * 0.010);
  ctx.fillStyle = '#0C1226';
  ctx.fill();

  ctx.save();
  chamferRectPath(sumpLeft, sumpTop, sumpW, sumpH, minSide * 0.010);
  ctx.clip();
  // Animated Cyan Nutrient Fluid Level inside Reservoir Tank
  const fluidTop = sumpTop + sumpH * (0.34 + 0.05 * Math.sin(TAU * (u * 3)));
  const fluidGrad = ctx.createLinearGradient(0, fluidTop, 0, sumpTop + sumpH);
  fluidGrad.addColorStop(0, '#00E5FF');
  fluidGrad.addColorStop(1, '#006980');
  ctx.fillStyle = fluidGrad;
  ctx.beginPath();
  ctx.moveTo(sumpLeft, sumpTop + sumpH);
  ctx.lineTo(sumpLeft, fluidTop);
  for (let w = 0; w <= 24; w++) {
    const f = w / 24;
    const wx = lerp(sumpLeft, sumpLeft + sumpW, f);
    const wy = fluidTop + minSide * 0.003 * Math.sin(f * TAU * 3 - u * TAU * 4);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(sumpLeft + sumpW, sumpTop + sumpH);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  chamferRectPath(sumpLeft, sumpTop, sumpW, sumpH, minSide * 0.010);
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#00E5FF';
  ctx.stroke();

  // Spinning Pump Impeller Rotor centered inside Sump
  const pumpR = minSide * 0.020;
  ctx.save();
  ctx.translate(cx, pumpY + minSide * 0.004);
  ctx.beginPath();
  ctx.arc(0, 0, pumpR, 0, TAU);
  ctx.fillStyle = '#091826';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#84FFFF';
  ctx.stroke();

  const impAng = TAU * (12 * u + (4 * (Math.sin(TAU * (u - 1 / 6)) - Math.sin(-TAU / 6))) / TAU);
  ctx.rotate(impAng);
  for (let b = 0; b < 4; b++) {
    ctx.rotate(Math.PI * 0.5);
    ctx.beginPath();
    ctx.moveTo(0, -pumpR * 0.16);
    ctx.lineTo(pumpR * 0.72, 0);
    ctx.lineTo(0, pumpR * 0.16);
    ctx.closePath();
    ctx.fillStyle = '#00E5FF';
    ctx.fill();
  }
  ctx.restore();

  // 4. Precision Grow Racks, Magenta-Violet Spectrum Cones, Flora Bloom & Hydration Mist
  // Helper: Draw Multi-Leaf Botanical Hydroponic Rosette (strictly bounded within slot cell!)
  function drawHydroPlant(px, traySurfaceY, bloomFactor, phase) {
    // bloomFactor ranges cleanly ~0.62 -> 1.00 peaking in Scene 2, strictly <= maxCellWidth!
    const h = minSide * (0.044 + 0.030 * bloomFactor);
    const w = minSide * (0.026 + 0.015 * bloomFactor);
    const sway = 0.025 * Math.sin(TAU * (u * 2 + phase));

    // Clean recessed white-cyan hydroponic cup socket on tray top
    roundRectPath(px - minSide * 0.012, traySurfaceY - minSide * 0.006, minSide * 0.024, minSide * 0.010, minSide * 0.003);
    ctx.fillStyle = '#1D2C4D';
    ctx.fill();
    ctx.fillStyle = '#00E5FF';
    ctx.fillRect(px - minSide * 0.010, traySurfaceY - minSide * 0.005, minSide * 0.020, minSide * 0.0022);

    ctx.save();
    ctx.translate(px, traySurfaceY - minSide * 0.006);
    ctx.rotate(sway);

    // 5 Symmetrical Botanical Leaves (Outer lower pair, mid inner pair, central shoot)
    const leafSpecs = [
      { ang: -0.78 * (0.7 + 0.3 * bloomFactor), len: h * 0.68, wid: w * 0.28, cLeft: '#38B000', cRight: '#1F7A00' },
      { ang: 0.78 * (0.7 + 0.3 * bloomFactor),  len: h * 0.68, wid: w * 0.28, cLeft: '#38B000', cRight: '#1F7A00' },
      { ang: -0.40 * (0.75 + 0.25 * bloomFactor), len: h * 0.86, wid: w * 0.30, cLeft: '#70E000', cRight: '#38B000' },
      { ang: 0.40 * (0.75 + 0.25 * bloomFactor),  len: h * 0.86, wid: w * 0.30, cLeft: '#70E000', cRight: '#38B000' },
      { ang: 0.0, len: h, wid: w * 0.32, cLeft: '#9EF01A', cRight: '#38B000' },
    ];

    for (const lf of leafSpecs) {
      ctx.save();
      ctx.rotate(lf.ang);
      // Left lit blade half
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(-lf.wid, -lf.len * 0.35, -lf.wid * 0.85, -lf.len * 0.78, 0, -lf.len);
      ctx.closePath();
      ctx.fillStyle = lf.cLeft;
      ctx.fill();

      // Right shaded blade half
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(lf.wid, -lf.len * 0.35, lf.wid * 0.85, -lf.len * 0.78, 0, -lf.len);
      ctx.closePath();
      ctx.fillStyle = lf.cRight;
      ctx.fill();

      // Crisp chlorophyll center vein
      ctx.beginPath();
      ctx.moveTo(0, -lf.len * 0.08);
      ctx.lineTo(0, -lf.len * 0.86);
      ctx.lineWidth = Math.max(0.9, minSide * 0.0012);
      ctx.strokeStyle = mixColor([112, 224, 0], [216, 243, 220], s2Weight);
      ctx.stroke();

      ctx.restore();
    }

    ctx.restore();
  }

  for (let tIdx = 0; tIdx < towers.length; tIdx++) {
    const tw = towers[tIdx];
    const twW = tw.right - tw.left;

    // Vertical Structural Rack Posts flanking each Grow Tower cleanly
    for (const postX of [tw.left, tw.right - minSide * 0.008]) {
      ctx.fillStyle = '#18203D';
      ctx.fillRect(postX, shelves[0].ceilingY - minSide * 0.012, minSide * 0.008, shelves[2].trayY - shelves[0].ceilingY + minSide * 0.044);
    }

    for (let sIdx = 0; sIdx < shelves.length; sIdx++) {
      const sh = shelves[sIdx];
      const ledIntensity = clamp01(0.45 + 0.55 * (s1Weight * 0.4 + s2Weight * 0.8 + 0.2) * (0.85 + 0.15 * Math.sin(TAU * (u * 2 - sh.phase))));

      // Upper LED Lighting Fixture Rail + Crisp Spectrum Light Cone
      const ledBarX = tw.left + twW * 0.08;
      const ledBarW = twW * 0.84;
      const ledBarH = minSide * 0.012;

      // Crisp Trapezoid Grow-Light Spectrum Cone (Zero Blurry Background Glow!)
      const coneBotY = sh.trayY - minSide * 0.010;
      const coneGrad = ctx.createLinearGradient(0, sh.ceilingY + ledBarH, 0, coneBotY);
      coneGrad.addColorStop(0, `rgba(255, 42, 133, ${(0.22 * ledIntensity).toFixed(4)})`);
      coneGrad.addColorStop(0.55, `rgba(123, 44, 191, ${(0.12 * ledIntensity).toFixed(4)})`);
      coneGrad.addColorStop(1, 'rgba(123, 44, 191, 0)');
      ctx.fillStyle = coneGrad;
      ctx.beginPath();
      ctx.moveTo(ledBarX, sh.ceilingY + ledBarH);
      ctx.lineTo(ledBarX + ledBarW, sh.ceilingY + ledBarH);
      ctx.lineTo(tw.right - twW * 0.02, coneBotY);
      ctx.lineTo(tw.left + twW * 0.02, coneBotY);
      ctx.closePath();
      ctx.fill();

      // Physical LED Bar Housing
      roundRectPath(ledBarX - minSide * 0.004, sh.ceilingY, ledBarW + minSide * 0.008, ledBarH, minSide * 0.004);
      ctx.fillStyle = '#1E1A36';
      ctx.fill();
      roundRectPath(ledBarX, sh.ceilingY + ledBarH * 0.45, ledBarW, ledBarH * 0.42, minSide * 0.002);
      ctx.fillStyle = mixColor([123, 44, 191], [255, 42, 133], ledIntensity);
      ctx.fill();

      // Absorbing Magenta-Violet Photon Particles descending strictly inside cone above plant crowns
      for (let ph = 0; ph < 4; ph++) {
        const pPhase = (u * 3 + ph * 0.25 + sh.phase + tIdx * 0.35) % 1;
        const px = lerp(ledBarX + ledBarW * 0.14, ledBarX + ledBarW * 0.86, (ph + 0.5) / 4);
        const py = lerp(sh.ceilingY + ledBarH * 1.4, sh.trayY - minSide * 0.056, pPhase);
        const pFade = (0.35 + 0.65 * s2Weight) * Math.sin(Math.PI * pPhase);
        ctx.beginPath();
        ctx.arc(px, py, minSide * 0.0028, 0, TAU);
        ctx.fillStyle = ph % 2 === 0 ? `rgba(255, 42, 133, ${pFade.toFixed(3)})` : `rgba(224, 170, 255, ${pFade.toFixed(3)})`;
        ctx.fill();
      }

      // 4 Hydroponic Plants Seated Evenly Along Tray
      const plantCount = 4;
      const trayInnerLeft = tw.left + twW * 0.05;
      const trayInnerW = twW * 0.90;
      const bloomVal = 0.62 + 0.38 * (0.5 + 0.5 * Math.cos(TAU * (u - 0.5))); // Peaks cleanly at u=0.5 (Scene 2!)

      for (let p = 0; p < plantCount; p++) {
        const plantX = lerp(trayInnerLeft + trayInnerW * 0.12, trayInnerLeft + trayInnerW * 0.88, p / (plantCount - 1));
        drawHydroPlant(plantX, sh.trayY, bloomVal, sh.phase + p * 0.13 + tIdx * 0.2);
      }

      // Scene 3 Micro-Mist Hydration Droplets floating strictly in clear air gap under LED fixture
      if (s3Weight > 0.05) {
        for (let m = 0; m < 6; m++) {
          const mp = (u * 3 + m / 6 + sh.phase) % 1;
          const mx = lerp(tw.left + twW * 0.10, tw.right - twW * 0.10, (m + 0.5) / 6) + Math.sin(mp * TAU) * minSide * 0.005;
          const my = lerp(sh.ceilingY + minSide * 0.028, sh.trayY - minSide * 0.075, mp);
          const mAlpha = 0.72 * s3Weight * Math.sin(Math.PI * mp);
          ctx.beginPath();
          ctx.arc(mx, my, minSide * 0.0024, 0, TAU);
          ctx.fillStyle = `rgba(0, 229, 255, ${mAlpha.toFixed(3)})`;
          ctx.fill();
        }
      }

      // Physical Hydroponic Tray Structure & Recessed Glass Nutrient Trough
      const trayH = minSide * 0.028;
      roundRectPath(tw.left, sh.trayY, twW, trayH, minSide * 0.006);
      ctx.fillStyle = '#151E3B';
      ctx.fill();
      ctx.lineWidth = minSide * 0.0018;
      ctx.strokeStyle = '#2E437A';
      ctx.stroke();

      // Cyan nutrient liquid stripe visible inside tray window
      roundRectPath(tw.left + minSide * 0.008, sh.trayY + trayH * 0.45, twW - minSide * 0.016, trayH * 0.34, minSide * 0.003);
      ctx.fillStyle = mixColor([0, 128, 158], [0, 229, 255], s1Weight * 0.7 + 0.3);
      ctx.fill();
    }
  }

  // 5. Flanking Left & Right Precision Climate Telemetry Consoles (Zero Overlap With Pavilion)

  // Left Console (Fluid Circulation, pH Balance, Nutrient EC)
  const lcLeft = width * 0.045;
  const lcW = width * 0.125;
  const lcTop = height * 0.22;
  const lcH = height * 0.56;
  chamferRectPath(lcLeft, lcTop, lcW, lcH, minSide * 0.014);
  ctx.fillStyle = '#0B0E1D';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([48, 64, 118], [0, 229, 255], s1Weight * 0.6 + s3Weight * 0.4);
  ctx.stroke();

  const leftMetrics = [
    { col: '#00E5FF', target: 0.72 + 0.16 * s1Weight },
    { col: '#7B2CBF', target: 0.65 + 0.22 * s2Weight },
    { col: '#38B000', target: 0.58 + 0.32 * s3Weight },
    { col: '#FF2A85', target: 0.62 + 0.24 * s1Weight },
  ];
  for (let m = 0; m < leftMetrics.length; m++) {
    const mx = lerp(lcLeft + lcW * 0.20, lcLeft + lcW * 0.80, m / (leftMetrics.length - 1));
    const mw = lcW * 0.13;
    const mh = lcH * 0.72;
    const my = lcTop + (lcH - mh) * 0.5;
    const wave = 0.04 * Math.sin(TAU * (u * 3 - m * 0.15));
    const val = clamp01(leftMetrics[m].target + wave);

    roundRectPath(mx - mw * 0.5, my, mw, mh, mw * 0.45);
    ctx.fillStyle = '#141933';
    ctx.fill();

    roundRectPath(mx - mw * 0.5, my + mh * (1 - val), mw, mh * val, mw * 0.45);
    ctx.fillStyle = leftMetrics[m].col;
    ctx.fill();
  }

  // Right Console (Moisture Equilibrium Dial & PAR Spectrum Matrix)
  const rcLeft = width * 0.830;
  const rcW = width * 0.125;
  const rcTop = height * 0.22;
  const rcH = height * 0.56;
  chamferRectPath(rcLeft, rcTop, rcW, rcH, minSide * 0.014);
  ctx.fillStyle = '#0B0E1D';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([48, 64, 118], [56, 176, 0], s3Weight * 0.75);
  ctx.stroke();

  // Top Moisture Optimal Dial inside Right Console
  const rDialX = rcLeft + rcW * 0.5;
  const rDialY = rcTop + rcH * 0.28;
  const rDialR = rcW * 0.30;
  const moistEq = clamp01(0.55 + 0.38 * s3Weight + 0.05 * Math.sin(TAU * (u * 2)));

  ctx.beginPath();
  ctx.arc(rDialX, rDialY, rDialR, 0, TAU);
  ctx.fillStyle = '#12172E';
  ctx.fill();

  ctx.beginPath();
  ctx.arc(rDialX, rDialY, rDialR * 0.78, -Math.PI * 0.75, Math.PI * 0.75);
  ctx.lineWidth = minSide * 0.0055;
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#1E274A';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(rDialX, rDialY, rDialR * 0.78, -Math.PI * 0.75, lerp(-Math.PI * 0.75, Math.PI * 0.75, moistEq));
  ctx.lineWidth = minSide * 0.0055;
  ctx.strokeStyle = mixColor([0, 229, 255], [56, 176, 0], s3Weight);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(rDialX, rDialY, rDialR * 0.22, 0, TAU);
  ctx.fillStyle = s3Weight > 0.4 ? '#80ED99' : '#00E5FF';
  ctx.fill();
  ctx.lineCap = 'butt';

  // Bottom 5 Horizontal Spectrum & Humidity Ratio Bars inside Right Console
  const rightBarColors = ['#FF2A85', '#7B2CBF', '#00E5FF', '#38B000', '#80ED99'];
  for (let b = 0; b < 5; b++) {
    const by = lerp(rcTop + rcH * 0.54, rcTop + rcH * 0.88, b / 4);
    const bx = rcLeft + rcW * 0.16;
    const bw = rcW * 0.68;
    const bh = minSide * 0.014;
    const act = clamp01(0.45 + 0.45 * (0.5 + 0.5 * Math.sin(TAU * (u * 3 - b * 0.14))) * (0.55 + 0.45 * Math.max(s2Weight, s3Weight)));

    roundRectPath(bx, by - bh * 0.5, bw, bh, bh * 0.45);
    ctx.fillStyle = '#141933';
    ctx.fill();

    roundRectPath(bx, by - bh * 0.5, bw * act, bh, bh * 0.45);
    ctx.fillStyle = rightBarColors[b];
    ctx.fill();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function samplePolyline(pts, s) {
    let total = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(len);
      total += len;
    }
    if (total <= 0) return pts[0];
    let target = clamp01(s) * total;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= segLens[i] || i === segLens.length - 1) {
        const local = segLens[i] > 0 ? target / segLens[i] : 0;
        return [
          lerp(pts[i][0], pts[i + 1][0], local),
          lerp(pts[i][1], pts[i + 1][1], local),
        ];
      }
      target -= segLens[i];
    }
    return pts[pts.length - 1];
  }

  // Smooth C-infinity periodic scene emphasis windows across the 3 scenes (20s total)
  const s1Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 1 / 6));
  const s2Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 3 / 6));
  const s3Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 5 / 6));

  // Periodic multi-octave surface wave profile (exact integer cycles -> seamless at t=0 & t=20)
  function waveProfile(x, yBase, ampScale, phaseShift, speedMult) {
    const nx = x / width;
    return (
      yBase +
      height * 0.013 * ampScale * Math.sin(nx * TAU * 2.5 - u * TAU * (2 * speedMult) + phaseShift) +
      height * 0.005 * ampScale * Math.cos(nx * TAU * 4.5 - u * TAU * (4 * speedMult) + phaseShift * 1.4)
    );
  }

  const waveAmpBoost = 1 + 0.28 * s1Weight;

  function frontWaveY(x) {
    return waveProfile(x, height * 0.285, waveAmpBoost, 0.0, 1);
  }

  // 1. Clean Abyssal Dark Night Sky & Deep Ocean Gradient (Zero Background Glow)
  const skyGrad = ctx.createLinearGradient(0, 0, 0, height * 0.30);
  skyGrad.addColorStop(0, '#02040A');
  skyGrad.addColorStop(1, '#050C1B');
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle distant dark horizon shelf bands above wave line (clean minimalist sky geometry)
  ctx.fillStyle = '#040A17';
  ctx.fillRect(0, height * 0.23, width, height * 0.08);

  // 2. Layered Surface Ocean Waves (Back Indigo -> Mid Ocean Blue -> Front Bioluminescent Aqua Crest)
  const waveLayers = [
    { yBase: height * 0.258, amp: waveAmpBoost * 0.85, phase: 1.2, speed: 1, fill: '#08183A', stroke: '#1F3A7D' },
    { yBase: height * 0.272, amp: waveAmpBoost * 0.92, phase: 0.6, speed: 1, fill: '#072756', stroke: '#0077FF' },
  ];

  for (const wl of waveLayers) {
    ctx.beginPath();
    ctx.moveTo(0, height);
    for (let i = 0; i <= 64; i++) {
      const px = (i / 64) * width;
      ctx.lineTo(px, waveProfile(px, wl.yBase, wl.amp, wl.phase, wl.speed));
    }
    ctx.lineTo(width, height);
    ctx.closePath();
    ctx.fillStyle = wl.fill;
    ctx.fill();

    ctx.beginPath();
    for (let i = 0; i <= 64; i++) {
      const px = (i / 64) * width;
      const py = waveProfile(px, wl.yBase, wl.amp, wl.phase, wl.speed);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.lineWidth = Math.max(1.2, minSide * 0.0018);
    ctx.strokeStyle = wl.stroke;
    ctx.stroke();
  }

  // Front Ocean Body Fill down to Seabed
  const oceanBodyGrad = ctx.createLinearGradient(0, height * 0.28, 0, height * 0.85);
  oceanBodyGrad.addColorStop(0, '#07356E');
  oceanBodyGrad.addColorStop(0.35, '#042048');
  oceanBodyGrad.addColorStop(0.78, '#031129');
  oceanBodyGrad.addColorStop(1, '#020816');

  ctx.beginPath();
  ctx.moveTo(0, height);
  for (let i = 0; i <= 64; i++) {
    const px = (i / 64) * width;
    ctx.lineTo(px, frontWaveY(px));
  }
  ctx.lineTo(width, height);
  ctx.closePath();
  ctx.fillStyle = oceanBodyGrad;
  ctx.fill();

  // Crisp glowing Aqua crest along Front Wave
  ctx.beginPath();
  for (let i = 0; i <= 64; i++) {
    const px = (i / 64) * width;
    const py = frontWaveY(px);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.lineWidth = minSide * 0.0032;
  ctx.strokeStyle = '#00FFCC';
  ctx.stroke();

  // 3. Underwater Vector Caustics Light Ribbons (Contained Cleanly in Upper Column [0.305*H .. 0.455*H])
  // Strictly clipped below front wave and ending cleanly above turbine rotor arc!
  ctx.save();
  ctx.beginPath();
  for (let i = 0; i <= 64; i++) {
    const px = (i / 64) * width;
    if (i === 0) ctx.moveTo(px, frontWaveY(px));
    else ctx.lineTo(px, frontWaveY(px));
  }
  ctx.lineTo(width, height * 0.468);
  ctx.lineTo(0, height * 0.468);
  ctx.closePath();
  ctx.clip();

  const causticShafts = [
    { baseX: 0.14, wid: 0.065, tilt: 0.08, phase: 0.0 },
    { baseX: 0.30, wid: 0.055, tilt: 0.09, phase: 0.25 },
    { baseX: 0.47, wid: 0.072, tilt: 0.08, phase: 0.50 },
    { baseX: 0.64, wid: 0.058, tilt: 0.09, phase: 0.75 },
    { baseX: 0.80, wid: 0.052, tilt: 0.08, phase: 0.40 },
  ];

  for (const cs of causticShafts) {
    const shift = 0.018 * Math.sin(TAU * (u * 2 + cs.phase));
    const alpha = (0.025 + 0.032 * s2Weight) * (0.55 + 0.45 * Math.cos(TAU * (u * 3 + cs.phase)));
    const tx = width * (cs.baseX + shift);
    const tw = width * cs.wid;
    const bx = tx + width * cs.tilt;
    const bw = tw * 1.45;

    const cGrad = ctx.createLinearGradient(tx, height * 0.28, bx, height * 0.468);
    cGrad.addColorStop(0, `rgba(0, 255, 204, ${(alpha * 1.15).toFixed(4)})`);
    cGrad.addColorStop(0.65, `rgba(0, 119, 255, ${(alpha * 0.65).toFixed(4)})`);
    cGrad.addColorStop(1, 'rgba(0, 119, 255, 0)');
    ctx.fillStyle = cGrad;

    ctx.beginPath();
    ctx.moveTo(tx, height * 0.27);
    ctx.lineTo(tx + tw, height * 0.27);
    ctx.lineTo(bx + bw, height * 0.468);
    ctx.lineTo(bx, height * 0.468);
    ctx.closePath();
    ctx.fill();
  }

  // Crisp subtle horizontal vector caustic mesh waves
  for (let cw = 0; cw < 2; cw++) {
    ctx.beginPath();
    for (let i = 0; i <= 56; i++) {
      const nx = i / 56;
      const px = nx * width;
      const py = height * (0.345 + cw * 0.042) + height * 0.008 * Math.sin(nx * TAU * 5 - u * TAU * 3 + cw * 1.5);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
    ctx.strokeStyle = `rgba(0, 255, 204, ${(0.12 + 0.16 * s2Weight).toFixed(3)})`;
    ctx.stroke();
  }
  ctx.restore();

  // 4. Tidal Current Flow Lanes & Micro-Bubbles (Clean Unobstructed Horizontal Band [0.380*H .. 0.455*H])
  // Carefully routed completely above turbine blades and left of Buoy Riser Cable (x = 0.875*W)
  const currentLanes = [
    { yBase: height * 0.375, amp: height * 0.009, phase: 0.0, cycles: 2 },
    { yBase: height * 0.412, amp: height * 0.008, phase: 0.35, cycles: 3 },
    { yBase: height * 0.448, amp: height * 0.007, phase: 0.70, cycles: 2 },
  ];

  for (let cl = 0; cl < currentLanes.length; cl++) {
    const lane = currentLanes[cl];
    const pts = [];
    for (let i = 0; i <= 40; i++) {
      const f = i / 40;
      const px = lerp(width * 0.05, width * 0.78, f);
      const py = lane.yBase + lane.amp * Math.sin(f * TAU * 3 - u * TAU * lane.cycles + lane.phase * TAU);
      pts.push([px, py]);
    }

    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]);
      else ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.lineWidth = minSide * 0.0018;
    ctx.strokeStyle = `rgba(0, 119, 255, ${(0.22 + 0.25 * s1Weight).toFixed(3)})`;
    ctx.stroke();

    // Flowing tidal energy dash ribbons & micro-bubbles along each current path
    for (let p = 0; p < 3; p++) {
      const s = (u * lane.cycles + p / 3 + lane.phase) % 1;
      const head = samplePolyline(pts, s);
      const tail = samplePolyline(pts, Math.max(0, s - 0.08));
      const fade = Math.sin(Math.PI * s);

      const g = ctx.createLinearGradient(tail[0], tail[1], head[0], head[1]);
      g.addColorStop(0, 'rgba(0, 255, 204, 0)');
      g.addColorStop(1, `rgba(0, 255, 204, ${(0.88 * fade).toFixed(3)})`);

      ctx.beginPath();
      ctx.moveTo(tail[0], tail[1]);
      ctx.lineTo(head[0], head[1]);
      ctx.lineWidth = minSide * 0.0032;
      ctx.lineCap = 'round';
      ctx.strokeStyle = g;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(head[0], head[1], minSide * 0.0036 * fade, 0, TAU);
      ctx.fillStyle = '#00FFCC';
      ctx.fill();
    }
  }
  ctx.lineCap = 'butt';

  // 5. Stepped Abyssal Seabed Terraces & Subsea Conduit Rock Layer
  // Clean tiered seabed shelves matching the 4 turbine pedestals + deeper rock strata
  const turbines = [
    { xRatio: 0.155, hubYRatio: 0.590, shelfYRatio: 0.765, phase: 0.00 },
    { xRatio: 0.335, hubYRatio: 0.568, shelfYRatio: 0.742, phase: 0.18 },
    { xRatio: 0.515, hubYRatio: 0.602, shelfYRatio: 0.778, phase: 0.36 },
    { xRatio: 0.695, hubYRatio: 0.578, shelfYRatio: 0.752, phase: 0.54 },
  ];

  // Upper stepped seabed contour polygon
  ctx.fillStyle = '#061124';
  ctx.beginPath();
  ctx.moveTo(0, height * 0.785);
  ctx.lineTo(width * 0.08, height * 0.765);
  ctx.lineTo(width * 0.23, height * 0.765);
  ctx.lineTo(width * 0.26, height * 0.742);
  ctx.lineTo(width * 0.41, height * 0.742);
  ctx.lineTo(width * 0.44, height * 0.778);
  ctx.lineTo(width * 0.59, height * 0.778);
  ctx.lineTo(width * 0.62, height * 0.752);
  ctx.lineTo(width * 0.79, height * 0.752);
  ctx.lineTo(width * 0.84, height * 0.782);
  ctx.lineTo(width, height * 0.782);
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();
  ctx.fill();

  // Crisp top seabed ridge outline
  ctx.beginPath();
  ctx.moveTo(0, height * 0.785);
  ctx.lineTo(width * 0.08, height * 0.765);
  ctx.lineTo(width * 0.23, height * 0.765);
  ctx.lineTo(width * 0.26, height * 0.742);
  ctx.lineTo(width * 0.41, height * 0.742);
  ctx.lineTo(width * 0.44, height * 0.778);
  ctx.lineTo(width * 0.59, height * 0.778);
  ctx.lineTo(width * 0.62, height * 0.752);
  ctx.lineTo(width * 0.79, height * 0.752);
  ctx.lineTo(width * 0.84, height * 0.782);
  ctx.lineTo(width, height * 0.782);
  ctx.lineWidth = minSide * 0.0028;
  ctx.strokeStyle = '#15346B';
  ctx.stroke();

  // Deep bedrock sub-layer housing the horizontal subsea power trunk
  ctx.fillStyle = '#040B1A';
  ctx.beginPath();
  ctx.moveTo(0, height * 0.832);
  ctx.lineTo(width * 0.30, height * 0.822);
  ctx.lineTo(width * 0.65, height * 0.838);
  ctx.lineTo(width, height * 0.824);
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();
  ctx.fill();

  // 6. Subsea Power Grid Conduit Trunk & Vertical Risers
  const trunkY = height * 0.892;
  const buoyX = width * 0.875;
  const buoySurfaceY = frontWaveY(buoyX);
  const dxSlope = 4;
  const dySlope = frontWaveY(buoyX + dxSlope) - frontWaveY(buoyX - dxSlope);
  const buoyTilt = Math.atan2(dySlope, dxSlope * 2) * 0.65;

  // Compute exact world anchor on bottom of floating buoy keel
  const keelLocalY = minSide * 0.036;
  const buoyBottomX = buoyX - Math.sin(buoyTilt) * keelLocalY;
  const buoyBottomY = buoySurfaceY + Math.cos(buoyTilt) * keelLocalY;

  function drawPowerPipe(pts) {
    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]);
      else ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.lineWidth = minSide * 0.014;
    ctx.strokeStyle = '#0D1E40';
    ctx.stroke();

    ctx.lineWidth = minSide * 0.0046;
    ctx.strokeStyle = mixColor([24, 92, 185], [0, 255, 204], s3Weight * 0.85);
    ctx.stroke();
    ctx.restore();
  }

  // Horizontal subsea trunk spanning from Turbine 0 drop -> Buoy riser turn
  const t0X = width * turbines[0].xRatio;
  drawPowerPipe([
    [t0X, trunkY],
    [buoyX, trunkY],
    [buoyBottomX, buoyBottomY],
  ]);

  // Vertical power drops from each turbine foundation straight down into subsea trunk
  for (let i = 0; i < turbines.length; i++) {
    const tb = turbines[i];
    const tx = width * tb.xRatio;
    const shelfY = height * tb.shelfYRatio;
    const dropPts = [
      [tx, shelfY],
      [tx, trunkY],
    ];
    drawPowerPipe(dropPts);

    // Subsea trunk junction hex collar
    ctx.beginPath();
    ctx.arc(tx, trunkY, minSide * 0.011, 0, TAU);
    ctx.fillStyle = '#091A3B';
    ctx.fill();
    ctx.lineWidth = minSide * 0.0024;
    ctx.strokeStyle = mixColor([0, 119, 255], [0, 255, 204], s3Weight);
    ctx.stroke();

    // Animated power pulses rushing down drop -> across trunk -> up buoy riser!
    const fullCablePath = [
      [tx, shelfY],
      [tx, trunkY],
      [buoyX, trunkY],
      [buoyBottomX, buoyBottomY],
    ];
    for (let pk = 0; pk < 2; pk++) {
      const p = (u * 3 + pk * 0.5 + tb.phase) % 1;
      const pt = samplePolyline(fullCablePath, p);
      const sz = minSide * (0.0042 + 0.0018 * s3Weight) * Math.sin(Math.PI * p);
      ctx.beginPath();
      ctx.arc(pt[0], pt[1], sz, 0, TAU);
      ctx.fillStyle = '#00FFCC';
      ctx.fill();
    }
  }

  // 7. Four Hydrokinetic Seabed Turbines + Downstream Wake Rings
  // Exact 10 full rotations in 20s, accelerating cleanly in Scene 2 (u = 0.50)
  const rotorR = minSide * 0.085;
  const nTotalRev = 10;
  const boostAmp = 4;
  const turbAngleBase =
    TAU *
    (nTotalRev * u +
      (boostAmp * (Math.sin(TAU * (u - 0.5)) - Math.sin(-Math.PI))) / TAU);

  for (let i = 0; i < turbines.length; i++) {
    const tb = turbines[i];
    const tx = width * tb.xRatio;
    const ty = height * tb.hubYRatio;
    const shelfY = height * tb.shelfYRatio;

    // Downstream hydrodynamic vortex arcs strictly in open corridor to the right of nacelle
    for (let w = 0; w < 3; w++) {
      const wPhase = (u * 3 + w / 3 + tb.phase) % 1;
      const wx = tx + lerp(rotorR * 0.56, rotorR * 1.45, wPhase);
      const wy = ty + minSide * 0.005 * Math.sin(wPhase * TAU);
      const wRadius = rotorR * lerp(0.28, 0.56, wPhase);
      const wAlpha = (0.32 + 0.68 * s2Weight) * Math.sin(Math.PI * wPhase);

      ctx.beginPath();
      ctx.arc(wx, wy, wRadius, -0.62, 0.62);
      ctx.lineWidth = minSide * 0.0024;
      ctx.lineCap = 'round';
      ctx.strokeStyle = `rgba(0, 255, 204, ${(wAlpha * 0.78).toFixed(3)})`;
      ctx.stroke();
    }
    ctx.lineCap = 'butt';

    // Machined subsea foundation plinth seated flush on terraced shelfY
    const padW = minSide * 0.088;
    const padH = minSide * 0.022;
    chamferRectPath(tx - padW * 0.5, shelfY - padH, padW, padH, minSide * 0.006);
    ctx.fillStyle = '#0D1C3D';
    ctx.fill();
    ctx.lineWidth = minSide * 0.0020;
    ctx.strokeStyle = '#3D5AFE';
    ctx.stroke();

    // Tapered Hydrodynamic Pylon connecting foundation plinth straight up into nacelle
    const pylonTopW = minSide * 0.018;
    const pylonBotW = minSide * 0.034;
    ctx.beginPath();
    ctx.moveTo(tx - pylonBotW * 0.5, shelfY - padH);
    ctx.lineTo(tx - pylonTopW * 0.5, ty);
    ctx.lineTo(tx + pylonTopW * 0.5, ty);
    ctx.lineTo(tx + pylonBotW * 0.5, shelfY - padH);
    ctx.closePath();
    const pylonGrad = ctx.createLinearGradient(tx - pylonBotW, ty, tx + pylonBotW, shelfY);
    pylonGrad.addColorStop(0, '#122959');
    pylonGrad.addColorStop(1, '#0A1636');
    ctx.fillStyle = pylonGrad;
    ctx.fill();

    // Pylon central illuminated power bus vein
    ctx.beginPath();
    ctx.moveTo(tx, ty + minSide * 0.012);
    ctx.lineTo(tx, shelfY - padH);
    ctx.lineWidth = minSide * 0.0032;
    ctx.strokeStyle = mixColor([0, 119, 255], [0, 255, 204], s3Weight);
    ctx.stroke();

    // Hydrokinetic Stator Nacelle Housing with Active Torque Meter Ring
    ctx.beginPath();
    ctx.arc(tx, ty, minSide * 0.024, 0, TAU);
    ctx.fillStyle = '#0F224A';
    ctx.fill();
    ctx.lineWidth = minSide * 0.0024;
    ctx.strokeStyle = mixColor([0, 119, 255], [0, 255, 204], s2Weight * 0.6 + s3Weight * 0.4);
    ctx.stroke();

    // 3 Symmetrical Aerodynamic Hydrokinetic Rotor Blades
    const angle = turbAngleBase + tb.phase * TAU;
    ctx.save();
    ctx.translate(tx, ty);
    ctx.rotate(angle);

    for (let b = 0; b < 3; b++) {
      ctx.save();
      ctx.rotate((b / 3) * TAU);

      ctx.beginPath();
      ctx.moveTo(-minSide * 0.0055, -minSide * 0.014);
      ctx.quadraticCurveTo(-minSide * 0.016, -rotorR * 0.58, -minSide * 0.0035, -rotorR);
      ctx.lineTo(minSide * 0.0045, -rotorR);
      ctx.quadraticCurveTo(minSide * 0.010, -rotorR * 0.50, minSide * 0.0055, -minSide * 0.014);
      ctx.closePath();

      const bladeGrad = ctx.createLinearGradient(0, -minSide * 0.014, 0, -rotorR);
      bladeGrad.addColorStop(0, '#0077FF');
      bladeGrad.addColorStop(0.6, '#00B8D4');
      bladeGrad.addColorStop(1, '#00FFCC');
      ctx.fillStyle = bladeGrad;
      ctx.fill();

      ctx.lineWidth = Math.max(1.0, minSide * 0.0012);
      ctx.strokeStyle = '#84FFFF';
      ctx.stroke();

      ctx.restore();
    }

    // Center Nose Spinner Hub
    ctx.beginPath();
    ctx.arc(0, 0, minSide * 0.014, 0, TAU);
    ctx.fillStyle = '#15326B';
    ctx.fill();
    ctx.lineWidth = minSide * 0.0022;
    ctx.strokeStyle = '#00FFCC';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, minSide * 0.0055, 0, TAU);
    ctx.fillStyle = '#00FFCC';
    ctx.fill();

    ctx.restore();
  }

  // 8. Floating Surface Energy Transmitter Buoy Station (Anchored Cleanly to Wave & Riser Cable)
  ctx.save();
  ctx.translate(buoyX, buoySurfaceY);
  ctx.rotate(buoyTilt);

  // Submerged ballast keel & cable mooring collar
  const keelW = minSide * 0.032;
  const keelH = minSide * 0.036;
  roundRectPath(-keelW * 0.5, 0, keelW, keelH, minSide * 0.006);
  ctx.fillStyle = '#0E1F45';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#0077FF';
  ctx.stroke();

  // Main Buoy Float Hull straddling waterline cleanly
  const hullW = minSide * 0.098;
  const hullH = minSide * 0.030;
  chamferRectPath(-hullW * 0.5, -hullH * 0.55, hullW, hullH, minSide * 0.008);
  const hullGrad = ctx.createLinearGradient(-hullW * 0.5, 0, hullW * 0.5, 0);
  hullGrad.addColorStop(0, '#132A5C');
  hullGrad.addColorStop(0.5, '#1B3D82');
  hullGrad.addColorStop(1, '#10244F');
  ctx.fillStyle = hullGrad;
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([0, 119, 255], [0, 255, 204], s3Weight);
  ctx.stroke();

  // Buoy Waterline Charge Strip (3 LED segments pulsing strongly in Scene 3)
  for (let seg = -1; seg <= 1; seg++) {
    const sx = seg * minSide * 0.022;
    const active = clamp01(0.35 + 0.65 * s3Weight * (0.5 + 0.5 * Math.sin(TAU * (u * 4 - seg * 0.16))));
    roundRectPath(sx - minSide * 0.008, -hullH * 0.25, minSide * 0.016, minSide * 0.009, minSide * 0.003);
    ctx.fillStyle = mixColor([18, 62, 128], [0, 255, 204], active);
    ctx.fill();
  }

  // Lattice Transmitter Mast & Beacon Core rising cleanly into night sky
  const mastBotY = -hullH * 0.55;
  const mastTopY = mastBotY - minSide * 0.095;
  ctx.beginPath();
  ctx.moveTo(-minSide * 0.018, mastBotY);
  ctx.lineTo(-minSide * 0.005, mastTopY);
  ctx.lineTo(minSide * 0.005, mastTopY);
  ctx.lineTo(minSide * 0.018, mastBotY);
  ctx.closePath();
  ctx.fillStyle = '#142C61';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#3D5AFE';
  ctx.stroke();

  // Beacon emitter core
  ctx.beginPath();
  ctx.arc(0, mastTopY, minSide * 0.010, 0, TAU);
  ctx.fillStyle = mixColor([0, 140, 255], [0, 255, 204], s3Weight);
  ctx.fill();
  ctx.lineWidth = minSide * 0.0020;
  ctx.strokeStyle = '#FFFFFF';
  ctx.stroke();

  // Expanding clean vector broadcast signal arcs into unobstructed upper sky
  for (let arc = 0; arc < 3; arc++) {
    const ap = (u * 3 + arc / 3) % 1;
    const ar = minSide * lerp(0.018, 0.072, ap);
    const aAlpha = (0.35 + 0.65 * s3Weight) * (1 - ap);
    ctx.beginPath();
    ctx.arc(0, mastTopY, ar, -Math.PI * 0.82, -Math.PI * 0.18);
    ctx.lineWidth = minSide * 0.0022;
    ctx.lineCap = 'round';
    ctx.strokeStyle = `rgba(0, 255, 204, ${aAlpha.toFixed(3)})`;
    ctx.stroke();
  }

  ctx.restore();
  ctx.restore();
}

function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  // Smooth C-infinity periodic scene emphasis across the 4 scenes (5s each over 20s)
  const s1Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 1 / 8));
  const s2Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 3 / 8));
  const s3Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 5 / 8));
  const s4Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 7 / 8));

  // 1. Clean Dark Slate Modern Background (Zero Glow Effect on Background)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#070A10');
  bgGrad.addColorStop(0.5, '#080B12');
  bgGrad.addColorStop(1, '#05080D');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle geometric precision dot grid background in open canvas (ultra-subtle, no border frame)
  const gridSpacing = minSide * 0.065;
  ctx.fillStyle = 'rgba(83, 109, 254, 0.075)';
  const cols = Math.floor(width / gridSpacing);
  const rows = Math.floor(height / gridSpacing);
  const offX = (width - (cols - 1) * gridSpacing) * 0.5;
  const offY = (height - (rows - 1) * gridSpacing) * 0.5;
  for (let gx = 1; gx < cols - 1; gx++) {
    for (let gy = 1; gy < rows - 1; gy++) {
      ctx.fillRect(offX + gx * gridSpacing - 1, offY + gy * gridSpacing - 1, 2, 2);
    }
  }

  // 2. Parametric Closed-Loop Rounded Stadium Track (Constant Arc-Length Speed)
  const cx = width * 0.50;
  const cy = height * 0.50;
  const hx = width * 0.185; // Half straight horizontal length
  const rLoop = height * 0.245; // Radius of left & right semicircle arcs
  const straightLen = hx * 2;
  const arcLen = Math.PI * rLoop;
  const totalPerim = 2 * straightLen + 2 * arcLen;

  // s = 0 starts cleanly at Left Arc Midpoint (x = cx - hx - rLoop, y = cy) going Clockwise!
  function sampleStadium(sRaw) {
    const s = ((sRaw % 1) + 1) % 1;
    const dist = s * totalPerim;

    // Segment A: Upper half of Left Semicircle (angle PI -> 3*PI/2, moving up & right)
    if (dist < arcLen * 0.5) {
      const a = Math.PI + (dist / (arcLen * 0.5)) * (Math.PI * 0.5);
      return {
        x: cx - hx + Math.cos(a) * rLoop,
        y: cy + Math.sin(a) * rLoop,
        angle: a + Math.PI * 0.5,
      };
    }
    let d = dist - arcLen * 0.5;

    // Segment B: Top Straight Rail (moving left -> right)
    if (d < straightLen) {
      return {
        x: lerp(cx - hx, cx + hx, d / straightLen),
        y: cy - rLoop,
        angle: 0,
      };
    }
    d -= straightLen;

    // Segment C: Right Semicircle (-PI/2 -> +PI/2, moving clockwise top -> bottom)
    if (d < arcLen) {
      const a = -Math.PI * 0.5 + (d / arcLen) * Math.PI;
      return {
        x: cx + hx + Math.cos(a) * rLoop,
        y: cy + Math.sin(a) * rLoop,
        angle: a + Math.PI * 0.5,
      };
    }
    d -= arcLen;

    // Segment D: Bottom Straight Rail (moving right -> left)
    if (d < straightLen) {
      return {
        x: lerp(cx + hx, cx - hx, d / straightLen),
        y: cy + rLoop,
        angle: Math.PI,
      };
    }
    d -= straightLen;

    // Segment E: Lower half of Left Semicircle (+PI/2 -> PI, closing smoothly to s = 0)
    const a = Math.PI * 0.5 + (d / (arcLen * 0.5)) * (Math.PI * 0.5);
    return {
      x: cx - hx + Math.cos(a) * rLoop,
      y: cy + Math.sin(a) * rLoop,
      angle: a + Math.PI * 0.5,
    };
  }

  function traceStadiumContour(offsetR) {
    const r = rLoop + offsetR;
    ctx.beginPath();
    ctx.moveTo(cx - hx, cy - r);
    ctx.lineTo(cx + hx, cy - r);
    ctx.arc(cx + hx, cy, r, -Math.PI * 0.5, Math.PI * 0.5, false);
    ctx.lineTo(cx - hx, cy + r);
    ctx.arc(cx - hx, cy, r, Math.PI * 0.5, Math.PI * 1.5, false);
    ctx.closePath();
  }

  // Outer recessed bezel & crisp dual guide rails of the closed loop
  traceStadiumContour(0);
  ctx.lineWidth = minSide * 0.048;
  ctx.strokeStyle = '#0F1522';
  ctx.stroke();

  traceStadiumContour(minSide * 0.024);
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#202C44';
  ctx.stroke();

  traceStadiumContour(-minSide * 0.024);
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#202C44';
  ctx.stroke();

  // Animated chromatic directional track centerline gradient (smooth energy transfer rail)
  const trackGrad = ctx.createLinearGradient(cx - hx - rLoop, cy, cx + hx + rLoop, cy);
  trackGrad.addColorStop(0, '#FFD740');
  trackGrad.addColorStop(0.35, '#FF6E40');
  trackGrad.addColorStop(0.70, '#26C6DA');
  trackGrad.addColorStop(1, '#536DFE');

  traceStadiumContour(0);
  ctx.lineWidth = minSide * 0.0055;
  ctx.strokeStyle = trackGrad;
  ctx.globalAlpha = 0.45 + 0.35 * Math.max(s1Weight, s2Weight, s3Weight, s4Weight);
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Flowing directional energy dashes moving clockwise smoothly around stadium centerline
  ctx.save();
  traceStadiumContour(0);
  const dashLen = minSide * 0.022;
  const gapLen = minSide * 0.040;
  const dashPeriod = dashLen + gapLen;
  // Exact integer dash cycles fitting along track perimeter for 100% seamless loop
  const cycleMult = Math.round(totalPerim / dashPeriod);
  const exactPeriod = totalPerim / cycleMult;
  ctx.setLineDash([exactPeriod * 0.36, exactPeriod * 0.64]);
  ctx.lineDashOffset = -(u * exactPeriod * 8);
  ctx.lineWidth = minSide * 0.0032;
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#FFD740';
  ctx.stroke();
  ctx.restore();

  // 3. Central Efficiency Radar Console (Strictly Contained Inside Courtyard Gap)
  const radR = minSide * 0.142;

  // Radar Outer Base Ring
  ctx.beginPath();
  ctx.arc(cx, cy, radR, 0, TAU);
  ctx.fillStyle = '#0B101B';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0028;
  ctx.strokeStyle = '#23324D';
  ctx.stroke();

  // Inner concentric measurement circles
  for (const frac of [0.76, 0.50, 0.24]) {
    ctx.beginPath();
    ctx.arc(cx, cy, radR * frac, 0, TAU);
    ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
    ctx.strokeStyle = 'rgba(83, 109, 254, 0.28)';
    ctx.stroke();
  }

  // Symmetrical crosshair axes inside radar
  ctx.beginPath();
  ctx.moveTo(cx - radR * 0.85, cy);
  ctx.lineTo(cx + radR * 0.85, cy);
  ctx.moveTo(cx, cy - radR * 0.85);
  ctx.lineTo(cx, cy + radR * 0.85);
  ctx.lineWidth = Math.max(1.0, minSide * 0.0012);
  ctx.strokeStyle = 'rgba(38, 198, 218, 0.22)';
  ctx.stroke();

  // Synchronized Rotating Radar Sweep Pie Sector (2 exact clockwise rotations per 20s)
  const sweepAng = u * TAU * 2 - Math.PI * 0.5;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(sweepAng);
  const sweepGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, radR * 0.86);
  sweepGrad.addColorStop(0, 'rgba(38, 198, 218, 0.05)');
  sweepGrad.addColorStop(1, 'rgba(38, 198, 218, 0.26)');
  ctx.fillStyle = sweepGrad;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.arc(0, 0, radR * 0.86, -0.58, 0);
  ctx.closePath();
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(radR * 0.86, 0);
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = '#26C6DA';
  ctx.stroke();
  ctx.restore();

  // Periodic concentric efficiency pulse wave expanding strictly inside radar ring
  for (let pw = 0; pw < 2; pw++) {
    const pPhase = (u * 4 + pw * 0.5) % 1;
    const pRad = radR * lerp(0.18, 0.86, pPhase);
    ctx.beginPath();
    ctx.arc(cx, cy, pRad, 0, TAU);
    ctx.lineWidth = minSide * 0.0020;
    ctx.strokeStyle = `rgba(255, 215, 64, ${(0.55 * (1 - pPhase)).toFixed(3)})`;
    ctx.stroke();
  }

  // 4 Quadrant Efficiency Arcs along Radar Perimeter synced with 4 Scenes
  const quadColors = ['#FFD740', '#FF6E40', '#26C6DA', '#536DFE'];
  const quadWeights = [s1Weight, s2Weight, s3Weight, s4Weight];
  for (let q = 0; q < 4; q++) {
    const baseA = Math.PI + q * (Math.PI * 0.5);
    const active = quadWeights[q];
    const span = Math.PI * 0.36;
    const midA = baseA + Math.PI * 0.25;
    ctx.beginPath();
    ctx.arc(cx, cy, radR * 0.92, midA - span * 0.5, midA + span * 0.5);
    ctx.lineWidth = minSide * lerp(0.0032, 0.0064, active);
    ctx.lineCap = 'round';
    ctx.strokeStyle = quadColors[q];
    ctx.globalAlpha = 0.35 + 0.65 * active;
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Radar center hub
  ctx.beginPath();
  ctx.arc(cx, cy, radR * 0.14, 0, TAU);
  ctx.fillStyle = '#151E30';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#26C6DA';
  ctx.stroke();

  // 4. Four Cleanly Separated Modular Stations (Non-Overlapping Around Loop Perimeter)

  // STATION 1 (Left Exterior Intake Module: x = 0.035*W .. 0.125*W, coupled cleanly to Left Track Apex)
  const st1Left = width * 0.036;
  const st1W = width * 0.088;
  const st1Top = cy - height * 0.16;
  const st1H = height * 0.32;
  const leftApexX = cx - hx - rLoop;

  // Feeder bridge pipe from Station 1 right wall -> Left Track Entry Flange
  roundRectPath(st1Left + st1W - minSide * 0.004, cy - minSide * 0.012, leftApexX - minSide * 0.024 - (st1Left + st1W) + minSide * 0.008, minSide * 0.024, minSide * 0.004);
  ctx.fillStyle = '#182133';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(st1Left + st1W, cy);
  ctx.lineTo(leftApexX - minSide * 0.026, cy);
  ctx.lineWidth = minSide * 0.0042;
  ctx.strokeStyle = mixColor([80, 95, 130], [255, 215, 64], s1Weight);
  ctx.stroke();

  chamferRectPath(st1Left, st1Top, st1W, st1H, minSide * 0.014);
  ctx.fillStyle = '#0D1320';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = mixColor([48, 64, 96], [255, 215, 64], s1Weight * 0.85);
  ctx.stroke();

  // Metered raw material inventory cells inside Station 1 (5 clean horizontal cells pulsing in Scene 1)
  for (let b = 0; b < 5; b++) {
    const by = lerp(st1Top + st1H * 0.16, st1Top + st1H * 0.84, b / 4);
    const cellW = st1W * 0.68;
    const cellH = minSide * 0.016;
    const pulse = 0.5 + 0.5 * Math.sin(TAU * (u * 4 - b * 0.14));
    const fillFrac = clamp01(0.35 + 0.55 * s1Weight * (0.5 + 0.5 * pulse));

    roundRectPath(st1Left + st1W * 0.16, by - cellH * 0.5, cellW, cellH, cellH * 0.35);
    ctx.fillStyle = '#151E30';
    ctx.fill();

    roundRectPath(st1Left + st1W * 0.16, by - cellH * 0.5, cellW * fillFrac, cellH, cellH * 0.35);
    ctx.fillStyle = b % 2 === 0 ? '#FFD740' : '#FF6E40';
    ctx.fill();
  }

  // STATION 2 (Top Precision Mechanical Assembly Gantry & Twin Robotic Vector Arms, Strictly Above Top Rail)
  const gantryY = height * 0.072;
  const gantryW = width * 0.28;
  const gantryH = height * 0.068;
  chamferRectPath(cx - gantryW * 0.5, gantryY, gantryW, gantryH, minSide * 0.012);
  ctx.fillStyle = '#0D1320';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([48, 64, 96], [255, 110, 64], s2Weight * 0.85);
  ctx.stroke();

  // Precision assembly synchronization bars cleanly housed inside Top Gantry
  const gantryBars = 5;
  for (let gb = 0; gb < gantryBars; gb++) {
    const gx = lerp(cx - gantryW * 0.36, cx + gantryW * 0.36, gb / (gantryBars - 1));
    const gw = gantryW * 0.11;
    const gh = gantryH * 0.42;
    const gy = gantryY + (gantryH - gh) * 0.5;
    const gPulse = 0.5 + 0.5 * Math.sin(TAU * (u * 4 - gb * 0.16));
    const gFill = clamp01(0.32 + 0.68 * s2Weight * (0.4 + 0.6 * gPulse));
    roundRectPath(gx - gw * 0.5, gy, gw, gh, minSide * 0.004);
    ctx.fillStyle = '#151E30';
    ctx.fill();
    roundRectPath(gx - gw * 0.5, gy, gw * gFill, gh, minSide * 0.004);
    ctx.fillStyle = gb === 2 ? '#FFD740' : '#FF6E40';
    ctx.fill();
  }

  // Twin Symmetrical Precision Robotic Arms reaching cleanly down toward top rail without intersecting track
  const armTopY = gantryY + gantryH;
  const topRailClearY = cy - rLoop - minSide * 0.044;
  for (const side of [-1, 1]) {
    const shoulderX = cx + side * width * 0.088;
    const shoulderY = armTopY;
    const armPhase = u * TAU * 4 + (side === 1 ? 0.5 : 0);
    const elbowX = shoulderX + side * minSide * 0.014 + Math.sin(armPhase) * minSide * 0.008;
    const elbowY = lerp(shoulderY, topRailClearY, 0.52);
    const wristX = cx + side * width * 0.044 + Math.sin(armPhase + 0.6) * minSide * 0.010;
    const wristY = topRailClearY - minSide * (0.010 + 0.005 * (1 - s2Weight));

    // Upper & forearm linkages
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(shoulderX, shoulderY);
    ctx.lineTo(elbowX, elbowY);
    ctx.lineTo(wristX, wristY);
    ctx.lineWidth = minSide * 0.0085;
    ctx.strokeStyle = '#25334F';
    ctx.stroke();

    ctx.lineWidth = minSide * 0.0030;
    ctx.strokeStyle = mixColor([110, 128, 165], [255, 110, 64], s2Weight);
    ctx.stroke();

    // Precision joints
    for (const [jx, jy, jr] of [
      [shoulderX, shoulderY, 0.0095],
      [elbowX, elbowY, 0.0075],
      [wristX, wristY, 0.0070],
    ]) {
      ctx.beginPath();
      ctx.arc(jx, jy, minSide * jr, 0, TAU);
      ctx.fillStyle = '#151E30';
      ctx.fill();
      ctx.lineWidth = minSide * 0.0020;
      ctx.strokeStyle = '#FFD740';
      ctx.stroke();
    }

    // Precision calibration optical laser cone down to top rail (non-destructive crisp dashed line)
    if (s2Weight > 0.08) {
      ctx.beginPath();
      ctx.moveTo(wristX, wristY + minSide * 0.008);
      ctx.lineTo(cx + side * width * 0.022, cy - rLoop - minSide * 0.012);
      ctx.lineWidth = minSide * 0.0018;
      ctx.strokeStyle = `rgba(255, 110, 64, ${(0.65 * s2Weight).toFixed(3)})`;
      ctx.stroke();
    }
  }
  ctx.lineCap = 'butt';

  // STATION 3 (Right Optical Scanner Gate & Sorting Telemetry Console)
  const rightApexX = cx + hx + rLoop;
  const gateOpen = minSide * 0.112;
  // Inner and outer gate pylons strictly clear of curved track inner/outer rails
  const gateInnerX = rightApexX - gateOpen * 0.5;
  const gateOuterX = rightApexX + gateOpen * 0.5;
  const gateHalfH = minSide * 0.052;

  for (const px of [gateInnerX, gateOuterX]) {
    roundRectPath(px - minSide * 0.007, cy - gateHalfH, minSide * 0.014, gateHalfH * 2, minSide * 0.005);
    ctx.fillStyle = '#131D30';
    ctx.fill();
    ctx.lineWidth = minSide * 0.0018;
    ctx.strokeStyle = mixColor([48, 86, 110], [38, 198, 218], s3Weight);
    ctx.stroke();
  }

  // Optical Laser Scan Bar oscillating vertically across open gate corridor
  const scanOffset = Math.sin(u * TAU * 4) * (gateHalfH * 0.72);
  ctx.beginPath();
  ctx.moveTo(gateInnerX + minSide * 0.007, cy + scanOffset);
  ctx.lineTo(gateOuterX - minSide * 0.007, cy + scanOffset);
  ctx.lineWidth = minSide * (0.0024 + 0.0018 * s3Weight);
  ctx.strokeStyle = '#26C6DA';
  ctx.stroke();

  // Exterior Right Sorting Console (x = 0.875*W .. 0.962*W)
  const st3Left = width * 0.876;
  const st3W = width * 0.086;
  const st3Top = cy - height * 0.16;
  const st3H = height * 0.32;

  // Clean horizontal telemetry bridge pipe from outer gate pylon -> Station 3 console
  ctx.beginPath();
  ctx.moveTo(gateOuterX + minSide * 0.007, cy);
  ctx.lineTo(st3Left, cy);
  ctx.lineWidth = minSide * 0.0042;
  ctx.strokeStyle = mixColor([60, 82, 110], [38, 198, 218], s3Weight);
  ctx.stroke();

  chamferRectPath(st3Left, st3Top, st3W, st3H, minSide * 0.014);
  ctx.fillStyle = '#0D1320';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = mixColor([48, 64, 96], [38, 198, 218], s3Weight * 0.85);
  ctx.stroke();

  // 4 Sorted Recycle Category Rings + Meters inside Station 3
  const sortCols = ['#FFD740', '#FF6E40', '#26C6DA', '#536DFE'];
  for (let sc = 0; sc < 4; sc++) {
    const sy = lerp(st3Top + st3H * 0.19, st3Top + st3H * 0.81, sc / 3);
    const act = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(TAU * (u * 4 - sc * 0.18))) * (0.4 + 0.6 * s3Weight);
    const dotX = st3Left + st3W * 0.22;
    ctx.beginPath();
    ctx.arc(dotX, sy, minSide * 0.0075, 0, TAU);
    ctx.fillStyle = sortCols[sc];
    ctx.fill();

    const barX = st3Left + st3W * 0.36;
    const barW = st3W * 0.48;
    const barH = minSide * 0.011;
    roundRectPath(barX, sy - barH * 0.5, barW, barH, barH * 0.45);
    ctx.fillStyle = '#151E30';
    ctx.fill();

    roundRectPath(barX, sy - barH * 0.5, barW * clamp01(act), barH, barH * 0.45);
    ctx.fillStyle = sortCols[sc];
    ctx.fill();
  }

  // STATION 4 (Bottom Purification & Molecular Regeneration Bay, Strictly Below Bottom Rail)
  const bayTop = cy + rLoop + minSide * 0.044;
  const bayH = height * 0.090;
  const bayW = width * 0.30;
  chamferRectPath(cx - bayW * 0.5, bayTop, bayW, bayH, minSide * 0.012);
  ctx.fillStyle = '#0D1320';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([48, 64, 96], [83, 109, 254], s4Weight * 0.85);
  ctx.stroke();

  // 7 Vertical Purification Chamber Emitters inside Bottom Bay rising cleanly toward rail without crossing
  const emitCount = 7;
  for (let e = 0; e < emitCount; e++) {
    const ex = lerp(cx - bayW * 0.38, cx + bayW * 0.38, e / (emitCount - 1));
    const ew = minSide * 0.014;
    const eh = bayH * 0.56;
    const ey = bayTop + (bayH - eh) * 0.5;
    const wave = 0.5 + 0.5 * Math.sin(TAU * (u * 4 + e * 0.14));
    const act = clamp01(0.35 + 0.65 * s4Weight) * (0.45 + 0.55 * wave);

    roundRectPath(ex - ew * 0.5, ey, ew, eh, ew * 0.4);
    ctx.fillStyle = '#162038';
    ctx.fill();

    roundRectPath(ex - ew * 0.5, ey + eh * (1 - act), ew, eh * act, ew * 0.4);
    ctx.fillStyle = e % 2 === 0 ? '#536DFE' : '#26C6DA';
    ctx.fill();
  }

  // 5. Four Evenly Spaced Parametric Material Units Traveling Seamless Closed Loop
  // Constant polygon helper: draws smooth morph between Square (4-sided), Triangle (3-sided), and Hexagon (6-sided)
  function drawMorphingPolygon(px, py, radius, rotAngle, morphState, fillCol, strokeCol) {
    // morphState 0 = Rounded Square, 0.5 = Equilateral Triangle, 1.0 = Regular Hexagon
    const pts = [];
    const N = 12; // Exact common factor of 3, 4, 6 -> 100% smooth vertex interpolation!
    for (let i = 0; i < N; i++) {
      const a = (i / N) * TAU;
      // Helper radial profile of N-gon at angle a: cos(pi/k) / cos((a mod 2pi/k) - pi/k)
      const polyRadius = (sides, angleOffset) => {
        const sector = TAU / sides;
        const aa = (((a + angleOffset) % sector) + sector) % sector - sector * 0.5;
        return Math.cos(Math.PI / sides) / Math.cos(aa);
      };

      const rSq = polyRadius(4, Math.PI * 0.25) * 0.85;
      const rTri = polyRadius(3, -Math.PI * 0.5) * 0.68;
      const rHex = polyRadius(6, 0) * 0.94;

      let rNorm;
      if (morphState < 0.5) {
        const k = morphState * 2;
        const ease = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
        rNorm = lerp(rSq, rTri, ease);
      } else {
        const k = (morphState - 0.5) * 2;
        const ease = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
        rNorm = lerp(rTri, rHex, ease);
      }
      pts.push([Math.cos(a) * radius * rNorm, Math.sin(a) * radius * rNorm]);
    }

    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(rotAngle);
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = fillCol;
    ctx.fill();
    ctx.lineWidth = minSide * 0.0024;
    ctx.strokeStyle = strokeCol;
    ctx.stroke();

    // Inner concentric geometric facet core
    ctx.beginPath();
    ctx.moveTo(pts[0][0] * 0.46, pts[0][1] * 0.46);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0] * 0.46, pts[i][1] * 0.46);
    }
    ctx.closePath();
    ctx.fillStyle = '#080B12';
    ctx.fill();
    ctx.restore();
  }

  // 4 Identical-Period Carriers Staggered by 0.25 -> Exact Seamless Loop & Zero Overlap!
  const carrierCount = 4;
  for (let c = 0; c < carrierCount; c++) {
    const s = (u + c / carrierCount) % 1;
    const pos = sampleStadium(s);

    // Phase-dependent transformation along the closed loop:
    // s in [0.00, 0.14]: Raw Yellow Block exiting Left Intake
    // s in [0.14, 0.42]: Morphing on Top Assembly Gantry (Square -> Triangle -> Hexagon, Yellow -> Peach -> Teal)
    // s in [0.42, 0.56]: Passing Right Optical Scanner Gate, cleanly separating into 4 non-overlapping categorized particles
    // s in [0.56, 0.88]: Bottom Purification Rail (4 separated colored beads gliding smoothly along track curve)
    // s in [0.88, 1.00]: Recombining seamlessly into single pure Lemon-Gold Material Block at Left Re-entry!

    // Disjoint split/merge phases so unified polygon and separated component beads NEVER overlap:
    // s in [0.00, 0.50]: Unified polygon (shrinking cleanly to 0 over [0.47, 0.50] at Right Scanner)
    // s in [0.50, 0.90]: Separated 4 colored component beads flowing cleanly through Bottom Purification
    // s in [0.90, 1.00]: Regenerated Lemon-Gold Material Block growing smoothly back to 1.0

    if (s <= 0.50 || s >= 0.90) {
      const morphVal =
        s < 0.14
          ? 0
          : s < 0.36
          ? (s - 0.14) / 0.22
          : s <= 0.50
          ? 1
          : 0;

      const unitCol =
        s < 0.20 || s >= 0.90
          ? '#FFD740'
          : s < 0.36
          ? mixColor([255, 215, 64], [255, 110, 64], (s - 0.20) / 0.16)
          : mixColor([255, 110, 64], [38, 198, 218], (s - 0.36) / 0.14);

      const scaleUnit =
        s < 0.47
          ? s >= 0.90
            ? clamp01((s - 0.90) / 0.03)
            : 1
          : s <= 0.50
          ? clamp01((0.50 - s) / 0.03)
          : clamp01((s - 0.90) / 0.03);

      const unitR = minSide * 0.021 * scaleUnit;
      if (unitR > 0.8) {
        drawMorphingPolygon(pos.x, pos.y, unitR, pos.angle + u * TAU * 2, morphVal, unitCol, '#FFFFFF');
      }
    } else {
      const beadScale =
        s < 0.53
          ? clamp01((s - 0.50) / 0.03)
          : s > 0.87
          ? clamp01((0.90 - s) / 0.03)
          : 1;

      const partCols = ['#FFD740', '#FF6E40', '#26C6DA', '#536DFE'];
      const spreadS = 0.025 * beadScale;
      const beadR = minSide * 0.0085 * beadScale;

      if (beadR > 0.6) {
        for (let p = 0; p < 4; p++) {
          const subS = s + (p - 1.5) * spreadS;
          const pPos = sampleStadium(subS);
          const nx = -Math.sin(pPos.angle);
          const ny = Math.cos(pPos.angle);
          const laneOffset = (p % 2 === 0 ? -1 : 1) * minSide * 0.0072 * beadScale;

          ctx.beginPath();
          ctx.arc(pPos.x + nx * laneOffset, pPos.y + ny * laneOffset, beadR, 0, TAU);
          ctx.fillStyle = partCols[p];
          ctx.fill();
          ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
          ctx.strokeStyle = '#080B12';
          ctx.stroke();
        }
      }
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function samplePolyline(pts, s) {
    let total = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const dx = pts[i + 1][0] - pts[i][0];
      const dy = pts[i + 1][1] - pts[i][1];
      const len = Math.hypot(dx, dy);
      segLens.push(len);
      total += len;
    }
    if (total <= 0) return pts[0];
    let target = clamp01(s) * total;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= segLens[i] || i === segLens.length - 1) {
        const local = segLens[i] > 0 ? target / segLens[i] : 0;
        return [
          lerp(pts[i][0], pts[i + 1][0], local),
          lerp(pts[i][1], pts[i + 1][1], local),
        ];
      }
      target -= segLens[i];
    }
    return pts[pts.length - 1];
  }

  function groundSurfaceY(x) {
    const nx = x / width;
    return height * 0.685 + height * 0.007 * Math.sin(nx * TAU * 1.5 - 0.55);
  }

  // 1. Clean Dark Modern Botanical Background (Zero Radial Glow)
  const skyGrad = ctx.createLinearGradient(0, 0, 0, height * 0.70);
  skyGrad.addColorStop(0, '#020705');
  skyGrad.addColorStop(0.55, '#040C08');
  skyGrad.addColorStop(1, '#06150E');
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, width, height);

  // Far recessed botanical horizon ridge silhouette
  ctx.fillStyle = '#06130C';
  ctx.beginPath();
  ctx.moveTo(0, height * 0.685);
  for (let i = 0; i <= 40; i++) {
    const px = (i / 40) * width;
    const ridgeH =
      height * 0.602 +
      height * 0.015 * Math.sin((i / 40) * TAU * 2.5 + 0.4) +
      height * 0.008 * Math.cos((i / 40) * TAU * 5.0 - 0.8);
    ctx.lineTo(px, ridgeH);
  }
  ctx.lineTo(width, height * 0.72);
  ctx.lineTo(0, height * 0.72);
  ctx.closePath();
  ctx.fill();

  // Crisp angled geometric sunbeams aligned diagonally between open tree corridors
  const sunBeams = [
    { topX: 0.07, topW: 0.048, botX: 0.28, botW: 0.105, phase: 0.0, cycles: 2 },
    { topX: 0.23, topW: 0.042, botX: 0.45, botW: 0.088, phase: 0.33, cycles: 3 },
    { topX: 0.43, topW: 0.056, botX: 0.66, botW: 0.115, phase: 0.66, cycles: 2 },
    { topX: 0.66, topW: 0.042, botX: 0.87, botW: 0.090, phase: 0.18, cycles: 3 },
  ];
  for (const beam of sunBeams) {
    const mod = 0.5 + 0.5 * Math.sin(TAU * (beam.cycles * u + beam.phase));
    const alpha = 0.024 + 0.032 * mod;
    const x1 = width * beam.topX;
    const x2 = x1 + width * beam.topW;
    const x3 = width * beam.botX + width * beam.botW;
    const x4 = width * beam.botX;
    const beamGrad = ctx.createLinearGradient(x1, 0, (x3 + x4) * 0.5, height * 0.67);
    beamGrad.addColorStop(0, `rgba(174, 234, 0, ${alpha.toFixed(4)})`);
    beamGrad.addColorStop(0.58, `rgba(46, 204, 113, ${(alpha * 0.52).toFixed(4)})`);
    beamGrad.addColorStop(1, 'rgba(0, 200, 83, 0)');
    ctx.fillStyle = beamGrad;
    ctx.beginPath();
    ctx.moveTo(x1, 0);
    ctx.lineTo(x2, 0);
    ctx.lineTo(x3, height * 0.685);
    ctx.lineTo(x4, height * 0.685);
    ctx.closePath();
    ctx.fill();
  }

  // 2. Subterranean Stratified Earth Cross-Section
  function traceSoilSurfacePath(yOffset) {
    ctx.beginPath();
    ctx.moveTo(0, groundSurfaceY(0) + yOffset);
    for (let i = 1; i <= 48; i++) {
      const px = (i / 48) * width;
      ctx.lineTo(px, groundSurfaceY(px) + yOffset);
    }
  }

  const soilGrad = ctx.createLinearGradient(0, height * 0.68, 0, height);
  soilGrad.addColorStop(0, '#071810');
  soilGrad.addColorStop(0.45, '#05110B');
  soilGrad.addColorStop(1, '#030906');
  ctx.fillStyle = soilGrad;
  traceSoilSurfacePath(0);
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();
  ctx.fill();

  const strataY = [height * 0.775, height * 0.865];
  const strataColors = ['#06140D', '#040D09'];
  for (let sIdx = 0; sIdx < strataY.length; sIdx++) {
    ctx.fillStyle = strataColors[sIdx];
    ctx.beginPath();
    ctx.moveTo(0, strataY[sIdx]);
    for (let i = 1; i <= 36; i++) {
      const px = (i / 36) * width;
      const py = strataY[sIdx] + height * 0.005 * Math.sin((px / width) * TAU * 2 + sIdx * 1.3);
      ctx.lineTo(px, py);
    }
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.closePath();
    ctx.fill();
  }

  traceSoilSurfacePath(0);
  ctx.lineWidth = minSide * 0.0042;
  ctx.strokeStyle = '#0F5C33';
  ctx.stroke();
  traceSoilSurfacePath(-minSide * 0.0018);
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#2ECC71';
  ctx.stroke();

  // 3. Tree & Root Circuit Data (Strict Non-Overlapping X & Y Lanes)
  const trees = [
    { id: 0, hero: false, xRatio: 0.092, heightS: 0.19, crownW: 0.054, phase: 0.05 },
    { id: 1, hero: true,  xRatio: 0.215, heightS: 0.40, crownW: 0.114, phase: 0.17 },
    { id: 2, hero: false, xRatio: 0.348, heightS: 0.20, crownW: 0.055, phase: 0.30 },
    { id: 3, hero: true,  xRatio: 0.500, heightS: 0.48, crownW: 0.146, phase: 0.45 },
    { id: 4, hero: false, xRatio: 0.652, heightS: 0.205, crownW: 0.055, phase: 0.60 },
    { id: 5, hero: true,  xRatio: 0.785, heightS: 0.415, crownW: 0.114, phase: 0.74 },
    { id: 6, hero: false, xRatio: 0.908, heightS: 0.185, crownW: 0.054, phase: 0.88 },
  ];

  function drawHexNode(cx, cy, r, activeIntensity) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const ang = (i / 6) * TAU - Math.PI / 6;
      const hx = cx + Math.cos(ang) * r;
      const hy = cy + Math.sin(ang) * r;
      if (i === 0) ctx.moveTo(hx, hy);
      else ctx.lineTo(hx, hy);
    }
    ctx.closePath();
    ctx.fillStyle = mixColor([11, 56, 34], [0, 200, 83], activeIntensity);
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, minSide * 0.0018);
    ctx.strokeStyle = mixColor([24, 108, 63], [174, 234, 0], activeIntensity);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.36, 0, TAU);
    ctx.fillStyle = mixColor([36, 138, 79], [212, 255, 89], activeIntensity);
    ctx.fill();
  }

  // 4. Clean Non-Crossing Hierarchical Subterranean Root Network
  // - busMidY connects ALL 7 trees vertically from busMidY -> groundY (zero crossing lines!)
  // - Below busMidY, ONLY the 3 Hero Trees branch diagonally down to busLowY aquifer nodes!
  const busMidY = height * 0.790;
  const busLowY = height * 0.895;

  const mineralBuses = [
    { y: busMidY, xStart: width * 0.092, xEnd: width * 0.908, w: minSide * 0.0032 },
    { y: busLowY, xStart: width * 0.171, xEnd: width * 0.829, w: minSide * 0.0042 },
  ];

  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  for (const bus of mineralBuses) {
    ctx.beginPath();
    ctx.moveTo(bus.xStart, bus.y);
    ctx.lineTo(bus.xEnd, bus.y);
    ctx.lineWidth = bus.w * 2.1;
    ctx.strokeStyle = '#092B1B';
    ctx.stroke();

    ctx.lineWidth = bus.w * 0.95;
    ctx.strokeStyle = '#125937';
    ctx.stroke();
  }

  const rootPaths = [];
  for (const tr of trees) {
    const cx = width * tr.xRatio;
    const gy = groundSurfaceY(cx);

    // Clean vertical trunk tap from Mid Nutrient Bus straight up to each tree collar (zero line crossing!)
    rootPaths.push({
      tree: tr,
      pts: [
        [cx, busMidY],
        [cx, gy + minSide * 0.004],
      ],
      side: 0,
    });

    // Hero Trees also draw clean Y-root diagonals ONLY in the lower tier [busLowY -> busMidY]
    if (tr.hero) {
      const rootSpan = width * 0.044;
      rootPaths.push({
        tree: tr,
        pts: [
          [cx - rootSpan, busLowY],
          [cx - rootSpan * 0.58, lerp(busLowY, busMidY, 0.45)],
          [cx, busMidY],
        ],
        side: -1,
      });
      rootPaths.push({
        tree: tr,
        pts: [
          [cx + rootSpan, busLowY],
          [cx + rootSpan * 0.58, lerp(busLowY, busMidY, 0.45)],
          [cx, busMidY],
        ],
        side: 1,
      });
    }
  }

  for (const rp of rootPaths) {
    ctx.beginPath();
    ctx.moveTo(rp.pts[0][0], rp.pts[0][1]);
    for (let i = 1; i < rp.pts.length; i++) {
      ctx.lineTo(rp.pts[i][0], rp.pts[i][1]);
    }
    ctx.lineWidth = (rp.tree.hero ? 0.0052 : 0.0034) * minSide;
    ctx.strokeStyle = '#0B3320';
    ctx.stroke();

    ctx.lineWidth = (rp.tree.hero ? 0.0022 : 0.0014) * minSide;
    ctx.strokeStyle = '#156A3F';
    ctx.stroke();

    const packetCount = rp.tree.hero ? 2 : 1;
    for (let p = 0; p < packetCount; p++) {
      const s = (u * 3 + rp.tree.phase + p / packetCount + (rp.side === 1 ? 0.22 : 0)) % 1;
      const pt = samplePolyline(rp.pts, s);
      const rDot = (rp.tree.hero ? 0.0036 : 0.0026) * minSide;
      const tailS = Math.max(0, s - 0.16);
      const tailPt = samplePolyline(rp.pts, tailS);

      const pGrad = ctx.createLinearGradient(tailPt[0], tailPt[1], pt[0], pt[1]);
      pGrad.addColorStop(0, 'rgba(0, 200, 83, 0)');
      pGrad.addColorStop(1, 'rgba(174, 234, 0, 0.94)');
      ctx.beginPath();
      ctx.moveTo(tailPt[0], tailPt[1]);
      ctx.lineTo(pt[0], pt[1]);
      ctx.lineWidth = rDot * 1.25;
      ctx.strokeStyle = pGrad;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(pt[0], pt[1], rDot * 0.95, 0, TAU);
      ctx.fillStyle = '#D4FF59';
      ctx.fill();
    }
  }

  // Horizontal pulse beads traveling along deep aquifer & mid nutrient buses
  for (let bIdx = 0; bIdx < 6; bIdx++) {
    const s = (u * 2 + bIdx / 6) % 1;
    const pxLow = lerp(width * 0.171, width * 0.829, s);
    ctx.beginPath();
    ctx.arc(pxLow, busLowY, minSide * 0.0030, 0, TAU);
    ctx.fillStyle = '#AEEA00';
    ctx.fill();

    const pxMid = lerp(width * 0.092, width * 0.908, (s + 0.5) % 1);
    ctx.beginPath();
    ctx.arc(pxMid, busMidY, minSide * 0.0024, 0, TAU);
    ctx.fillStyle = '#2ECC71';
    ctx.fill();
  }

  // Mineral Hex Nodes at clean bus junctions
  for (const tr of trees) {
    const cx = width * tr.xRatio;
    const pulse = 0.5 + 0.5 * Math.sin(TAU * (3 * u - tr.phase));
    drawHexNode(cx, busMidY, (tr.hero ? 0.0080 : 0.0056) * minSide, pulse);
    if (tr.hero) {
      const rootSpan = width * 0.044;
      drawHexNode(cx - rootSpan, busLowY, 0.0074 * minSide, 0.5 + 0.5 * Math.sin(TAU * (3 * u - tr.phase + 0.15)));
      drawHexNode(cx + rootSpan, busLowY, 0.0074 * minSide, 0.5 + 0.5 * Math.sin(TAU * (3 * u - tr.phase + 0.30)));
    }
  }
  ctx.restore();

  // 5. Crisp Vector Geometric Leaf Helper (Dual-Tone Almond + Animated Midrib & Lateral Veins)
  function drawVectorLeaf(x, y, len, wid, angle, veinEnergy, isSecondary) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -len * 0.14);
    ctx.lineWidth = Math.max(1.1, wid * 0.14);
    ctx.strokeStyle = isSecondary ? '#135733' : '#1F854D';
    ctx.stroke();

    const tipY = -len;
    const baseY = -len * 0.10;
    const midY = lerp(baseY, tipY, 0.45);

    ctx.beginPath();
    ctx.moveTo(0, baseY);
    ctx.bezierCurveTo(-wid * 0.95, lerp(baseY, midY, 0.35), -wid * 0.88, lerp(midY, tipY, 0.48), 0, tipY);
    ctx.closePath();
    ctx.fillStyle = isSecondary
      ? mixColor([14, 72, 42], [28, 128, 72], veinEnergy)
      : mixColor([22, 128, 68], [46, 204, 113], veinEnergy);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, baseY);
    ctx.bezierCurveTo(wid * 0.95, lerp(baseY, midY, 0.35), wid * 0.88, lerp(midY, tipY, 0.48), 0, tipY);
    ctx.closePath();
    ctx.fillStyle = isSecondary
      ? mixColor([9, 52, 30], [18, 98, 55], veinEnergy)
      : mixColor([12, 86, 46], [0, 178, 76], veinEnergy);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, baseY);
    ctx.bezierCurveTo(-wid * 0.95, lerp(baseY, midY, 0.35), -wid * 0.88, lerp(midY, tipY, 0.48), 0, tipY);
    ctx.bezierCurveTo(wid * 0.88, lerp(midY, tipY, 0.48), wid * 0.95, lerp(baseY, midY, 0.35), 0, baseY);
    ctx.lineWidth = Math.max(1.0, minSide * 0.0014);
    ctx.strokeStyle = isSecondary ? '#186E41' : mixColor([36, 175, 96], [174, 234, 0], veinEnergy * 0.75);
    ctx.stroke();

    const veinColor = isSecondary
      ? mixColor([24, 116, 65], [108, 224, 134], veinEnergy)
      : mixColor([36, 170, 92], [212, 255, 89], veinEnergy);

    ctx.strokeStyle = veinColor;
    ctx.lineCap = 'round';
    ctx.lineWidth = Math.max(1.1, len * 0.028);
    ctx.beginPath();
    ctx.moveTo(0, baseY + len * 0.02);
    ctx.lineTo(0, lerp(baseY, tipY, 0.86));
    ctx.stroke();

    if (!isSecondary) {
      ctx.lineWidth = Math.max(0.9, len * 0.018);
      for (let v = 0; v < 3; v++) {
        const vy = lerp(baseY, tipY, 0.28 + v * 0.20);
        const span = wid * (0.58 - v * 0.12);
        const rise = len * (0.11 - v * 0.015);
        ctx.beginPath();
        ctx.moveTo(0, vy);
        ctx.lineTo(-span, vy - rise);
        ctx.moveTo(0, vy);
        ctx.lineTo(span, vy - rise);
        ctx.stroke();
      }
    }

    ctx.restore();
  }

  // 6. Canopy Dome Backdrop
  function drawCanopyDome(rx, ry, swayPhase, energy, isSecondary) {
    const breath = 1 + 0.016 * Math.sin(TAU * (3 * u - swayPhase));
    const w = rx * breath;
    const h = ry * breath;

    ctx.beginPath();
    ctx.moveTo(0, -h * 1.04);
    ctx.bezierCurveTo(w * 0.82, -h * 0.96, w * 1.08, -h * 0.12, w * 0.74, h * 0.56);
    ctx.bezierCurveTo(w * 0.42, h * 0.90, -w * 0.42, h * 0.90, -w * 0.74, h * 0.56);
    ctx.bezierCurveTo(-w * 1.08, -h * 0.12, -w * 0.82, -h * 0.96, 0, -h * 1.04);
    ctx.closePath();

    const domeGrad = ctx.createLinearGradient(-w * 0.5, -h, w * 0.5, h * 0.8);
    if (isSecondary) {
      domeGrad.addColorStop(0, '#0E482A');
      domeGrad.addColorStop(1, '#072415');
    } else {
      domeGrad.addColorStop(0, mixColor([18, 108, 56], [34, 168, 92], energy * 0.65));
      domeGrad.addColorStop(1, '#07321C');
    }
    ctx.fillStyle = domeGrad;
    ctx.fill();

    ctx.lineWidth = Math.max(1.2, minSide * 0.0018);
    ctx.strokeStyle = isSecondary ? '#145D37' : mixColor([24, 132, 72], [116, 232, 92], energy * 0.6);
    ctx.stroke();
  }

  function drawBotanicalTree(tr) {
    const cx = width * tr.xRatio;
    const gy = groundSurfaceY(cx);
    const th = minSide * tr.heightS;
    const isSec = !tr.hero;

    const swayRad =
      (isSec ? 0.010 : 0.014) * Math.sin(TAU * (2 * u - tr.phase)) +
      (isSec ? 0.003 : 0.005) * Math.sin(TAU * (4 * u - tr.phase + 0.15));

    const treePulseBase = (u * 3 - tr.phase + 1) % 1;
    const canopyEnergy = 0.5 + 0.5 * Math.cos(TAU * ((treePulseBase - 0.55 + 1) % 1));

    const trunkBaseW = th * (isSec ? 0.072 : 0.068);
    const trunkTopW = th * (isSec ? 0.026 : 0.024);
    const forkRatio = isSec ? 0.48 : 0.42;
    const forkY = -th * forkRatio;
    const forkX = Math.sin(swayRad) * th * 0.32;

    ctx.save();
    ctx.translate(cx, gy);

    const trunkGrad = ctx.createLinearGradient(-trunkBaseW, 0, trunkBaseW, forkY);
    trunkGrad.addColorStop(0, isSec ? '#0B281A' : '#103D26');
    trunkGrad.addColorStop(0.55, isSec ? '#0F3724' : '#195E3B');
    trunkGrad.addColorStop(1, isSec ? '#12462D' : '#1F7449');

    ctx.beginPath();
    ctx.moveTo(-trunkBaseW * 1.15, minSide * 0.004);
    ctx.bezierCurveTo(-trunkBaseW * 0.52, -th * 0.14, forkX - trunkTopW * 0.85, forkY * 0.65, forkX - trunkTopW * 0.55, forkY);
    ctx.lineTo(forkX + trunkTopW * 0.55, forkY);
    ctx.bezierCurveTo(forkX + trunkTopW * 0.85, forkY * 0.65, trunkBaseW * 0.52, -th * 0.14, trunkBaseW * 1.15, minSide * 0.004);
    ctx.closePath();
    ctx.fillStyle = trunkGrad;
    ctx.fill();

    const trunkSpine = [
      [0, 0],
      [forkX * 0.45, forkY * 0.5],
      [forkX, forkY],
    ];
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(forkX * 0.45, forkY * 0.5, forkX, forkY);
    ctx.lineWidth = Math.max(1.4, trunkTopW * 0.42);
    ctx.strokeStyle = isSec ? '#165F3A' : mixColor([22, 118, 66], [0, 200, 83], canopyEnergy * 0.5);
    ctx.stroke();

    if (!isSec) {
      const tp = samplePolyline(trunkSpine, treePulseBase);
      ctx.beginPath();
      ctx.arc(tp[0], tp[1], trunkTopW * 0.38, 0, TAU);
      ctx.fillStyle = '#AEEA00';
      ctx.fill();
    }

    ctx.translate(forkX, forkY);
    ctx.rotate(swayRad);

    // Explicitly separated bough angles & lengths so Left, Center, and Right canopy pods NEVER clip one another or neighboring trees!
    const branches = isSec
      ? [
          { ang: -0.90, len: th * 0.33, rx: minSide * tr.crownW * 0.49, ry: minSide * tr.crownW * 0.43, lag: 0.06, topPod: false },
          { ang: 0.90,  len: th * 0.33, rx: minSide * tr.crownW * 0.49, ry: minSide * tr.crownW * 0.43, lag: 0.12, topPod: false },
          { ang: 0.0,   len: th * 0.49, rx: minSide * tr.crownW * 0.62, ry: minSide * tr.crownW * 0.55, lag: 0.18, topPod: true },
        ]
      : [
          { ang: -0.90, len: th * 0.34, rx: minSide * tr.crownW * 0.51, ry: minSide * tr.crownW * 0.43, lag: 0.08, topPod: false },
          { ang: 0.90,  len: th * 0.34, rx: minSide * tr.crownW * 0.51, ry: minSide * tr.crownW * 0.43, lag: 0.14, topPod: false },
          { ang: 0.0,   len: th * 0.56, rx: minSide * tr.crownW * 0.64, ry: minSide * tr.crownW * 0.55, lag: 0.20, topPod: true },
        ];

    for (const br of branches) {
      const localSway = 0.010 * Math.sin(TAU * (2 * u - tr.phase - br.lag));
      ctx.save();
      ctx.rotate(br.ang + localSway);

      const bw0 = trunkTopW * 0.46;
      const bw1 = trunkTopW * 0.18;
      ctx.beginPath();
      ctx.moveTo(-bw0, 0);
      ctx.lineTo(-bw1, -br.len);
      ctx.lineTo(bw1, -br.len);
      ctx.lineTo(bw0, 0);
      ctx.closePath();
      ctx.fillStyle = isSec ? '#12462D' : '#1E6E45';
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(0, -br.len);
      ctx.lineWidth = Math.max(1.2, bw1 * 0.75);
      ctx.strokeStyle = isSec ? '#1D7448' : mixColor([36, 154, 86], [174, 234, 0], canopyEnergy);
      ctx.stroke();

      ctx.restore();
    }

    for (const br of branches) {
      const localSway = 0.010 * Math.sin(TAU * (2 * u - tr.phase - br.lag));
      const podEnergy = 0.5 + 0.5 * Math.cos(TAU * ((treePulseBase - 0.60 - br.lag + 1) % 1));

      ctx.save();
      ctx.rotate(br.ang + localSway);
      ctx.translate(0, -br.len);
      ctx.rotate(-(br.ang + localSway) * 0.80);

      drawCanopyDome(br.rx, br.ry, tr.phase + br.lag, podEnergy, isSec);

      const leafAngles = br.topPod ? [-0.84, -0.42, 0.0, 0.42, 0.84] : [-0.68, -0.22, 0.22, 0.68];
      const leafLen = br.ry * (isSec ? 0.90 : 1.02);
      const leafWid = br.rx * (isSec ? 0.24 : 0.23);

      for (let lIdx = 0; lIdx < leafAngles.length; lIdx++) {
        const lAng = leafAngles[lIdx];
        const lFlutter = 0.020 * Math.sin(TAU * (3 * u - tr.phase - lIdx * 0.09));
        const lEnergy = clamp01(podEnergy * (0.78 + 0.22 * Math.sin(TAU * (u * 3 + lIdx * 0.14))));
        const anchorY = br.ry * 0.28;
        drawVectorLeaf(
          Math.sin(lAng) * br.rx * 0.22,
          anchorY,
          leafLen * (lAng === 0 ? 1.10 : 0.92),
          leafWid,
          lAng + lFlutter,
          lEnergy,
          isSec
        );
      }

      ctx.restore();
    }

    ctx.restore();
  }

  for (const tr of trees) {
    if (!tr.hero) drawBotanicalTree(tr);
  }
  for (const tr of trees) {
    if (tr.hero) drawBotanicalTree(tr);
  }

  // Symmetrical ground fern tufts strictly placed in ground gaps between trunks
  const fernX = [0.155, 0.280, 0.415, 0.585, 0.720, 0.845];
  for (let f = 0; f < fernX.length; f++) {
    const fx = width * fernX[f];
    const fy = groundSurfaceY(fx);
    const fSway = 0.026 * Math.sin(TAU * (2 * u - f * 0.14));
    const fEnergy = 0.5 + 0.5 * Math.sin(TAU * (3 * u - f * 0.17));
    const blades = [-0.55, -0.18, 0.18, 0.55];
    for (let b = 0; b < blades.length; b++) {
      const len = minSide * (b === 1 || b === 2 ? 0.042 : 0.032);
      drawVectorLeaf(fx, fy + minSide * 0.002, len, len * 0.22, blades[b] + fSway, fEnergy, false);
    }
  }

  // 7. Oxygen Molecule Bubbles (Strictly Bounded in Unobstructed Sky Corridors & High Above Canopies)
  const o2Lanes = [
    { xBase: 0.095 * width, yTop: 0.075 * height, yBot: 0.36 * height, rS: 0.0085, ampX: 0.008, speedC: 2, phase: 0.08 },
    { xBase: 0.215 * width, yTop: 0.055 * height, yBot: 0.20 * height, rS: 0.0095, ampX: 0.007, speedC: 2, phase: 0.44 },
    { xBase: 0.345 * width, yTop: 0.065 * height, yBot: 0.38 * height, rS: 0.0092, ampX: 0.009, speedC: 3, phase: 0.15 },
    { xBase: 0.345 * width, yTop: 0.065 * height, yBot: 0.38 * height, rS: 0.0076, ampX: 0.009, speedC: 3, phase: 0.65 },
    { xBase: 0.460 * width, yTop: 0.045 * height, yBot: 0.135 * height, rS: 0.0082, ampX: 0.006, speedC: 2, phase: 0.28 },
    { xBase: 0.540 * width, yTop: 0.045 * height, yBot: 0.135 * height, rS: 0.0088, ampX: 0.006, speedC: 2, phase: 0.78 },
    { xBase: 0.655 * width, yTop: 0.065 * height, yBot: 0.38 * height, rS: 0.0094, ampX: 0.009, speedC: 3, phase: 0.36 },
    { xBase: 0.655 * width, yTop: 0.065 * height, yBot: 0.38 * height, rS: 0.0078, ampX: 0.009, speedC: 3, phase: 0.86 },
    { xBase: 0.785 * width, yTop: 0.055 * height, yBot: 0.19 * height, rS: 0.0094, ampX: 0.007, speedC: 2, phase: 0.54 },
    { xBase: 0.905 * width, yTop: 0.075 * height, yBot: 0.36 * height, rS: 0.0085, ampX: 0.008, speedC: 2, phase: 0.91 },
  ];

  for (const lane of o2Lanes) {
    const progress = (u * lane.speedC + lane.phase) % 1;
    const py = lerp(lane.yBot, lane.yTop, progress);
    const px = lane.xBase + minSide * lane.ampX * Math.sin(TAU * (lane.speedC * 2 * u + lane.phase * 2));
    const env = Math.sin(Math.PI * progress);
    const radius = minSide * lane.rS * (0.55 + 0.45 * env);

    ctx.save();
    ctx.globalAlpha = 0.90 * env;

    ctx.beginPath();
    ctx.arc(px, py, radius, 0, TAU);
    ctx.fillStyle = 'rgba(10, 48, 28, 0.68)';
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, minSide * 0.0018);
    ctx.strokeStyle = '#AEEA00';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(px, py, radius * 0.58, 0, TAU);
    ctx.lineWidth = Math.max(1.0, minSide * 0.0012);
    ctx.strokeStyle = '#2ECC71';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(px - radius * 0.32, py - radius * 0.32, radius * 0.22, 0, TAU);
    ctx.fillStyle = '#E8FFCC';
    ctx.fill();

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  ctx.save();
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;

  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = (currentScene + sceneProgress) / sceneCount;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;

  function mixColor(c1, c2, k) {
    const f = clamp01(k);
    const r = Math.round(lerp(c1[0], c2[0], f));
    const g = Math.round(lerp(c1[1], c2[1], f));
    const b = Math.round(lerp(c1[2], c2[2], f));
    return `rgb(${r},${g},${b})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function samplePolyline(pts, s) {
    let total = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(len);
      total += len;
    }
    if (total <= 0) return pts[0];
    let target = clamp01(s) * total;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= segLens[i] || i === segLens.length - 1) {
        const local = segLens[i] > 0 ? target / segLens[i] : 0;
        return [
          lerp(pts[i][0], pts[i + 1][0], local),
          lerp(pts[i][1], pts[i + 1][1], local),
        ];
      }
      target -= segLens[i];
    }
    return pts[pts.length - 1];
  }

  // Smooth C-infinity periodic scene emphasis windows across the 3 scenes (total = 20s)
  // s1Weight peaks around u = 1/6 (3.33s), s2Weight peaks around u = 3/6 (10.0s), s3Weight peaks around u = 5/6 (16.67s)
  const s1Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 1 / 6));
  const s2Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 3 / 6));
  const s3Weight = 0.5 + 0.5 * Math.cos(TAU * (u - 5 / 6));

  // Key Spatial Datum Constants
  const surfaceY = height * 0.405;
  const inX = width * 0.245;
  const outX = width * 0.460;
  const resTopY = height * 0.652;
  const resBotY = height * 0.752;
  const channelY = [height * 0.678, height * 0.703, height * 0.728];
  const bridgeY = height * 0.135;
  const coolX = width * 0.150;
  const turbX = width * 0.625;
  const turbY = height * 0.295;
  const turbR = minSide * 0.082;
  const subLeft = width * 0.765;
  const subW = width * 0.150;

  // 1. Clean Volcanic Obsidian Background (Zero Glow on Background)
  const bgGrad = ctx.createLinearGradient(0, 0, 0, surfaceY);
  bgGrad.addColorStop(0, '#090406');
  bgGrad.addColorStop(0.55, '#0C0507');
  bgGrad.addColorStop(1, '#14080B');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Clean geometric volcanic silhouette ridges behind power plant
  ctx.fillStyle = '#12070A';
  ctx.beginPath();
  ctx.moveTo(0, surfaceY);
  ctx.lineTo(width * 0.08, height * 0.345);
  ctx.lineTo(width * 0.19, height * 0.378);
  ctx.lineTo(width * 0.34, height * 0.330);
  ctx.lineTo(width * 0.50, height * 0.372);
  ctx.lineTo(width * 0.69, height * 0.338);
  ctx.lineTo(width * 0.85, height * 0.365);
  ctx.lineTo(width, height * 0.340);
  ctx.lineTo(width, surfaceY);
  ctx.closePath();
  ctx.fill();

  // 2. Stratified Earth Crust Cross-Section
  const crustLayers = [
    { yBase: surfaceY, color: '#170B0F', amp: 0.004, freq: 2.0, phase: 0.0 },
    { yBase: height * 0.485, color: '#1E0E13', amp: 0.006, freq: 2.5, phase: 0.7 },
    { yBase: height * 0.568, color: '#261116', amp: 0.007, freq: 2.0, phase: 1.5 },
    { yBase: height * 0.642, color: '#1A0A0E', amp: 0.005, freq: 3.0, phase: 2.1 },
    { yBase: height * 0.775, color: '#2A1012', amp: 0.006, freq: 2.0, phase: 0.4 },
  ];

  for (let lIdx = 0; lIdx < crustLayers.length; lIdx++) {
    const lay = crustLayers[lIdx];
    ctx.fillStyle = lay.color;
    ctx.beginPath();
    ctx.moveTo(0, lay.yBase);
    for (let i = 1; i <= 48; i++) {
      const px = (i / 48) * width;
      const py =
        lIdx === 0
          ? surfaceY
          : lay.yBase + height * lay.amp * Math.sin((px / width) * TAU * lay.freq + lay.phase);
      ctx.lineTo(px, py);
    }
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.closePath();
    ctx.fill();

    if (lIdx > 0) {
      ctx.beginPath();
      for (let i = 0; i <= 48; i++) {
        const px = (i / 48) * width;
        const py = lay.yBase + height * lay.amp * Math.sin((px / width) * TAU * lay.freq + lay.phase);
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.lineWidth = Math.max(1.2, minSide * 0.0018);
      ctx.strokeStyle = lIdx === 4 ? '#4F1B15' : '#331820';
      ctx.stroke();
    }
  }

  ctx.beginPath();
  ctx.moveTo(0, surfaceY);
  ctx.lineTo(width, surfaceY);
  ctx.lineWidth = minSide * 0.0045;
  ctx.strokeStyle = '#3B232B';
  ctx.stroke();

  // 3. Layered Vector Volcanic Magma Pocket (Bottom Heat Core — Zero Background Blur)
  const magmaBreath = Math.sin(TAU * (2 * u));
  const magmaBands = [
    { topY: 0.868, peakShift: 0.018, color: '#6E1304' },
    { topY: 0.892, peakShift: 0.022, color: '#B71C1C' },
    { topY: 0.918, peakShift: 0.020, color: '#FF3D00' },
    { topY: 0.946, peakShift: 0.016, color: '#FF9100' },
    { topY: 0.974, peakShift: 0.012, color: '#FFC400' },
  ];

  for (let mIdx = 0; mIdx < magmaBands.length; mIdx++) {
    const mb = magmaBands[mIdx];
    const breathAmp = height * (0.0048 - mIdx * 0.0006) * magmaBreath;
    ctx.fillStyle = mb.color;
    ctx.beginPath();
    ctx.moveTo(0, height);
    ctx.lineTo(0, height * mb.topY + height * 0.015);
    for (let i = 0; i <= 56; i++) {
      const nx = i / 56;
      const px = nx * width;
      const dome = Math.exp(-Math.pow((nx - 0.36) / 0.34, 2));
      const wave = Math.sin(TAU * (3 * nx - u * 2 + mIdx * 0.16));
      const py =
        height * mb.topY -
        height * mb.peakShift * dome +
        height * 0.0045 * wave +
        breathAmp;
      ctx.lineTo(px, py);
    }
    ctx.lineTo(width, height);
    ctx.closePath();
    ctx.fill();
  }

  // 4. Isotherm Contour Waves (Strictly BELOW Reservoir resBotY = 0.752*H -> ZERO intersection with cavern or boreholes!)
  for (let iso = 0; iso < 4; iso++) {
    const waveCycle = (u * 3 - iso * 0.18 + 1) % 1;
    const pulse = 0.5 - 0.5 * Math.cos(TAU * waveCycle);
    const active = clamp01(0.32 + 0.68 * s1Weight) * (0.28 + 0.72 * pulse);
    const baseIsoY = height * (0.848 - iso * 0.019); // Spans 0.791*H to 0.848*H cleanly below resBotY (0.752*H)
    const colMix = iso / 3;
    const baseRGB = [255, lerp(61, 165, colMix), lerp(0, 20, colMix)];

    ctx.beginPath();
    for (let i = 0; i <= 52; i++) {
      const nx = 0.06 + (i / 52) * 0.88;
      const px = nx * width;
      const dome = Math.exp(-Math.pow((nx - 0.36) / 0.35, 2));
      const ripple = Math.sin(TAU * (2 * nx + u * 2 + iso * 0.14));
      const py = baseIsoY - height * 0.015 * dome + height * 0.0028 * ripple - minSide * 0.0032 * pulse;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.lineWidth = minSide * lerp(0.0018, 0.0034, active);
    ctx.strokeStyle = mixColor([118, 30, 18], baseRGB, active);
    ctx.stroke();
  }

  // Right-side clean subterranean thermal strata profile stack (compact aligned telemetry column, zero stray lines)
  const thermalCardX = width * 0.825;
  const thermalCardW = width * 0.090;
  const thermalCardY = height * 0.445;
  const thermalCardH = height * 0.270;
  chamferRectPath(thermalCardX, thermalCardY, thermalCardW, thermalCardH, minSide * 0.010);
  ctx.fillStyle = 'rgba(24, 11, 15, 0.86)';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0016;
  ctx.strokeStyle = mixColor([68, 28, 32], [255, 112, 32], s1Weight * 0.7);
  ctx.stroke();

  const strataBars = 6;
  for (let sb = 0; sb < strataBars; sb++) {
    const sy = lerp(thermalCardY + thermalCardH * 0.14, thermalCardY + thermalCardH * 0.86, sb / (strataBars - 1));
    const phase = (u * 3 - sb * 0.12 + 1) % 1;
    const pulse = 0.5 - 0.5 * Math.cos(TAU * phase);
    const active = clamp01(0.32 + 0.68 * s1Weight) * (0.45 + 0.55 * pulse);
    const bx = thermalCardX + thermalCardW * 0.14;
    const bw = thermalCardW * 0.72;
    const bh = minSide * 0.009;
    const depthRatio = (sb + 2) / (strataBars + 1);

    roundRectPath(bx, sy - bh * 0.5, bw, bh, bh * 0.45);
    ctx.fillStyle = '#261217';
    ctx.fill();

    roundRectPath(bx, sy - bh * 0.5, bw * clamp01(depthRatio * (0.55 + 0.45 * active)), bh, bh * 0.45);
    ctx.fillStyle = sb < 2 ? '#00B8D4' : mixColor([255, 110, 20], [255, 196, 0], active);
    ctx.fill();
  }

  // 5. Fractured Porous Geothermal Reservoir Zone & 3 Separated Heating Channels
  const resLeft = inX - width * 0.018;
  const resRight = outX + width * 0.018;
  const resPadW = resRight - resLeft;
  roundRectPath(resLeft, resTopY, resPadW, resBotY - resTopY, minSide * 0.018);
  ctx.fillStyle = '#12070A';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0030;
  ctx.strokeStyle = mixColor([78, 28, 18], [255, 95, 25], s1Weight * 0.6 + s2Weight * 0.4);
  ctx.stroke();

  const channelPts = [];
  for (let c = 0; c < channelY.length; c++) {
    const cy = channelY[c];
    const waveOffset = c === 1 ? 0 : (c === 0 ? -0.003 : 0.003) * height;
    const pts = [];
    const steps = 14;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      const px = lerp(inX, outX, f);
      const py = cy + waveOffset * Math.sin(f * TAU * 1.5);
      pts.push([px, py]);
    }
    channelPts.push(pts);

    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]);
      else ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = minSide * 0.0145;
    ctx.strokeStyle = '#241013';
    ctx.stroke();

    const heatGrad = ctx.createLinearGradient(inX, cy, outX, cy);
    heatGrad.addColorStop(0, '#00566B');
    heatGrad.addColorStop(0.45, '#8E3E12');
    heatGrad.addColorStop(1, '#A62308');
    ctx.lineWidth = minSide * 0.0080;
    ctx.strokeStyle = heatGrad;
    ctx.stroke();
  }

  for (let d = 0; d < 2; d++) {
    const divY = (channelY[d] + channelY[d + 1]) * 0.5;
    ctx.beginPath();
    ctx.moveTo(inX + width * 0.024, divY);
    ctx.lineTo(outX - width * 0.024, divY);
    ctx.lineWidth = minSide * 0.0045;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#2F151A';
    ctx.stroke();
  }

  // 6. Dual Vertical Boreholes (Injection Left = inX, Steam Extraction Right = outX)
  function drawBoreholePipe(cx, topY, botY, innerColor, casingColor) {
    const outerW = minSide * 0.032;
    const innerW = minSide * 0.017;

    ctx.fillStyle = '#181C24';
    ctx.fillRect(cx - outerW * 0.5, topY, outerW, botY - topY);

    ctx.fillStyle = casingColor;
    ctx.fillRect(cx - outerW * 0.5, topY, minSide * 0.0032, botY - topY);
    ctx.fillRect(cx + outerW * 0.5 - minSide * 0.0032, topY, minSide * 0.0032, botY - topY);

    ctx.fillStyle = innerColor;
    ctx.fillRect(cx - innerW * 0.5, topY, innerW, botY - topY);

    const collarCount = 6;
    for (let i = 1; i < collarCount; i++) {
      const ry = lerp(topY, botY, i / collarCount);
      roundRectPath(cx - outerW * 0.66, ry - minSide * 0.004, outerW * 1.32, minSide * 0.008, minSide * 0.003);
      ctx.fillStyle = '#2F3847';
      ctx.fill();
      ctx.fillStyle = casingColor;
      ctx.fillRect(cx - outerW * 0.56, ry - minSide * 0.0012, outerW * 1.12, minSide * 0.0024);
    }
  }

  drawBoreholePipe(inX, surfaceY, channelY[2], '#042A36', '#2A5B70');
  drawBoreholePipe(outX, surfaceY, channelY[2], '#3A0E07', '#7A3224');

  // 7. Overhead Condenser Return Pipe & Surface Interconnecting Piping
  const pipeOuterW = minSide * 0.024;
  const pipeInnerW = minSide * 0.012;

  function drawVectorConduit(pts, outerColor, innerStartColor, innerEndColor) {
    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]);
      else ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.lineWidth = pipeOuterW;
    ctx.strokeStyle = outerColor;
    ctx.stroke();

    const g = ctx.createLinearGradient(pts[0][0], pts[0][1], pts[pts.length - 1][0], pts[pts.length - 1][1]);
    g.addColorStop(0, innerStartColor);
    g.addColorStop(1, innerEndColor);
    ctx.lineWidth = pipeInnerW;
    ctx.strokeStyle = g;
    ctx.stroke();
    ctx.restore();
  }

  const bridgePts = [
    [turbX, turbY - turbR * 0.85],
    [turbX, bridgeY],
    [coolX, bridgeY],
    [coolX, height * 0.220],
  ];
  drawVectorConduit(bridgePts, '#273040', '#632818', '#094354');

  const coldReturnPts = [
    [coolX + width * 0.042, height * 0.345],
    [inX - width * 0.024, height * 0.345],
  ];
  drawVectorConduit(coldReturnPts, '#273040', '#0A4E61', '#008BA3');

  const steamManifoldPts = [
    [outX + width * 0.036, turbY],
    [turbX - turbR * 0.85, turbY],
  ];
  drawVectorConduit(steamManifoldPts, '#302226', '#872B12', '#BF4013');

  const powerBusPts = [
    [turbX + turbR * 0.82, height * 0.340],
    [subLeft, height * 0.340],
  ];
  drawVectorConduit(powerBusPts, '#252C3A', '#6E500A', '#0D5E66');

  // 8. Surface Plant Modules (All Aligned Cleanly on surfaceY Datum)

  // A. Cooling Condenser Tower
  const coolW = width * 0.090;
  const coolLeft = coolX - coolW * 0.5;
  const coolTop = height * 0.215;
  const coolH = surfaceY - coolTop;

  chamferRectPath(coolLeft, coolTop, coolW, coolH, minSide * 0.012);
  const coolBodyGrad = ctx.createLinearGradient(coolLeft, coolTop, coolLeft + coolW, surfaceY);
  coolBodyGrad.addColorStop(0, '#1D2736');
  coolBodyGrad.addColorStop(1, '#121924');
  ctx.fillStyle = coolBodyGrad;
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = '#384C66';
  ctx.stroke();

  roundRectPath(coolX - minSide * 0.020, coolTop - minSide * 0.010, minSide * 0.040, minSide * 0.016, minSide * 0.004);
  ctx.fillStyle = '#3B4D63';
  ctx.fill();

  const finCount = 6;
  for (let f = 0; f < finCount; f++) {
    const fy = lerp(coolTop + coolH * 0.16, surfaceY - coolH * 0.16, f / (finCount - 1));
    const finPhase = (u * 3 - f * 0.11 + 1) % 1;
    const finEnergy = (0.35 + 0.65 * s3Weight) * (0.4 + 0.6 * (0.5 - 0.5 * Math.cos(TAU * finPhase)));
    const fX = coolLeft + coolW * 0.14;
    const fW = coolW * 0.72;
    const fH = minSide * 0.010;
    roundRectPath(fX, fy - fH * 0.5, fW, fH, fH * 0.45);
    ctx.fillStyle = '#0D141C';
    ctx.fill();

    roundRectPath(fX + minSide * 0.002, fy - fH * 0.34, (fW - minSide * 0.004) * clamp01(0.45 + 0.55 * finEnergy), fH * 0.68, fH * 0.34);
    ctx.fillStyle = mixColor([18, 98, 122], [0, 229, 255], finEnergy);
    ctx.fill();
  }

  // B. Injection Wellhead Collar (centered on inX, clean pressure gauge circle with zero overlapping fluid dots)
  const whW = width * 0.052;
  const whTop = height * 0.312;
  chamferRectPath(inX - whW * 0.5, whTop, whW, surfaceY - whTop, minSide * 0.008);
  ctx.fillStyle = '#1E2D3D';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#00B8D4';
  ctx.stroke();

  const valveR = minSide * 0.015;
  const valveCy = lerp(whTop, surfaceY, 0.50);
  ctx.beginPath();
  ctx.arc(inX, valveCy, valveR, 0, TAU);
  ctx.fillStyle = '#082630';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0028;
  ctx.strokeStyle = mixColor([0, 155, 190], [132, 255, 255], s2Weight);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(inX, valveCy, valveR * 0.32, 0, TAU);
  ctx.fillStyle = '#84FFFF';
  ctx.fill();

  // C. Flash Steam Separator Vessel
  const sepW = width * 0.076;
  const sepTop = height * 0.215;
  const sepH = surfaceY - sepTop;
  roundRectPath(outX - sepW * 0.5, sepTop, sepW, sepH, sepW * 0.42);
  const sepGrad = ctx.createLinearGradient(outX - sepW * 0.5, sepTop, outX + sepW * 0.5, surfaceY);
  sepGrad.addColorStop(0, '#2B2027');
  sepGrad.addColorStop(1, '#1A1318');
  ctx.fillStyle = sepGrad;
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = '#6E4239';
  ctx.stroke();

  const glassW = sepW * 0.50;
  const glassH = sepH * 0.58;
  const glassX = outX - glassW * 0.5;
  const glassY = sepTop + sepH * 0.22;
  roundRectPath(glassX, glassY, glassW, glassH, glassW * 0.35);
  ctx.fillStyle = '#140808';
  ctx.fill();

  ctx.save();
  roundRectPath(glassX, glassY, glassW, glassH, glassW * 0.35);
  ctx.clip();
  const boilLevel = glassY + glassH * (0.42 + 0.05 * Math.sin(TAU * (u * 3)));
  const boilGrad = ctx.createLinearGradient(0, boilLevel, 0, glassY + glassH);
  boilGrad.addColorStop(0, '#FF9100');
  boilGrad.addColorStop(1, '#FF3D00');
  ctx.fillStyle = boilGrad;
  ctx.fillRect(glassX, boilLevel, glassW, glassY + glassH - boilLevel);

  for (let sb = 0; sb < 4; sb++) {
    const bp = (u * 4 + sb * 0.25) % 1;
    const bx = outX + Math.sin(bp * TAU + sb) * glassW * 0.22;
    const by = lerp(glassY + glassH * 0.9, glassY + glassH * 0.1, bp);
    ctx.beginPath();
    ctx.arc(bx, by, minSide * 0.0042 * Math.sin(Math.PI * bp), 0, TAU);
    ctx.fillStyle = '#FFC400';
    ctx.fill();
  }
  ctx.restore();

  roundRectPath(glassX, glassY, glassW, glassH, glassW * 0.35);
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeStyle = '#FF6D33';
  ctx.stroke();

  // D. Precision Steam Turbine & Generator Unit
  const plinthW = turbR * 1.65;
  chamferRectPath(turbX - plinthW * 0.5, turbY + turbR * 0.72, plinthW, surfaceY - (turbY + turbR * 0.72), minSide * 0.008);
  ctx.fillStyle = '#1D2430';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = '#404D63';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(turbX, turbY, turbR, 0, TAU);
  ctx.fillStyle = '#161C26';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0035;
  ctx.strokeStyle = '#47566E';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(turbX, turbY, turbR * 0.80, 0, TAU);
  ctx.fillStyle = '#0E121A';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0022;
  ctx.strokeStyle = mixColor([112, 48, 22], [255, 145, 0], s3Weight);
  ctx.stroke();

  // Seamless Integrated Turbine Angle:
  // Exact 12 full revolutions over 20s; angular velocity peaks cleanly in Scene 3 (u = 5/6) via + sign!
  const nTotalRev = 12;
  const boostCycleAmp = 4;
  const peakPhi = 5 / 6;
  const turbAngle =
    TAU *
    (nTotalRev * u +
      (boostCycleAmp * (Math.sin(TAU * (u - peakPhi)) - Math.sin(-TAU * peakPhi))) / TAU);

  ctx.save();
  ctx.translate(turbX, turbY);
  ctx.rotate(turbAngle);

  const bladeCount = 8;
  for (let b = 0; b < bladeCount; b++) {
    ctx.save();
    ctx.rotate((b / bladeCount) * TAU);
    ctx.beginPath();
    ctx.moveTo(turbR * 0.22, -turbR * 0.055);
    ctx.quadraticCurveTo(turbR * 0.48, -turbR * 0.16, turbR * 0.73, -turbR * 0.04);
    ctx.lineTo(turbR * 0.73, turbR * 0.055);
    ctx.quadraticCurveTo(turbR * 0.48, -turbR * 0.04, turbR * 0.22, turbR * 0.055);
    ctx.closePath();

    const bladeGrad = ctx.createLinearGradient(turbR * 0.2, 0, turbR * 0.74, 0);
    bladeGrad.addColorStop(0, '#FF9100');
    bladeGrad.addColorStop(1, s3Weight > 0.35 ? '#FFC400' : '#FF6D33');
    ctx.fillStyle = bladeGrad;
    ctx.fill();
    ctx.restore();
  }

  ctx.beginPath();
  ctx.arc(0, 0, turbR * 0.25, 0, TAU);
  ctx.fillStyle = '#2B3648';
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = '#FFC400';
  ctx.stroke();

  for (let k = 0; k < 4; k++) {
    const ka = (k / 4) * TAU;
    ctx.beginPath();
    ctx.moveTo(Math.cos(ka) * turbR * 0.08, Math.sin(ka) * turbR * 0.08);
    ctx.lineTo(Math.cos(ka) * turbR * 0.19, Math.sin(ka) * turbR * 0.19);
    ctx.lineWidth = minSide * 0.0022;
    ctx.strokeStyle = '#E0F7FA';
    ctx.stroke();
  }
  ctx.restore();

  roundRectPath(turbX - minSide * 0.018, turbY - turbR - minSide * 0.006, minSide * 0.036, minSide * 0.015, minSide * 0.004);
  ctx.fillStyle = '#3B485E';
  ctx.fill();

  // E. Clean Power Output Substation Module
  const subTop = height * 0.205;
  const subH = surfaceY - subTop;
  chamferRectPath(subLeft, subTop, subW, subH, minSide * 0.014);
  const subGrad = ctx.createLinearGradient(subLeft, subTop, subLeft + subW, surfaceY);
  subGrad.addColorStop(0, '#1A2332');
  subGrad.addColorStop(1, '#101620');
  ctx.fillStyle = subGrad;
  ctx.fill();
  ctx.lineWidth = minSide * 0.0024;
  ctx.strokeStyle = mixColor([58, 76, 102], [0, 229, 255], s3Weight * 0.7);
  ctx.stroke();

  // Power Output Meter peaks cleanly in Scene 3 (u = 5/6) via + sign!
  const powerLoad = 0.24 + 0.70 * (0.5 + 0.5 * Math.cos(TAU * (u - 5 / 6)));

  const dialX = subLeft + subW * 0.5;
  const dialY = subTop + subH * 0.34;
  const dialR = minSide * 0.038;

  ctx.beginPath();
  ctx.arc(dialX, dialY, dialR, 0, TAU);
  ctx.fillStyle = '#0D131C';
  ctx.fill();

  ctx.beginPath();
  ctx.arc(dialX, dialY, dialR * 0.80, -Math.PI * 0.75, Math.PI * 0.75);
  ctx.lineWidth = minSide * 0.0062;
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#1E2A3B';
  ctx.stroke();

  const dialEnd = lerp(-Math.PI * 0.75, Math.PI * 0.75, powerLoad);
  const dialGrad = ctx.createLinearGradient(dialX - dialR, dialY, dialX + dialR, dialY);
  dialGrad.addColorStop(0, '#FF9100');
  dialGrad.addColorStop(0.55, '#FFC400');
  dialGrad.addColorStop(1, '#00E5FF');
  ctx.beginPath();
  ctx.arc(dialX, dialY, dialR * 0.80, -Math.PI * 0.75, dialEnd);
  ctx.lineWidth = minSide * 0.0062;
  ctx.lineCap = 'round';
  ctx.strokeStyle = dialGrad;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(dialX, dialY, dialR * 0.24, 0, TAU);
  ctx.fillStyle = mixColor([255, 145, 0], [0, 229, 255], powerLoad);
  ctx.fill();

  const barCount = 6;
  const barZoneLeft = subLeft + subW * 0.15;
  const barZoneW = subW * 0.70;
  const barZoneBot = surfaceY - subH * 0.11;
  const barMaxH = subH * 0.26;
  const barGap = barZoneW * 0.055;
  const singleBarW = (barZoneW - barGap * (barCount - 1)) / barCount;

  for (let b = 0; b < barCount; b++) {
    const bx = barZoneLeft + b * (singleBarW + barGap);
    const barFrac = clamp01((powerLoad * barCount - b) / 1.0);
    const bh = barMaxH * ((b + 2) / (barCount + 1));

    roundRectPath(bx, barZoneBot - bh, singleBarW, bh, singleBarW * 0.28);
    ctx.fillStyle = '#151E2B';
    ctx.fill();

    if (barFrac > 0.01) {
      const fillH = bh * barFrac;
      roundRectPath(bx, barZoneBot - fillH, singleBarW, fillH, singleBarW * 0.28);
      ctx.fillStyle = b >= 4 ? '#00E5FF' : b >= 2 ? '#FFC400' : '#FF9100';
      ctx.fill();
    }
  }

  // 9. Thermodynamic Flow Packets (Strictly Contained Inside Borehole & Conduit Tracks)

  // A. Cold Injection Flow Down Left Borehole (starts strictly below surfaceY so wellhead remains clean)
  const coldCount = 5;
  for (let i = 0; i < coldCount; i++) {
    const p = (u * 3 + i / coldCount) % 1;
    const py = lerp(surfaceY + minSide * 0.018, channelY[2] - minSide * 0.008, p);
    const len = minSide * lerp(0.016, 0.024, s2Weight);
    const tailY = Math.max(surfaceY + minSide * 0.006, py - len);

    const g = ctx.createLinearGradient(inX, tailY, inX, py);
    g.addColorStop(0, 'rgba(0, 229, 255, 0)');
    g.addColorStop(1, 'rgba(132, 255, 255, 0.96)');
    ctx.beginPath();
    ctx.moveTo(inX, tailY);
    ctx.lineTo(inX, py);
    ctx.lineWidth = minSide * 0.0065;
    ctx.lineCap = 'round';
    ctx.strokeStyle = g;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(inX, py, minSide * 0.0046, 0, TAU);
    ctx.fillStyle = '#B2FEFF';
    ctx.fill();
  }

  // B. Thermal Conversion Across the 3 Horizontal Reservoir Channels
  for (let c = 0; c < channelPts.length; c++) {
    const pts = channelPts[c];
    const pktPerChan = 3;
    for (let i = 0; i < pktPerChan; i++) {
      const p = (u * 3 + c * 0.28 + i / pktPerChan) % 1;
      const pos = samplePolyline(pts, p);
      const col =
        p < 0.5
          ? mixColor([0, 229, 255], [255, 196, 0], p * 2)
          : mixColor([255, 196, 0], [255, 61, 0], (p - 0.5) * 2);

      const r = minSide * (0.0044 + 0.0014 * Math.sin(Math.PI * p));
      ctx.beginPath();
      ctx.arc(pos[0], pos[1], r, 0, TAU);
      ctx.fillStyle = col;
      ctx.fill();
    }
  }

  // C. Superheated Steam Extraction Rising Up Right Borehole (stops cleanly at surfaceY collar)
  const steamCount = 6;
  for (let i = 0; i < steamCount; i++) {
    const p = (u * 4 + i / steamCount) % 1;
    const py = lerp(channelY[0] + minSide * 0.012, surfaceY + minSide * 0.016, p);
    const len = minSide * lerp(0.020, 0.032, s2Weight * 0.7 + s3Weight * 0.3);
    const tailY = Math.min(channelY[2], py + len);

    const g = ctx.createLinearGradient(outX, tailY, outX, py);
    g.addColorStop(0, 'rgba(255, 61, 0, 0)');
    g.addColorStop(1, 'rgba(255, 196, 0, 0.96)');
    ctx.beginPath();
    ctx.moveTo(outX, tailY);
    ctx.lineTo(outX, py);
    ctx.lineWidth = minSide * 0.0070;
    ctx.lineCap = 'round';
    ctx.strokeStyle = g;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(outX, py, minSide * 0.0050, 0, TAU);
    ctx.fillStyle = '#FFE082';
    ctx.fill();
  }

  // D. High-Pressure Steam Manifold (Flash Separator -> Turbine Intake)
  for (let i = 0; i < 3; i++) {
    const p = (u * 5 + i / 3) % 1;
    const pos = samplePolyline(steamManifoldPts, p);
    ctx.beginPath();
    ctx.arc(pos[0], pos[1], minSide * 0.0045 * Math.sin(Math.PI * p), 0, TAU);
    ctx.fillStyle = '#FFC400';
    ctx.fill();
  }

  // E. Overhead Condenser Bridge Steam -> Coolant Transition
  const bridgePkts = 7;
  for (let i = 0; i < bridgePkts; i++) {
    const p = (u * 3 + i / bridgePkts) % 1;
    const pos = samplePolyline(bridgePts, p);
    const col =
      p < 0.45
        ? mixColor([255, 145, 0], [224, 247, 250], p / 0.45)
        : mixColor([224, 247, 250], [0, 229, 255], (p - 0.45) / 0.55);

    ctx.beginPath();
    ctx.arc(pos[0], pos[1], minSide * 0.0048, 0, TAU);
    ctx.fillStyle = col;
    ctx.fill();
  }

  // F. Cold Condensate Return (Cooling Tower -> Wellhead)
  for (let i = 0; i < 2; i++) {
    const p = (u * 4 + i / 2) % 1;
    const pos = samplePolyline(coldReturnPts, p);
    ctx.beginPath();
    ctx.arc(pos[0], pos[1], minSide * 0.0042, 0, TAU);
    ctx.fillStyle = '#00E5FF';
    ctx.fill();
  }

  // G. Clean Electric Power Pulses (Turbine -> Power Substation Module)
  for (let i = 0; i < 3; i++) {
    const p = (u * 5 + i / 3) % 1;
    const pos = samplePolyline(powerBusPts, p);
    const sz = minSide * (0.0040 + 0.0016 * s3Weight) * Math.sin(Math.PI * p);
    ctx.beginPath();
    ctx.arc(pos[0], pos[1], sz, 0, TAU);
    ctx.fillStyle = mixColor([255, 196, 0], [0, 229, 255], p);
    ctx.fill();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;
  const easeInOutCubic = (x) => {
    const c = clamp01(x);
    return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
  };
  const easeInOutSine = (x) => 0.5 - 0.5 * Math.cos(Math.PI * clamp01(x));

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPolylinePoints(pts) {
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
  }

  function samplePolyline(pts, s) {
    const segLens = [];
    let total = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(len);
      total += len;
    }
    const target = clamp01(s) * total;
    let acc = 0;
    for (let i = 0; i < segLens.length; i++) {
      const len = segLens[i];
      if (acc + len >= target || i === segLens.length - 1) {
        const local = len > 0 ? (target - acc) / len : 0;
        return {
          x: lerp(pts[i][0], pts[i + 1][0], local),
          y: lerp(pts[i][1], pts[i + 1][1], local),
          ang: Math.atan2(pts[i + 1][1] - pts[i][1], pts[i + 1][0] - pts[i][0]),
        };
      }
      acc += len;
    }
    return { x: pts[0][0], y: pts[0][1], ang: 0 };
  }

  // =========================================================================
  // 1. CLEAN DEEP ABYSSAL NAVY BACKGROUND (ZERO GLOW, ZERO EDGE FRAMES)
  // =========================================================================
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#040812");
  bgGrad.addColorStop(0.55, "#071022");
  bgGrad.addColorStop(1, "#03060E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  const atmoGrad = ctx.createLinearGradient(0, 0, 0, height * 0.48);
  atmoGrad.addColorStop(0, "rgba(10, 26, 52, 0.28)");
  atmoGrad.addColorStop(1, "rgba(6, 14, 30, 0)");
  ctx.fillStyle = atmoGrad;
  ctx.fillRect(0, 0, width, height * 0.48);

  // =========================================================================
  // 2. SEAMLESS 4-SCENE HYDROLOGICAL CYCLE ENVELOPES (5s EACH, TOTAL 20s)
  // =========================================================================
  let evapStrength = 0.25;
  let rightCloudAlpha = 0.55;
  let rightCloudScale = 0.72;
  let rightCloudX = width * 0.740;
  let transitCloudAlpha = 0.0;
  let transitCloudX = width * 0.740;
  let transitCloudScale = 1.0;
  let rainIntensity = 0.0;
  let riverTrace = 0.0;
  let riverGlow = 0.0;
  let aquTrace = 0.0;
  let aquGlow = 0.0;
  let waveAmpFactor = 0.65;

  if (currentScene === 0) {
    // Scene 0 (0 - 5s): Ocean Wave Oscillation & Warm Vapor Evaporation
    const e = easeInOutCubic(sceneProgress);
    evapStrength = lerp(0.25, 1.0, Math.sin(clamp01(sceneProgress * 1.15) * Math.PI * 0.5));
    rightCloudAlpha = lerp(0.55, 1.0, e);
    rightCloudScale = lerp(0.72, 1.0, e);
    transitCloudAlpha = 0.0;
    rainIntensity = 0.0;
    riverTrace = 0.0;
    riverGlow = 0.0;
    aquTrace = 0.0;
    aquGlow = 0.0;
    waveAmpFactor = lerp(0.65, 1.0, e);
  } else if (currentScene === 1) {
    // Scene 1 (5 - 10s): Cloud Condensation & Atmospheric Transport Right -> Left
    const e = easeInOutCubic(sceneProgress);
    evapStrength = lerp(1.0, 0.30, easeInOutSine(sceneProgress));
    rightCloudAlpha = 0.0;
    transitCloudAlpha = 1.0;
    transitCloudX = lerp(width * 0.740, width * 0.285, e);
    transitCloudScale = lerp(1.0, 1.06, Math.sin(sceneProgress * Math.PI));
    rainIntensity = easeInOutSine(clamp01((sceneProgress - 0.78) / 0.22)) * 0.35;
    riverTrace = 0.0;
    riverGlow = 0.0;
    aquTrace = 0.0;
    aquGlow = 0.0;
    waveAmpFactor = lerp(1.0, 0.75, e);
  } else if (currentScene === 2) {
    // Scene 2 (10 - 15s): Precision Rainfall & Surface River Activation
    const e = easeInOutCubic(sceneProgress);
    evapStrength = 0.30;
    rightCloudAlpha = 0.0;
    transitCloudAlpha = 1.0;
    transitCloudX = width * 0.285;
    transitCloudScale = lerp(1.0, 0.94, e * 0.4);
    rainIntensity = lerp(0.35, 1.0, Math.sin(clamp01(sceneProgress / 0.45) * Math.PI * 0.5));
    if (sceneProgress > 0.75) {
      rainIntensity = lerp(1.0, 0.65, (sceneProgress - 0.75) / 0.25);
    }
    riverTrace = easeInOutSine(clamp01((sceneProgress - 0.10) / 0.75));
    riverGlow = clamp01(riverTrace * 1.25);
    aquTrace = easeInOutSine(clamp01((sceneProgress - 0.35) / 0.65)) * 0.55;
    aquGlow = clamp01((sceneProgress - 0.35) / 0.45);
    waveAmpFactor = lerp(0.75, 0.88, e);
  } else {
    // Scene 3 (15 - 20s): Subterranean Aquifer Recharge & Natural Fade Reset (no backward water flow!)
    const e = easeInOutCubic(sceneProgress);
    rainIntensity = lerp(0.65, 0.0, clamp01(sceneProgress / 0.35));
    transitCloudAlpha = lerp(1.0, 0.0, easeInOutSine(clamp01((sceneProgress - 0.22) / 0.58)));
    transitCloudX = width * 0.285;
    transitCloudScale = lerp(0.96, 0.76, clamp01((sceneProgress - 0.22) / 0.58));

    const reform = easeInOutSine(clamp01((sceneProgress - 0.42) / 0.58));
    rightCloudAlpha = lerp(0.0, 0.55, reform);
    rightCloudScale = lerp(0.55, 0.72, reform);
    evapStrength = lerp(0.30, 0.25, e);

    riverTrace = 1.0;
    aquTrace = lerp(0.55, 1.0, easeInOutSine(clamp01(sceneProgress / 0.42)));

    if (sceneProgress < 0.58) {
      riverGlow = 1.0;
      aquGlow = 1.0;
      waveAmpFactor = lerp(0.88, 0.92, sceneProgress / 0.58);
    } else {
      const r = easeInOutSine((sceneProgress - 0.58) / 0.42);
      riverGlow = lerp(1.0, 0.0, r);
      aquGlow = lerp(1.0, 0.0, r);
      waveAmpFactor = lerp(0.92, 0.65, r);
    }
  }

  // =========================================================================
  // 3. ARCHITECTURAL CROSS-SECTION TERRAIN & OCEAN GEOMETRY (OPEN SIDES, NO BOX FRAME)
  // =========================================================================
  const leftMargin = width * 0.060;
  const shoreX = width * 0.580;
  const rightMargin = width * 0.940;
  const seaLevelY = height * 0.575;
  const aquiferTopY = height * 0.665;
  const aquiferBotY = height * 0.790;
  const baseDatumY = height * 0.890;

  function getTerrainY(x) {
    const pts = [
      [leftMargin, height * 0.485],
      [width * 0.135, height * 0.372],
      [width * 0.220, height * 0.452],
      [width * 0.350, height * 0.458],
      [width * 0.465, height * 0.520],
      [shoreX, seaLevelY],
    ];
    if (x <= pts[0][0]) return pts[0][1];
    if (x >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
    for (let i = 0; i < pts.length - 1; i++) {
      if (x >= pts[i][0] && x <= pts[i + 1][0]) {
        const f = (x - pts[i][0]) / (pts[i + 1][0] - pts[i][0]);
        return lerp(pts[i][1], pts[i + 1][1], f);
      }
    }
    return seaLevelY;
  }

  const terrainPts = [
    [leftMargin, height * 0.485],
    [width * 0.135, height * 0.372],
    [width * 0.220, height * 0.452],
    [width * 0.350, height * 0.458],
    [width * 0.465, height * 0.520],
    [shoreX, seaLevelY],
  ];

  // Subtle upper sky altitude wind contour lines strictly above cloud ceiling
  ctx.strokeStyle = "rgba(0, 176, 255, 0.16)";
  ctx.lineWidth = minSide * 0.0014;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(width * 0.08, height * 0.072);
  ctx.lineTo(width * 0.92, height * 0.072);
  ctx.stroke();

  // 3a. Ocean Basin Water Body (Strictly Clipped Inside Right Basin)
  const shelfMidX = width * 0.655;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(shoreX, seaLevelY - minSide * 0.030);
  ctx.lineTo(rightMargin, seaLevelY - minSide * 0.030);
  ctx.lineTo(rightMargin, aquiferBotY);
  ctx.lineTo(shelfMidX, aquiferBotY);
  ctx.lineTo(shoreX, seaLevelY);
  ctx.closePath();
  ctx.clip();

  // Deep Ocean Backdrop Layer (Wave Layer 3)
  ctx.beginPath();
  const waveSteps = 56;
  for (let i = 0; i <= waveSteps; i++) {
    const f = i / waveSteps;
    const wx = lerp(shoreX, rightMargin, f);
    const edgeTaper = clamp01(f * 5);
    const wy = seaLevelY - minSide * 0.005 +
      Math.sin(f * 3.0 * TAU - u * 4 * TAU + 1.2) * minSide * 0.007 * waveAmpFactor * edgeTaper;
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineTo(rightMargin, aquiferBotY);
  ctx.lineTo(shoreX, aquiferBotY);
  ctx.closePath();
  ctx.fillStyle = "#062547";
  ctx.fill();

  // Mid Ocean Water Body (Wave Layer 2)
  ctx.beginPath();
  for (let i = 0; i <= waveSteps; i++) {
    const f = i / waveSteps;
    const wx = lerp(shoreX, rightMargin, f);
    const edgeTaper = clamp01(f * 5);
    const wy = seaLevelY +
      Math.sin(f * 2.5 * TAU - u * 4 * TAU + 0.4) * minSide * 0.009 * waveAmpFactor * edgeTaper +
      Math.sin(f * 5.0 * TAU + u * 2 * TAU) * minSide * 0.003 * waveAmpFactor * edgeTaper;
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineTo(rightMargin, aquiferBotY);
  ctx.lineTo(shoreX, aquiferBotY);
  ctx.closePath();
  const midSeaGrad = ctx.createLinearGradient(0, seaLevelY, 0, aquiferBotY);
  midSeaGrad.addColorStop(0, "rgba(2, 136, 209, 0.72)");
  midSeaGrad.addColorStop(0.55, "rgba(4, 58, 114, 0.85)");
  midSeaGrad.addColorStop(1, "rgba(4, 24, 58, 0.96)");
  ctx.fillStyle = midSeaGrad;
  ctx.fill();

  for (let d = 1; d <= 3; d++) {
    const dy = lerp(seaLevelY + minSide * 0.04, aquiferBotY - minSide * 0.025, d / 4);
    ctx.beginPath();
    for (let i = 0; i <= 32; i++) {
      const f = i / 32;
      const wx = lerp(shoreX + minSide * 0.04, rightMargin - minSide * 0.015, f);
      const wy = dy + Math.sin(f * 3 * TAU - u * 2 * TAU + d) * minSide * 0.003;
      if (i === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.strokeStyle = "rgba(0, 176, 255, 0.16)";
    ctx.lineWidth = minSide * 0.0014;
    ctx.stroke();
  }

  // Front Ocean Crest Stroke (Wave Layer 1)
  ctx.beginPath();
  for (let i = 0; i <= waveSteps; i++) {
    const f = i / waveSteps;
    const wx = lerp(shoreX, rightMargin, f);
    const edgeTaper = clamp01(f * 5);
    const wy = seaLevelY + minSide * 0.004 +
      Math.sin(f * 3.0 * TAU - u * 4 * TAU - 0.6) * minSide * 0.008 * waveAmpFactor * edgeTaper;
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.strokeStyle = "#00B0FF";
  ctx.lineWidth = minSide * 0.0024;
  ctx.stroke();

  // Submarine Groundwater Discharge Bubbles strictly inside underwater shelf
  const subPortsY = [height * 0.692, height * 0.728, height * 0.764];
  const subPortsX = [lerp(shoreX, shelfMidX, 0.56), lerp(shoreX, shelfMidX, 0.72), lerp(shoreX, shelfMidX, 0.88)];
  if (aquGlow > 0.05) {
    for (let pi = 0; pi < subPortsX.length; pi++) {
      const px0 = subPortsX[pi];
      const py0 = subPortsY[pi];
      for (let b = 0; b < 2; b++) {
        const bp = (u * 5 + pi * 0.28 + b * 0.5) % 1;
        const bx = px0 + minSide * 0.014 * bp + Math.sin(bp * TAU * 2) * minSide * 0.004;
        const by = lerp(py0, seaLevelY + minSide * 0.028, bp);
        const ba = Math.sin(bp * Math.PI) * aquGlow;
        ctx.beginPath();
        ctx.arc(bx, by, minSide * 0.0032, 0, TAU);
        ctx.fillStyle = `rgba(29, 233, 182, ${(0.85 * ba).toFixed(3)})`;
        ctx.fill();
      }
    }
  }
  ctx.restore();

  // 3b. Geological Cross-Section Strata (Closed flush along diagonal underwater shelf slope, open sides!)
  const aquSlopeTopX = lerp(shoreX, shelfMidX, (aquiferTopY - seaLevelY) / (aquiferBotY - seaLevelY));

  // Top Permeable Crust Layer (aligned cleanly along underwater slope down to aquiferTopY)
  ctx.beginPath();
  ctx.moveTo(terrainPts[0][0], terrainPts[0][1]);
  for (let i = 1; i < terrainPts.length; i++) {
    ctx.lineTo(terrainPts[i][0], terrainPts[i][1]);
  }
  ctx.lineTo(aquSlopeTopX, aquiferTopY);
  ctx.lineTo(leftMargin, aquiferTopY);
  ctx.closePath();
  const crustGrad = ctx.createLinearGradient(0, height * 0.37, 0, aquiferTopY);
  crustGrad.addColorStop(0, "#10213E");
  crustGrad.addColorStop(1, "#0B162C");
  ctx.fillStyle = crustGrad;
  ctx.fill();

  // Porous Aquifer Stratum Layer
  ctx.beginPath();
  ctx.moveTo(leftMargin, aquiferTopY);
  ctx.lineTo(aquSlopeTopX, aquiferTopY);
  ctx.lineTo(shelfMidX, aquiferBotY);
  ctx.lineTo(leftMargin, aquiferBotY);
  ctx.closePath();
  ctx.fillStyle = "#081226";
  ctx.fill();

  // Impermeable Bedrock Base Layer
  ctx.beginPath();
  ctx.moveTo(leftMargin, aquiferBotY);
  ctx.lineTo(rightMargin, aquiferBotY);
  ctx.lineTo(rightMargin, baseDatumY);
  ctx.lineTo(leftMargin, baseDatumY);
  ctx.closePath();
  ctx.fillStyle = "#050B18";
  ctx.fill();

  // Internal Geological Horizon Divider Lines (open-ended horizontal strata, NO outer box border frame!)
  ctx.strokeStyle = "#163868";
  ctx.lineWidth = minSide * 0.0016;
  ctx.beginPath();
  ctx.moveTo(leftMargin, aquiferTopY);
  ctx.lineTo(aquSlopeTopX, aquiferTopY);
  ctx.moveTo(leftMargin, aquiferBotY);
  ctx.lineTo(rightMargin, aquiferBotY);
  ctx.moveTo(leftMargin, baseDatumY);
  ctx.lineTo(rightMargin, baseDatumY);
  ctx.stroke();

  // Crisp bright mountain & valley crest rim highlight + underwater shelf line
  drawPolylinePoints(terrainPts);
  ctx.strokeStyle = "#00B0FF";
  ctx.lineWidth = minSide * 0.0024;
  ctx.lineJoin = "round";
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(shoreX, seaLevelY);
  ctx.lineTo(shelfMidX, aquiferBotY);
  ctx.strokeStyle = "#0288D1";
  ctx.lineWidth = minSide * 0.0022;
  ctx.stroke();

  // =========================================================================
  // 4. SURFACE RIVER CHANNEL, PERCOLATION CONDUITS & AQUIFER NETWORK
  // =========================================================================
  const riverPts = [
    [width * 0.235, getTerrainY(width * 0.235) - minSide * 0.003],
    [width * 0.350, getTerrainY(width * 0.350) - minSide * 0.003],
    [width * 0.465, getTerrainY(width * 0.465) - minSide * 0.003],
    [shoreX, seaLevelY - minSide * 0.002],
  ];

  ctx.strokeStyle = "rgba(0, 176, 255, 0.20)";
  ctx.lineWidth = minSide * 0.0052;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  drawPolylinePoints(riverPts);
  ctx.stroke();

  if (riverTrace > 0.02 && riverGlow > 0.01) {
    let riverLen = 0;
    for (let i = 1; i < riverPts.length; i++) {
      riverLen += Math.hypot(riverPts[i][0] - riverPts[i - 1][0], riverPts[i][1] - riverPts[i - 1][1]);
    }
    ctx.save();
    ctx.globalAlpha = riverGlow;
    ctx.strokeStyle = "#00B0FF";
    ctx.lineWidth = minSide * 0.0046;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.setLineDash([riverLen * riverTrace, riverLen]);
    drawPolylinePoints(riverPts);
    ctx.stroke();
    ctx.restore();

    for (let k = 0; k < 3; k++) {
      const rp = (u * 5 + k * 0.33) % 1;
      if (rp > 0.05 && rp < Math.min(0.95, riverTrace - 0.03)) {
        const pos = samplePolyline(riverPts, rp);
        const fade = Math.sin(clamp01(rp / Math.max(0.08, riverTrace)) * Math.PI);
        ctx.save();
        ctx.translate(pos.x, pos.y);
        ctx.rotate(pos.ang);
        ctx.globalAlpha = clamp01(fade * 1.4) * riverGlow;
        ctx.fillStyle = "#E0F7FA";
        roundRectPath(-minSide * 0.010, -minSide * 0.0024, minSide * 0.020, minSide * 0.0048, minSide * 0.0024);
        ctx.fill();
        ctx.restore();
      }
    }
  }

  // Three Non-Crossing Vertical Percolation Shafts & Horizontal Aquifer Channels
  const shaftXs = [width * 0.240, width * 0.315, width * 0.390];
  const aquLaneYs = subPortsY;

  const aquRoutes = [
    [
      [shaftXs[0], getTerrainY(shaftXs[0]) + minSide * 0.006],
      [shaftXs[0], aquLaneYs[2] - minSide * 0.012],
      [shaftXs[0] + minSide * 0.012, aquLaneYs[2]],
      [subPortsX[2], aquLaneYs[2]],
    ],
    [
      [shaftXs[1], getTerrainY(shaftXs[1]) + minSide * 0.006],
      [shaftXs[1], aquLaneYs[1] - minSide * 0.012],
      [shaftXs[1] + minSide * 0.012, aquLaneYs[1]],
      [subPortsX[1], aquLaneYs[1]],
    ],
    [
      [shaftXs[2], getTerrainY(shaftXs[2]) + minSide * 0.006],
      [shaftXs[2], aquLaneYs[0] - minSide * 0.012],
      [shaftXs[2] + minSide * 0.012, aquLaneYs[0]],
      [subPortsX[0], aquLaneYs[0]],
    ],
  ];

  // Porous Aquifer Node Circles
  for (let li = 0; li < aquLaneYs.length; li++) {
    const startX = shaftXs[2 - li] + minSide * 0.04;
    const endX = subPortsX[li] - minSide * 0.03;
    const nodeCount = 5;
    for (let ni = 0; ni < nodeCount; ni++) {
      const nx = lerp(startX, endX, ni / (nodeCount - 1));
      const ny = aquLaneYs[li];
      ctx.beginPath();
      ctx.arc(nx, ny, minSide * 0.0055, 0, TAU);
      ctx.fillStyle = "#081226";
      ctx.fill();
      ctx.strokeStyle = aquGlow > 0.35 + ni * 0.1 ? "#1DE9B6" : "#163868";
      ctx.lineWidth = minSide * 0.0014;
      ctx.stroke();
    }
  }

  for (let i = 0; i < aquRoutes.length; i++) {
    const pts = aquRoutes[i];
    ctx.strokeStyle = "rgba(29, 233, 182, 0.16)";
    ctx.lineWidth = minSide * 0.0028;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    if (aquTrace > 0.02 && aquGlow > 0.01) {
      let totalLen = 0;
      for (let k = 1; k < pts.length; k++) {
        totalLen += Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]);
      }
      ctx.save();
      ctx.globalAlpha = aquGlow;
      ctx.strokeStyle = "#1DE9B6";
      ctx.lineWidth = minSide * 0.0030;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.setLineDash([totalLen * aquTrace, totalLen]);
      drawPolylinePoints(pts);
      ctx.stroke();
      ctx.restore();

      const cp = (u * 4 + i * 0.27) % 1;
      if (cp > 0.06 && cp < Math.min(0.94, aquTrace - 0.03)) {
        const pos = samplePolyline(pts, cp);
        const fade = Math.sin(clamp01(cp / Math.max(0.1, aquTrace)) * Math.PI);
        ctx.save();
        ctx.translate(pos.x, pos.y);
        ctx.rotate(pos.ang);
        ctx.globalAlpha = clamp01(fade * 1.4) * aquGlow;
        ctx.fillStyle = "#E0F7FA";
        roundRectPath(-minSide * 0.008, -minSide * 0.0024, minSide * 0.016, minSide * 0.0048, minSide * 0.0024);
        ctx.fill();
        ctx.restore();
      }
    }

    const lastPt = pts[pts.length - 1];
    ctx.beginPath();
    ctx.arc(lastPt[0], lastPt[1], minSide * 0.0035, 0, TAU);
    ctx.fillStyle = aquGlow > 0.5 ? "#1DE9B6" : "#0288D1";
    ctx.fill();
  }

  // =========================================================================
  // 5. EVAPORATION ZONE (5 STRICTLY PARALLEL NON-CROSSING ASCENDING LANES)
  // =========================================================================
  const evapCenter = width * 0.740;
  const evapSpread = minSide * 0.034;
  const evapXs = [
    evapCenter - evapSpread * 2,
    evapCenter - evapSpread,
    evapCenter,
    evapCenter + evapSpread,
    evapCenter + evapSpread * 2,
  ];
  const evapStartY = seaLevelY - minSide * 0.025;
  const evapEndY = height * 0.228;

  for (let ei = 0; ei < evapXs.length; ei++) {
    const baseX = evapXs[ei];
    const pts = [];
    const segs = 28;
    for (let s = 0; s <= segs; s++) {
      const f = s / segs;
      const y = lerp(evapStartY, evapEndY, f);
      const env = Math.sin(f * Math.PI);
      const x = baseX + Math.sin(f * 2.0 * TAU - u * 4 * TAU + ei * 1.1) * minSide * 0.006 * env;
      pts.push([x, y]);
    }

    ctx.strokeStyle = `rgba(224, 247, 250, ${(0.04 + 0.16 * evapStrength).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0018;
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    for (let p = 0; p < 2; p++) {
      const vp = (u * 4 + ei * 0.19 + p * 0.5) % 1;
      const pos = samplePolyline(pts, vp);
      const fade = Math.sin(vp * Math.PI) * evapStrength;
      ctx.save();
      ctx.translate(pos.x, pos.y);
      ctx.rotate(pos.ang);
      ctx.globalAlpha = clamp01(fade * 1.3);
      ctx.fillStyle = ei % 2 === 0 ? "#E0F7FA" : "#00B0FF";
      roundRectPath(-minSide * 0.0085, -minSide * 0.0024, minSide * 0.017, minSide * 0.0048, minSide * 0.0024);
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // 6. PRECISION LAYERED GEOMETRIC VECTOR CLOUDS (EXACT TANGENT-INTERSECTING LOBES)
  // =========================================================================
  function upperCircleIntersect(cA, cB) {
    const dx = cB.x - cA.x;
    const dy = cB.y - cA.y;
    const d = Math.hypot(dx, dy);
    const a = (cA.r * cA.r - cB.r * cB.r + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, cA.r * cA.r - a * a));
    const px = cA.x + (a * dx) / d;
    const py = cA.y + (a * dy) / d;
    const ix1 = px + (h * (-dy)) / d;
    const iy1 = py + (h * dx) / d;
    const ix2 = px - (h * (-dy)) / d;
    const iy2 = py - (h * dx) / d;
    return iy1 < iy2 ? [ix1, iy1] : [ix2, iy2];
  }

  function tracePlumpCloudPath(lobes, baseY) {
    const ints = [];
    for (let i = 0; i < lobes.length - 1; i++) {
      ints.push(upperCircleIntersect(lobes[i], lobes[i + 1]));
    }
    ctx.beginPath();
    ctx.moveTo(lobes[0].x, baseY);
    for (let i = 0; i < lobes.length; i++) {
      const c = lobes[i];
      const startAng =
        i === 0
          ? Math.PI * 0.5
          : Math.atan2(ints[i - 1][1] - c.y, ints[i - 1][0] - c.x);
      const endAng =
        i === lobes.length - 1
          ? Math.PI * 0.5
          : Math.atan2(ints[i][1] - c.y, ints[i][0] - c.x);
      ctx.arc(c.x, c.y, c.r, startAng, endAng, false);
    }
    ctx.closePath();
  }

  function drawVectorCloud(cx, cy, scale, alpha, rainGlow) {
    if (alpha <= 0.01) return;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(scale, scale);
    ctx.globalAlpha = alpha;

    const baseY = minSide * 0.042;
    const lobes = [
      { x: -minSide * 0.072, y: baseY - minSide * 0.032, r: minSide * 0.032 },
      { x: -minSide * 0.018, y: -minSide * 0.008, r: minSide * 0.052 },
      { x: minSide * 0.036, y: minSide * 0.002, r: minSide * 0.040 },
      { x: minSide * 0.076, y: baseY - minSide * 0.028, r: minSide * 0.028 },
    ];

    // Primary hero cloud silhouette (zero behind-cloud bleed or overlap)
    tracePlumpCloudPath(lobes, baseY);
    const cloudGrad = ctx.createLinearGradient(0, -minSide * 0.062, 0, baseY);
    cloudGrad.addColorStop(0, rainGlow > 0.3 ? "#E0F7FA" : "#F0FBFF");
    cloudGrad.addColorStop(0.42, rainGlow > 0.3 ? "#1FB6FF" : "#2D8CD5");
    cloudGrad.addColorStop(1, "#0B356E");
    ctx.fillStyle = cloudGrad;
    ctx.fill();

    // Clipped layered vector interior highlights & underbelly depth band
    ctx.save();
    tracePlumpCloudPath(lobes, baseY);
    ctx.clip();

    ctx.fillStyle = rainGlow > 0.3 ? "rgba(6, 30, 68, 0.55)" : "rgba(8, 34, 72, 0.42)";
    ctx.fillRect(-minSide * 0.13, baseY - minSide * 0.016, minSide * 0.26, minSide * 0.020);

    // Crisp curved inner highlight crescent inside primary dome
    ctx.beginPath();
    ctx.arc(lobes[1].x, lobes[1].y, lobes[1].r * 0.78, Math.PI * 1.12, Math.PI * 1.72, false);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.52)";
    ctx.lineWidth = minSide * 0.0026;
    ctx.lineCap = "round";
    ctx.stroke();

    // Secondary crisp crescent highlight inside right-center dome
    ctx.beginPath();
    ctx.arc(lobes[2].x, lobes[2].y, lobes[2].r * 0.74, Math.PI * 1.18, Math.PI * 1.70, false);
    ctx.strokeStyle = "rgba(224, 247, 250, 0.38)";
    ctx.lineWidth = minSide * 0.0020;
    ctx.lineCap = "round";
    ctx.stroke();

    ctx.restore();

    // Outer crisp vector outline
    tracePlumpCloudPath(lobes, baseY);
    ctx.strokeStyle = rainGlow > 0.3 ? "#1DE9B6" : "#B2EBF2";
    ctx.lineWidth = minSide * 0.0022;
    ctx.lineJoin = "round";
    ctx.stroke();

    ctx.restore();
  }

  if (currentScene === 1 && transitCloudAlpha > 0.2) {
    const trailFade = Math.sin(sceneProgress * Math.PI);
    ctx.save();
    ctx.globalAlpha = trailFade * 0.55;
    ctx.strokeStyle = "#00B0FF";
    ctx.lineWidth = minSide * 0.0018;
    ctx.lineCap = "round";
    for (let ti = 0; ti < 3; ti++) {
      const ty = height * (0.140 + ti * 0.028);
      const tx0 = transitCloudX + minSide * 0.118 + ti * minSide * 0.014;
      const tx1 = tx0 + width * (0.068 - ti * 0.012);
      if (tx1 < width * 0.92) {
        ctx.beginPath();
        ctx.moveTo(tx0, ty);
        ctx.lineTo(tx1, ty);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  const cloudY = height * 0.165;
  drawVectorCloud(rightCloudX, cloudY, rightCloudScale, rightCloudAlpha, 0.0);
  drawVectorCloud(transitCloudX, cloudY, transitCloudScale, transitCloudAlpha, rainIntensity);

  // =========================================================================
  // 7. PRECISION RAINFALL STREAKS & SURFACE SPLASH ARCS (ABOVE TERRAIN ONLY)
  // =========================================================================
  if (rainIntensity > 0.02) {
    const rainCols = 7;
    const rainSpanW = minSide * 0.144;
    const rainStartX = width * 0.285 - rainSpanW * 0.5;
    const cloudBaseY = cloudY + minSide * 0.046;

    for (let ci = 0; ci < rainCols; ci++) {
      const rx = rainStartX + (ci / (rainCols - 1)) * rainSpanW;
      const groundHitY = getTerrainY(rx) - minSide * 0.004;

      for (let d = 0; d < 2; d++) {
        const dp = (u * 8 + ci * 0.13 + d * 0.5) % 1;
        const dropHeadY = lerp(cloudBaseY, groundHitY, dp);
        const dropLen = minSide * 0.024;
        const dropTailY = Math.max(cloudBaseY, dropHeadY - dropLen);
        const fadeIn = clamp01(dp * 5);
        const fadeOut = clamp01((1 - dp) * 6);

        ctx.save();
        ctx.globalAlpha = rainIntensity * fadeIn * fadeOut;
        ctx.strokeStyle = d === 0 ? "#00B0FF" : "#E0F7FA";
        ctx.lineWidth = minSide * 0.0022;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(rx, dropTailY);
        ctx.lineTo(rx, dropHeadY);
        ctx.stroke();
        ctx.restore();

        if (dp > 0.85) {
          const sp = (dp - 0.85) / 0.15;
          const sr = lerp(minSide * 0.002, minSide * 0.011, sp);
          ctx.save();
          ctx.globalAlpha = rainIntensity * (1 - sp) * 0.75;
          ctx.strokeStyle = "#E0F7FA";
          ctx.lineWidth = minSide * 0.0014;
          ctx.beginPath();
          ctx.ellipse(rx, groundHitY, sr, sr * 0.35, 0, Math.PI, TAU);
          ctx.stroke();
          ctx.restore();
        }
      }
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;
  const easeInOutCubic = (x) => {
    const c = clamp01(x);
    return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
  };
  const easeInOutSine = (x) => 0.5 - 0.5 * Math.cos(Math.PI * clamp01(x));

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function drawHexagon(cx, cy, r) {
    ctx.beginPath();
    for (let v = 0; v < 6; v++) {
      const ang = (v * Math.PI) / 3;
      const vx = cx + Math.cos(ang) * r;
      const vy = cy + Math.sin(ang) * r;
      if (v === 0) ctx.moveTo(vx, vy);
      else ctx.lineTo(vx, vy);
    }
    ctx.closePath();
  }

  function drawPolylinePoints(pts) {
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
  }

  function samplePolyline(pts, s) {
    const segLens = [];
    let total = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(len);
      total += len;
    }
    const target = clamp01(s) * total;
    let acc = 0;
    for (let i = 0; i < segLens.length; i++) {
      const len = segLens[i];
      if (acc + len >= target || i === segLens.length - 1) {
        const local = len > 0 ? (target - acc) / len : 0;
        return {
          x: lerp(pts[i][0], pts[i + 1][0], local),
          y: lerp(pts[i][1], pts[i + 1][1], local),
          ang: Math.atan2(pts[i + 1][1] - pts[i][1], pts[i + 1][0] - pts[i][0]),
        };
      }
      acc += len;
    }
    return { x: pts[0][0], y: pts[0][1], ang: 0 };
  }

  // =========================================================================
  // 1. CLEAN CHARCOAL INDIGO BACKGROUND (ZERO GLOW, ZERO EDGE FRAMES)
  // =========================================================================
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#070612");
  bgGrad.addColorStop(0.55, "#0D0B1E");
  bgGrad.addColorStop(1, "#05040C");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle flat subterranean stratum below vault collar (zero glow)
  const groundY = height * 0.720;
  const subGrad = ctx.createLinearGradient(0, groundY, 0, height);
  subGrad.addColorStop(0, "rgba(18, 13, 38, 0.55)");
  subGrad.addColorStop(1, "rgba(5, 4, 12, 0.90)");
  ctx.fillStyle = subGrad;
  ctx.fillRect(0, groundY, width, height - groundY);

  // =========================================================================
  // 2. SEAMLESS 3-SCENE CHOREOGRAPHY ENVELOPES (TOTAL 20s)
  // =========================================================================
  let intakeFlow = 0.45;
  let emissionLoad = 0.72;
  let reactorPower = 0.35;
  let cleanAirFlow = 0.22;
  let purityLevel = 0.22;
  let equilibriumPos = 0.28; // 0 = high emission load, 1 = net-zero balanced
  let sequestrationFlow = 0.18;
  let vaultLock = 1 / 6;

  if (currentScene === 0) {
    // Scene 0 (0 - 6.67s): Turbulent Carbon Intake & Load Surge
    const e = easeInOutCubic(sceneProgress);
    intakeFlow = lerp(0.45, 1.0, e);
    emissionLoad = lerp(0.72, 0.95, Math.sin(clamp01(sceneProgress * 1.1) * Math.PI * 0.5));
    reactorPower = lerp(0.35, 0.72, e);
    cleanAirFlow = lerp(0.22, 0.35, e);
    purityLevel = lerp(0.22, 0.32, e);
    equilibriumPos = lerp(0.28, 0.38, e);
    sequestrationFlow = lerp(0.18, 0.30, e);
    vaultLock = lerp(1 / 6, 1.6 / 6, e);
  } else if (currentScene === 1) {
    // Scene 1 (6.67 - 13.33s): Molecular Filtration & Color Conversion inside Reactor
    const e = easeInOutCubic(sceneProgress);
    intakeFlow = 1.0;
    emissionLoad = lerp(0.95, 0.35, e);
    reactorPower = lerp(0.72, 1.0, Math.sin(clamp01(sceneProgress / 0.6) * Math.PI * 0.5));
    cleanAirFlow = lerp(0.35, 0.92, e);
    purityLevel = lerp(0.32, 0.88, e);
    equilibriumPos = lerp(0.38, 0.85, e);
    sequestrationFlow = lerp(0.30, 0.90, easeInOutSine(clamp01((sceneProgress - 0.15) / 0.85)));
    vaultLock = lerp(1.6 / 6, 4.0 / 6, easeInOutSine(clamp01((sceneProgress - 0.2) / 0.8)));
  } else {
    // Scene 2 (13.33 - 20.00s): Net-Zero Atmosphere Release, Carbon Lock & Seamless Reset
    if (sceneProgress < 0.62) {
      const d = easeInOutCubic(clamp01(sceneProgress / 0.48));
      intakeFlow = lerp(1.0, 0.82, d);
      emissionLoad = lerp(0.35, 0.16, d);
      reactorPower = 1.0;
      cleanAirFlow = lerp(0.92, 1.0, d);
      purityLevel = lerp(0.88, 1.0, d);
      equilibriumPos = lerp(0.85, 1.0, d);
      sequestrationFlow = lerp(0.90, 1.0, d);
      vaultLock = lerp(4.0 / 6, 1.0, d);
    } else {
      const r = easeInOutSine((sceneProgress - 0.62) / 0.38);
      intakeFlow = lerp(0.82, 0.45, r);
      emissionLoad = lerp(0.16, 0.72, r);
      reactorPower = lerp(1.0, 0.35, r);
      cleanAirFlow = lerp(1.0, 0.22, r);
      purityLevel = lerp(1.0, 0.22, r);
      equilibriumPos = lerp(1.0, 0.28, r);
      sequestrationFlow = lerp(1.0, 0.18, r);
      vaultLock = lerp(1.0, 1 / 6, r);
    }
  }

  // =========================================================================
  // 3. CENTRAL GEOMETRIC COORDINATES (STRICT NON-OVERLAPPING ZONES)
  // =========================================================================
  const rx = width * 0.500;
  const ry = height * 0.455;
  const rOuter = minSide * 0.165;
  const rMid = minSide * 0.132;
  const rInner = minSide * 0.098;
  const rCore = minSide * 0.068;
  const reactorLeftX = rx - rOuter;
  const reactorRightX = rx + rOuter;
  const reactorTopY = ry - rOuter;
  const reactorBotY = ry + rOuter;

  const laneYs = [height * 0.385, height * 0.455, height * 0.525];
  const intakeMouthX = width * 0.255;
  const intakeStartX = width * 0.060;
  const diffuserMouthX = width * 0.745;
  const outputEndX = width * 0.940;

  // =========================================================================
  // 4. UPPER TELEMETRY ZONE: FLANKING GAUGES & NET-ZERO BALANCE SLIDER
  // =========================================================================
  const leftGaugeX = width * 0.155;
  const rightGaugeX = width * 0.845;
  const gaugeY = height * 0.170;
  const gaugeR = minSide * 0.068;

  // Clean non-crossing telemetry connector traces from gauges down to manifolds
  const leftTelemetryPts = [
    [leftGaugeX, gaugeY + gaugeR + minSide * 0.008],
    [leftGaugeX, height * 0.305],
    [width * 0.310, height * 0.305],
    [width * 0.310, height * 0.355],
  ];
  const rightTelemetryPts = [
    [rightGaugeX, gaugeY + gaugeR + minSide * 0.008],
    [rightGaugeX, height * 0.305],
    [width * 0.690, height * 0.305],
    [width * 0.690, height * 0.355],
  ];

  ctx.strokeStyle = "rgba(157, 78, 221, 0.38)";
  ctx.lineWidth = minSide * 0.0020;
  ctx.lineJoin = "round";
  drawPolylinePoints(leftTelemetryPts);
  ctx.stroke();

  ctx.strokeStyle = "rgba(128, 255, 219, 0.42)";
  drawPolylinePoints(rightTelemetryPts);
  ctx.stroke();

  // Helper to render crisp symmetric telemetry ring gauges
  function drawRingGauge(cx, cy, value, primaryColor, secondaryColor, spinDir) {
    ctx.beginPath();
    ctx.arc(cx, cy, gaugeR * 1.14, 0, TAU);
    ctx.fillStyle = "#0C0A1B";
    ctx.fill();
    ctx.strokeStyle = "rgba(157, 78, 221, 0.25)";
    ctx.lineWidth = minSide * 0.0016;
    ctx.stroke();

    // 20 radial calibration ticks
    for (let i = 0; i < 20; i++) {
      const ang = -Math.PI * 0.5 + (i / 20) * TAU;
      const r0 = gaugeR * (i % 5 === 0 ? 0.92 : 0.97);
      const r1 = gaugeR * 1.06;
      ctx.strokeStyle = i / 20 <= value ? primaryColor : "rgba(255, 255, 255, 0.14)";
      ctx.lineWidth = minSide * (i % 5 === 0 ? 0.0020 : 0.0012);
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(ang) * r0, cy + Math.sin(ang) * r0);
      ctx.lineTo(cx + Math.cos(ang) * r1, cy + Math.sin(ang) * r1);
      ctx.stroke();
    }

    // Dormant track + active measurement arc
    ctx.beginPath();
    ctx.arc(cx, cy, gaugeR * 0.78, 0, TAU);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
    ctx.lineWidth = minSide * 0.006;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, gaugeR * 0.78, -Math.PI * 0.5, -Math.PI * 0.5 + clamp01(value) * TAU);
    ctx.strokeStyle = primaryColor;
    ctx.lineWidth = minSide * 0.006;
    ctx.lineCap = "round";
    ctx.stroke();

    // Inner rotating indicator segments (2 exact revs / 20s)
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(u * 2 * TAU * spinDir);
    ctx.strokeStyle = secondaryColor;
    ctx.lineWidth = minSide * 0.0022;
    for (let s = 0; s < 3; s++) {
      const a0 = s * (TAU / 3) + 0.25;
      ctx.beginPath();
      ctx.arc(0, 0, gaugeR * 0.50, a0, a0 + TAU / 3 - 0.50);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(0, 0, gaugeR * 0.20, 0, TAU);
    ctx.fillStyle = primaryColor;
    ctx.fill();
    ctx.restore();
  }

  drawRingGauge(leftGaugeX, gaugeY, emissionLoad, "#EF233C", "#9D4EDD", 1);
  drawRingGauge(rightGaugeX, gaugeY, purityLevel, "#80FFDB", "#F8F9FA", -1);

  // Upper Center Net-Zero Equilibrium Balance Slider (strictly above Reactor)
  const balW = width * 0.250;
  const balH = minSide * 0.036;
  const balX = rx - balW * 0.5;
  const balY = height * 0.152;

  // Vertical telemetry spine linking Reactor top to Equilibrium Balance Bar
  ctx.strokeStyle = "rgba(128, 255, 219, 0.35)";
  ctx.lineWidth = minSide * 0.0020;
  ctx.beginPath();
  ctx.moveTo(rx, balY + balH * 0.5);
  ctx.lineTo(rx, reactorTopY);
  ctx.stroke();

  chamferRectPath(balX, balY - balH * 0.5, balW, balH, minSide * 0.007);
  ctx.fillStyle = "#0E0C20";
  ctx.fill();
  ctx.strokeStyle = equilibriumPos > 0.7 ? "#80FFDB" : "#9D4EDD";
  ctx.lineWidth = minSide * 0.0018;
  ctx.stroke();

  // Inner Spectrum Track Bar (Crimson-Violet -> Mint)
  const trackPad = balW * 0.08;
  const trackX = balX + trackPad;
  const trackW = balW - trackPad * 2;
  const trackH = minSide * 0.007;
  const trackGrad = ctx.createLinearGradient(trackX, 0, trackX + trackW, 0);
  trackGrad.addColorStop(0, "#EF233C");
  trackGrad.addColorStop(0.45, "#9D4EDD");
  trackGrad.addColorStop(1, "#80FFDB");
  roundRectPath(trackX, balY - trackH * 0.5, trackW, trackH, trackH * 0.5);
  ctx.fillStyle = "rgba(255, 255, 255, 0.09)";
  ctx.fill();

  const indX = lerp(trackX + minSide * 0.008, trackX + trackW - minSide * 0.008, equilibriumPos);
  roundRectPath(trackX, balY - trackH * 0.5, indX - trackX, trackH, trackH * 0.5);
  ctx.fillStyle = trackGrad;
  ctx.fill();

  // Crisp sliding equilibrium diamond marker
  const dSz = minSide * 0.011;
  ctx.beginPath();
  ctx.moveTo(indX, balY - dSz);
  ctx.lineTo(indX + dSz * 0.75, balY);
  ctx.lineTo(indX, balY + dSz);
  ctx.lineTo(indX - dSz * 0.75, balY);
  ctx.closePath();
  ctx.fillStyle = "#F8F9FA";
  ctx.fill();
  ctx.strokeStyle = equilibriumPos > 0.65 ? "#80FFDB" : "#EF233C";
  ctx.lineWidth = minSide * 0.0018;
  ctx.stroke();

  // =========================================================================
  // 5. LEFT INTAKE CORRIDOR & TAPERED MANIFOLD (CARBON EMISSION STREAM)
  // =========================================================================
  // Intake Funnel Manifold (OPEN THROAT MOUTH at intakeMouthX so particle lanes never cross a vertical wall!)
  const manTopOuter = laneYs[0] - minSide * 0.032;
  const manBotOuter = laneYs[2] + minSide * 0.032;
  const manTopInner = ry - rCore * 0.85;
  const manBotInner = ry + rCore * 0.85;

  ctx.beginPath();
  ctx.moveTo(intakeMouthX, manTopOuter);
  ctx.lineTo(reactorLeftX + minSide * 0.005, manTopInner);
  ctx.lineTo(reactorLeftX + minSide * 0.005, manBotInner);
  ctx.lineTo(intakeMouthX, manBotOuter);
  ctx.closePath();
  const manLeftGrad = ctx.createLinearGradient(intakeMouthX, 0, reactorLeftX, 0);
  manLeftGrad.addColorStop(0, "rgba(20, 13, 38, 0.35)");
  manLeftGrad.addColorStop(1, "#1C1233");
  ctx.fillStyle = manLeftGrad;
  ctx.fill();

  // Stroke ONLY top & bottom converging manifold walls + small flange lips (keeping entrance open!)
  ctx.strokeStyle = "#9D4EDD";
  ctx.lineWidth = minSide * 0.0022;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(intakeMouthX, manTopOuter);
  ctx.lineTo(reactorLeftX + minSide * 0.005, manTopInner);
  ctx.moveTo(intakeMouthX, manBotOuter);
  ctx.lineTo(reactorLeftX + minSide * 0.005, manBotInner);
  // Subtle top/bottom intake lip brackets strictly outside outer particle lanes
  ctx.moveTo(intakeMouthX, manTopOuter - minSide * 0.007);
  ctx.lineTo(intakeMouthX, manTopOuter + minSide * 0.009);
  ctx.moveTo(intakeMouthX, manBotOuter - minSide * 0.009);
  ctx.lineTo(intakeMouthX, manBotOuter + minSide * 0.007);
  ctx.stroke();

  // Two crisp 2D harmonic intake compression vanes inside manifold throat
  const vaneX = lerp(intakeMouthX, reactorLeftX, 0.42);
  const vaneAmp = minSide * 0.010 * (0.4 + 0.6 * intakeFlow);
  for (let side = -1; side <= 1; side += 2) {
    const vy = ry + side * (minSide * 0.034 - Math.sin(u * 6 * TAU) * vaneAmp * 0.5);
    roundRectPath(vaneX - minSide * 0.012, vy - minSide * 0.003, minSide * 0.024, minSide * 0.006, minSide * 0.003);
    ctx.fillStyle = "#EF233C";
    ctx.fill();
  }

  // 3 Strictly Separated Carbon Intake Streams (x: 0.060*W -> reactorLeftX)
  for (let li = 0; li < laneYs.length; li++) {
    const baseY = laneYs[li];
    const pts = [];
    const steps = 36;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      const px = lerp(intakeStartX, reactorLeftX, f);
      let py = baseY;
      if (px <= intakeMouthX) {
        const localF = (px - intakeStartX) / (intakeMouthX - intakeStartX);
        py = baseY + Math.sin(localF * 2.0 * TAU - u * 4 * TAU + li * 1.2) * minSide * 0.010 * Math.sin(localF * Math.PI);
      } else {
        const funF = (px - intakeMouthX) / (reactorLeftX - intakeMouthX);
        py = lerp(baseY, ry + (li - 1) * minSide * 0.024, easeInOutSine(funF));
      }
      pts.push([px, py]);
    }

    ctx.strokeStyle = `rgba(239, 35, 60, ${(0.18 + 0.30 * intakeFlow).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0022;
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    // Animated Carbon Emission Hexagons travelling into Reactor
    const count = 4;
    for (let pi = 0; pi < count; pi++) {
      const p = (u * 5 + li * 0.19 + pi / count) % 1;
      const pos = samplePolyline(pts, p);
      const fade = Math.sin(p * Math.PI);
      const pR = minSide * 0.0062;
      ctx.save();
      ctx.globalAlpha = clamp01(fade * 1.45) * (0.45 + 0.55 * intakeFlow);
      drawHexagon(pos.x, pos.y, pR);
      ctx.fillStyle = (pi + li) % 2 === 0 ? "#EF233C" : "#9D4EDD";
      ctx.fill();
      ctx.strokeStyle = "#FFB3C1";
      ctx.lineWidth = minSide * 0.0010;
      ctx.stroke();
      ctx.restore();
    }
  }

  // =========================================================================
  // 6. RIGHT PURIFIED ATMOSPHERE DIFFUSER (OPEN THROAT) & CLEAN-AIR STREAMS
  // =========================================================================
  ctx.beginPath();
  ctx.moveTo(reactorRightX - minSide * 0.005, manTopInner);
  ctx.lineTo(diffuserMouthX, manTopOuter);
  ctx.lineTo(diffuserMouthX, manBotOuter);
  ctx.lineTo(reactorRightX - minSide * 0.005, manBotInner);
  ctx.closePath();
  const manRightGrad = ctx.createLinearGradient(reactorRightX, 0, diffuserMouthX, 0);
  manRightGrad.addColorStop(0, "#0D242E");
  manRightGrad.addColorStop(1, "rgba(11, 25, 38, 0.35)");
  ctx.fillStyle = manRightGrad;
  ctx.fill();

  ctx.strokeStyle = cleanAirFlow > 0.5 ? "#80FFDB" : "#2D7A78";
  ctx.lineWidth = minSide * 0.0022;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(reactorRightX - minSide * 0.005, manTopInner);
  ctx.lineTo(diffuserMouthX, manTopOuter);
  ctx.moveTo(reactorRightX - minSide * 0.005, manBotInner);
  ctx.lineTo(diffuserMouthX, manBotOuter);
  // Subtle top/bottom outlet lip brackets strictly outside outer particle lanes
  ctx.moveTo(diffuserMouthX, manTopOuter - minSide * 0.007);
  ctx.lineTo(diffuserMouthX, manTopOuter + minSide * 0.009);
  ctx.moveTo(diffuserMouthX, manBotOuter - minSide * 0.009);
  ctx.lineTo(diffuserMouthX, manBotOuter + minSide * 0.007);
  ctx.stroke();

  // 3 Strictly Separated Clean-Air Output Streams (reactorRightX -> 0.940*W)
  for (let li = 0; li < laneYs.length; li++) {
    const baseY = laneYs[li];
    const pts = [];
    const steps = 36;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      const px = lerp(reactorRightX, outputEndX, f);
      let py = baseY;
      if (px <= diffuserMouthX) {
        const funF = (px - reactorRightX) / (diffuserMouthX - reactorRightX);
        py = lerp(ry + (li - 1) * minSide * 0.024, baseY, easeInOutSine(funF));
      } else {
        const localF = (px - diffuserMouthX) / (outputEndX - diffuserMouthX);
        py = baseY + Math.sin(localF * 2.0 * TAU - u * 4 * TAU + li * 1.1) * minSide * 0.008 * Math.sin(localF * Math.PI);
      }
      pts.push([px, py]);
    }

    ctx.strokeStyle = `rgba(128, 255, 219, ${(0.18 + 0.42 * cleanAirFlow).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0024;
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    // Animated Purified Oxygen/Clean-Air Ring Molecules exiting right
    const count = 4;
    for (let pi = 0; pi < count; pi++) {
      const p = (u * 5 + li * 0.21 + pi / count) % 1;
      const pos = samplePolyline(pts, p);
      const fade = Math.sin(p * Math.PI);
      const pR = minSide * 0.0058;
      ctx.save();
      ctx.globalAlpha = clamp01(fade * 1.45) * (0.35 + 0.65 * cleanAirFlow);
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, pR, 0, TAU);
      ctx.fillStyle = "#80FFDB";
      ctx.fill();
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, pR * 0.45, 0, TAU);
      ctx.fillStyle = "#F8F9FA";
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // 7. BOTTOM CARBON SEQUESTRATION CONDUIT & MINERALIZATION VAULT
  // =========================================================================
  const vaultW = width * 0.250;
  const vaultH = height * 0.165;
  const vaultX = rx - vaultW * 0.5;
  const vaultY = height * 0.735;
  const pipeW = minSide * 0.034;

  // Vertical armored carbon sequestration pipe (reactorBotY -> vaultY)
  ctx.fillStyle = "#140D26";
  ctx.fillRect(rx - pipeW * 0.5, reactorBotY - minSide * 0.004, pipeW, vaultY - reactorBotY + minSide * 0.008);
  ctx.strokeStyle = "#9D4EDD";
  ctx.lineWidth = minSide * 0.0020;
  ctx.strokeRect(rx - pipeW * 0.5, reactorBotY - minSide * 0.004, pipeW, vaultY - reactorBotY + minSide * 0.008);

  // Inner violet sequestration stream & downward carbon pellets
  ctx.strokeStyle = `rgba(157, 78, 221, ${(0.28 + 0.65 * sequestrationFlow).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0036;
  ctx.beginPath();
  ctx.moveTo(rx, reactorBotY);
  ctx.lineTo(rx, vaultY);
  ctx.stroke();

  if (sequestrationFlow > 0.1) {
    for (let k = 0; k < 2; k++) {
      const cp = (u * 5 + k * 0.5) % 1;
      const py = lerp(reactorBotY + minSide * 0.012, vaultY - minSide * 0.012, cp);
      const fade = Math.sin(cp * Math.PI);
      ctx.save();
      ctx.globalAlpha = fade * sequestrationFlow;
      drawHexagon(rx, py, minSide * 0.0075);
      ctx.fillStyle = "#C77DFF";
      ctx.fill();
      ctx.strokeStyle = "#F8F9FA";
      ctx.lineWidth = minSide * 0.0010;
      ctx.stroke();
      ctx.restore();
    }
  }

  // Geological Carbon Sequestration Vault Enclosure
  chamferRectPath(vaultX, vaultY, vaultW, vaultH, minSide * 0.014);
  const vaultGrad = ctx.createLinearGradient(vaultX, vaultY, vaultX, vaultY + vaultH);
  vaultGrad.addColorStop(0, "#150E2A");
  vaultGrad.addColorStop(1, "#0B0718");
  ctx.fillStyle = vaultGrad;
  ctx.fill();
  ctx.strokeStyle = vaultLock > 0.65 ? "#C77DFF" : "#6D34B0";
  ctx.lineWidth = minSide * 0.0022;
  ctx.stroke();

  // 6 Symmetrical Mineralization Lock Cells inside Vault (3 cols x 2 rows)
  const vPadX = vaultW * 0.10;
  const vPadY = vaultH * 0.18;
  const vGapX = vaultW * 0.05;
  const vGapY = vaultH * 0.12;
  const cellW = (vaultW - vPadX * 2 - vGapX * 2) / 3;
  const cellH = (vaultH - vPadY * 2 - vGapY) / 2;

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const idx = row * 3 + col;
      const cx = vaultX + vPadX + col * (cellW + vGapX);
      const cy = vaultY + vPadY + row * (cellH + vGapY);
      const cFloor = idx / 6;
      const cCeil = (idx + 1) / 6;
      const fillAmt = clamp01((vaultLock - cFloor) / (cCeil - cFloor));

      chamferRectPath(cx, cy, cellW, cellH, minSide * 0.005);
      ctx.fillStyle = "#090614";
      ctx.fill();

      if (fillAmt > 0.02) {
        ctx.save();
        ctx.globalAlpha = fillAmt;
        chamferRectPath(cx, cy, cellW, cellH, minSide * 0.005);
        const cellGrad = ctx.createLinearGradient(cx, cy, cx + cellW, cy + cellH);
        cellGrad.addColorStop(0, "#7B2CBF");
        cellGrad.addColorStop(1, "#C77DFF");
        ctx.fillStyle = cellGrad;
        ctx.fill();

        // Crisp locked hexagonal crystal motif centered inside locked cell
        drawHexagon(cx + cellW * 0.5, cy + cellH * 0.5, Math.min(cellW, cellH) * 0.24);
        ctx.fillStyle = "#F8F9FA";
        ctx.fill();
        ctx.restore();
      }

      chamferRectPath(cx, cy, cellW, cellH, minSide * 0.005);
      ctx.strokeStyle = fillAmt > 0.5 ? "#E0AAFF" : "#3E2266";
      ctx.lineWidth = minSide * 0.0014;
      ctx.stroke();
    }
  }

  // Clean horizontal geological floor anchor rail flush with Vault bottom (no edge frame!)
  const baseLineY = vaultY + vaultH;
  ctx.strokeStyle = "#4B287D";
  ctx.lineWidth = minSide * 0.0020;
  ctx.beginPath();
  ctx.moveTo(width * 0.060, baseLineY);
  ctx.lineTo(vaultX, baseLineY);
  ctx.moveTo(vaultX + vaultW, baseLineY);
  ctx.lineTo(width * 0.940, baseLineY);
  ctx.stroke();

  // =========================================================================
  // 8. CENTER CONCENTRIC RING PURIFICATION REACTOR
  // =========================================================================
  // Outer housing disc
  ctx.beginPath();
  ctx.arc(rx, ry, rOuter * 1.04, 0, TAU);
  ctx.fillStyle = "#0B0919";
  ctx.fill();
  ctx.strokeStyle = reactorPower > 0.6 ? "#80FFDB" : "#9D4EDD";
  ctx.lineWidth = minSide * 0.0026;
  ctx.stroke();

  // Ring 3 (Outer segmented ring, +2 exact revs / 20s)
  ctx.save();
  ctx.translate(rx, ry);
  ctx.rotate(u * 2 * TAU);
  ctx.strokeStyle = "#9D4EDD";
  ctx.lineWidth = minSide * 0.0036;
  ctx.lineCap = "round";
  for (let i = 0; i < 6; i++) {
    const a0 = i * (TAU / 6) + 0.14;
    ctx.beginPath();
    ctx.arc(0, 0, rOuter * 0.93, a0, a0 + TAU / 6 - 0.28);
    ctx.stroke();
  }
  ctx.restore();

  // Ring 2 (Middle counter-rotating transition ring, -3 exact revs / 20s)
  ctx.save();
  ctx.translate(rx, ry);
  ctx.rotate(-u * 3 * TAU);
  ctx.strokeStyle = reactorPower > 0.6 ? "#80FFDB" : "#EF233C";
  ctx.lineWidth = minSide * 0.0040;
  ctx.lineCap = "round";
  for (let i = 0; i < 4; i++) {
    const a0 = i * (TAU / 4) + 0.18;
    ctx.beginPath();
    ctx.arc(0, 0, rMid, a0, a0 + TAU / 4 - 0.36);
    ctx.stroke();
  }
  ctx.restore();

  // Ring 1 (Inner high-speed separation ring, +4 exact revs / 20s)
  ctx.save();
  ctx.translate(rx, ry);
  ctx.rotate(u * 4 * TAU);
  ctx.strokeStyle = "#F8F9FA";
  ctx.globalAlpha = 0.45 + 0.55 * reactorPower;
  ctx.lineWidth = minSide * 0.0024;
  ctx.setLineDash([minSide * 0.016, minSide * 0.012]);
  ctx.beginPath();
  ctx.arc(0, 0, rInner, 0, TAU);
  ctx.stroke();
  ctx.restore();

  // Central Molecular Separation Core (Strictly Clipped Inside rCore)
  ctx.save();
  ctx.beginPath();
  ctx.arc(rx, ry, rCore, 0, TAU);
  const coreBg = ctx.createLinearGradient(rx - rCore, ry, rx + rCore, ry);
  coreBg.addColorStop(0, "#240E33");
  coreBg.addColorStop(0.5, "#15122B");
  coreBg.addColorStop(1, "#0B292E");
  ctx.fillStyle = coreBg;
  ctx.fill();
  ctx.clip();

  // Animated internal horizontal purification transition particles across core
  for (let k = 0; k < 5; k++) {
    const p = (u * 5 + k * 0.2) % 1;
    const px = lerp(rx - rCore, rx + rCore, p);
    const py = ry + Math.sin(p * TAU * 1.5 + k) * rCore * 0.38;
    const isClean = px >= rx;
    ctx.beginPath();
    ctx.arc(px, py, minSide * 0.0052, 0, TAU);
    ctx.fillStyle = isClean ? "#80FFDB" : "#EF233C";
    ctx.fill();
  }

  // Separated carbon pellets routing downward from laser membrane into sequestration pipe
  for (let k = 0; k < 2; k++) {
    const dp = (u * 5 + k * 0.5) % 1;
    const py = lerp(ry, ry + rCore, dp);
    const fade = Math.sin(dp * Math.PI) * sequestrationFlow;
    ctx.save();
    ctx.globalAlpha = clamp01(fade * 1.4);
    drawHexagon(rx, py, minSide * 0.0054);
    ctx.fillStyle = "#C77DFF";
    ctx.fill();
    ctx.restore();
  }

  // Vertical Separation Laser Membrane line + oscillating scanner node
  const scanY = ry + Math.sin(u * 6 * TAU) * (rCore * 0.72);
  ctx.strokeStyle = `rgba(248, 249, 250, ${(0.55 + 0.45 * reactorPower).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0024;
  ctx.beginPath();
  ctx.moveTo(rx, ry - rCore);
  ctx.lineTo(rx, ry + rCore);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(rx, scanY, minSide * 0.0065, 0, TAU);
  ctx.fillStyle = "#80FFDB";
  ctx.fill();

  ctx.restore();

  // Crisp inner core rim ring
  ctx.beginPath();
  ctx.arc(rx, ry, rCore, 0, TAU);
  ctx.strokeStyle = reactorPower > 0.5 ? "#80FFDB" : "#9D4EDD";
  ctx.lineWidth = minSide * 0.0024;
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;
  const easeInOutCubic = (x) => {
    const c = clamp01(x);
    return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
  };
  const easeInOutSine = (x) => 0.5 - 0.5 * Math.cos(Math.PI * clamp01(x));

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function cubicBezierPoint(p0, p1, p2, p3, s) {
    const inv = 1 - s;
    const inv2 = inv * inv;
    const s2 = s * s;
    const a = inv2 * inv;
    const b = 3 * inv2 * s;
    const c = 3 * inv * s2;
    const d = s2 * s;
    return [
      a * p0[0] + b * p1[0] + c * p2[0] + d * p3[0],
      a * p0[1] + b * p1[1] + c * p2[1] + d * p3[1],
    ];
  }

  // =========================================================================
  // 1. CLEAN DARK OBSIDIAN BACKGROUND (ZERO GLOW, ZERO EDGE FRAMES)
  // =========================================================================
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#090705");
  bgGrad.addColorStop(0.55, "#100B06");
  bgGrad.addColorStop(1, "#070503");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  const datumY = height * 0.865;
  const floorGrad = ctx.createLinearGradient(0, datumY, 0, height);
  floorGrad.addColorStop(0, "#120D08");
  floorGrad.addColorStop(1, "#070503");
  ctx.fillStyle = floorGrad;
  ctx.fillRect(0, datumY, width, height - datumY);

  // =========================================================================
  // 2. SEAMLESS 3-SCENE CHOREOGRAPHY ENVELOPES
  // =========================================================================
  let tiltFactor = 0.0;
  let scanSweep = -1;
  let beamStrength = 0.18;
  let photonStream = 0.0;
  let hexEnergy = 0.12;
  let busFlow = 0.15;
  let storageCharge = 2 / 12;
  let inverterPower = 0.2;

  if (currentScene === 0) {
    // Scene 1: Solar Tracking Alignment & Optical Matrix Calibration
    const e = easeInOutCubic(sceneProgress);
    tiltFactor = e;
    scanSweep = clamp01(sceneProgress / 0.82);
    beamStrength = lerp(0.18, 0.55, e);
    photonStream = clamp01((sceneProgress - 0.55) / 0.45) * 0.45;
    hexEnergy = lerp(0.12, 0.32, e);
    busFlow = lerp(0.15, 0.35, e);
    storageCharge = lerp(2 / 12, 3 / 12, e);
    inverterPower = lerp(0.2, 0.42, e);
  } else if (currentScene === 1) {
    // Scene 2: Photon Bombardment & Hex-Ripple Harvest
    const e = easeInOutCubic(sceneProgress);
    tiltFactor = 1.0;
    scanSweep = -1;
    beamStrength = lerp(0.55, 1.0, Math.sin(clamp01(sceneProgress * 1.3) * Math.PI * 0.5));
    photonStream = lerp(0.45, 1.0, clamp01(sceneProgress / 0.35));
    hexEnergy = lerp(0.32, 0.98, e);
    busFlow = lerp(0.35, 0.95, easeInOutSine(clamp01((sceneProgress - 0.2) / 0.7)));
    storageCharge = lerp(3 / 12, 7.5 / 12, easeInOutSine(clamp01((sceneProgress - 0.25) / 0.75)));
    inverterPower = lerp(0.42, 0.85, e);
  } else {
    // Scene 3: Inverter Saturation, Full Battery Storage & Seamless Return
    if (sceneProgress < 0.62) {
      const d = easeInOutCubic(clamp01(sceneProgress / 0.48));
      tiltFactor = 1.0;
      scanSweep = -1;
      beamStrength = lerp(1.0, 0.84, d);
      photonStream = lerp(1.0, 0.78, d);
      hexEnergy = lerp(0.98, 1.0, Math.sin(d * Math.PI * 0.5));
      busFlow = 1.0;
      storageCharge = lerp(7.5 / 12, 1.0, d);
      inverterPower = lerp(0.85, 1.0, d);
    } else {
      const r = easeInOutSine((sceneProgress - 0.62) / 0.38);
      tiltFactor = lerp(1.0, 0.0, r);
      scanSweep = -1;
      beamStrength = lerp(0.84, 0.18, r);
      photonStream = lerp(0.78, 0.0, r);
      hexEnergy = lerp(1.0, 0.12, r);
      busFlow = lerp(1.0, 0.15, r);
      storageCharge = lerp(1.0, 2 / 12, r);
      inverterPower = lerp(1.0, 0.2, r);
    }
  }

  // =========================================================================
  // 3. SOLAR COLLECTOR & CONCENTRIC ORBITAL RINGS (TOP LEFT-CENTER)
  // =========================================================================
  const sunX = width * 0.375;
  const sunY = height * 0.172;
  const sunR = minSide * 0.044;
  const ringR1 = minSide * 0.064;
  const ringR2 = minSide * 0.084;
  const ringR3 = minSide * 0.104;

  ctx.save();
  ctx.translate(sunX, sunY);

  // Ring 3 (Outer segmented concentrator arc, +2 exact revs over 20s)
  ctx.save();
  ctx.rotate(u * 2 * TAU);
  ctx.strokeStyle = `rgba(255, 179, 0, ${(0.28 + 0.42 * beamStrength).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0020;
  ctx.lineCap = "round";
  for (let i = 0; i < 6; i++) {
    const a0 = i * (TAU / 6) + 0.14;
    const a1 = a0 + (TAU / 6) - 0.28;
    ctx.beginPath();
    ctx.arc(0, 0, ringR3, a0, a1);
    ctx.stroke();
  }
  ctx.strokeStyle = `rgba(255, 229, 127, ${(0.3 + 0.4 * beamStrength).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0014;
  for (let i = 0; i < 12; i++) {
    const ang = i * (TAU / 12);
    ctx.beginPath();
    ctx.moveTo(Math.cos(ang) * (ringR3 - minSide * 0.004), Math.sin(ang) * (ringR3 - minSide * 0.004));
    ctx.lineTo(Math.cos(ang) * (ringR3 + minSide * 0.004), Math.sin(ang) * (ringR3 + minSide * 0.004));
    ctx.stroke();
  }
  ctx.restore();

  // Ring 2 (Middle counter-rotating aperture arcs, -3 exact revs over 20s)
  ctx.save();
  ctx.rotate(-u * 3 * TAU);
  ctx.strokeStyle = `rgba(255, 109, 0, ${(0.45 + 0.5 * beamStrength).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0028;
  ctx.lineCap = "round";
  for (let i = 0; i < 4; i++) {
    const a0 = i * (TAU / 4) + 0.20;
    const a1 = a0 + (TAU / 4) - 0.40;
    ctx.beginPath();
    ctx.arc(0, 0, ringR2, a0, a1);
    ctx.stroke();
  }
  ctx.restore();

  // Ring 1 (Inner fine focusing ring, +4 exact revs over 20s)
  ctx.save();
  ctx.rotate(u * 4 * TAU);
  ctx.strokeStyle = `rgba(255, 229, 127, ${(0.55 + 0.45 * beamStrength).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0022;
  ctx.setLineDash([minSide * 0.015, minSide * 0.010]);
  ctx.beginPath();
  ctx.arc(0, 0, ringR1, 0, TAU);
  ctx.stroke();
  ctx.restore();

  // 8 crisp tapered radial solar prism ticks strictly inside gap between sunR and ringR1
  ctx.save();
  ctx.rotate(-u * 1 * TAU);
  const rayIn = sunR + minSide * 0.004;
  const rayOut = lerp(sunR + minSide * 0.007, ringR1 - minSide * 0.004, 0.4 + 0.6 * beamStrength);
  ctx.fillStyle = `rgba(255, 229, 127, ${(0.35 + 0.55 * beamStrength).toFixed(3)})`;
  for (let k = 0; k < 8; k++) {
    const ang = k * (TAU / 8);
    ctx.save();
    ctx.rotate(ang);
    ctx.beginPath();
    ctx.moveTo(rayIn, -minSide * 0.0018);
    ctx.lineTo(rayOut, 0);
    ctx.lineTo(rayIn, minSide * 0.0018);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // Solar Core Disc (crisp vector edge, gradient strictly inside disc, zero background glow)
  const corePulse = 1 + 0.03 * Math.sin(u * 4 * TAU);
  const discR = sunR * corePulse;
  const sunGrad = ctx.createRadialGradient(0, 0, discR * 0.1, 0, 0, discR);
  sunGrad.addColorStop(0, "#FFF9D6");
  sunGrad.addColorStop(0.55, "#FFE57F");
  sunGrad.addColorStop(0.85, "#FFB300");
  sunGrad.addColorStop(1, "#FF6D00");
  ctx.beginPath();
  ctx.arc(0, 0, discR, 0, TAU);
  ctx.fillStyle = sunGrad;
  ctx.fill();

  ctx.strokeStyle = "#FFE57F";
  ctx.lineWidth = minSide * 0.0018;
  ctx.stroke();

  ctx.restore();

  // =========================================================================
  // 4. FIVE NON-OVERLAPPING STAGGERED PHOTOVOLTAIC PANEL COLUMNS
  // =========================================================================
  const panelW = width * 0.106;
  const basePanelH = minSide * 0.130;
  const apparentScaleY = lerp(0.78, 1.0, tiltFactor);
  const panelH = basePanelH * apparentScaleY;

  const panels = [
    { colX: width * 0.125, centerY: height * 0.635, row: 2, order: 0 },
    { colX: width * 0.250, centerY: height * 0.460, row: 1, order: 1 },
    { colX: width * 0.375, centerY: height * 0.635, row: 2, order: 2 },
    { colX: width * 0.500, centerY: height * 0.460, row: 1, order: 3 },
    { colX: width * 0.625, centerY: height * 0.635, row: 2, order: 4 },
  ];

  // =========================================================================
  // 5. OPTICAL GUIDE TRACKS, TAPERED LIGHT CONES & PHOTON CAPSULES
  // =========================================================================
  const opticalRoutes = [
    {
      p0: [sunX - ringR3 * 0.94, sunY + ringR3 * 0.34],
      p1: [width * 0.175, height * 0.220],
      p2: [width * 0.125, height * 0.275],
      p3: [width * 0.125, height * 0.340],
      targetX: panels[0].colX,
      targetY: panels[0].centerY - panelH * 0.5,
    },
    {
      p0: [sunX - ringR3 * 0.56, sunY + ringR3 * 0.83],
      p1: [width * 0.285, height * 0.285],
      p2: [width * 0.250, height * 0.305],
      p3: [width * 0.250, height * 0.340],
      targetX: panels[1].colX,
      targetY: panels[1].centerY - panelH * 0.5,
    },
    {
      p0: [sunX, sunY + ringR3],
      p1: [sunX, height * 0.300],
      p2: [sunX, height * 0.320],
      p3: [sunX, height * 0.340],
      targetX: panels[2].colX,
      targetY: panels[2].centerY - panelH * 0.5,
    },
    {
      p0: [sunX + ringR3 * 0.56, sunY + ringR3 * 0.83],
      p1: [width * 0.465, height * 0.285],
      p2: [width * 0.500, height * 0.305],
      p3: [width * 0.500, height * 0.340],
      targetX: panels[3].colX,
      targetY: panels[3].centerY - panelH * 0.5,
    },
    {
      p0: [sunX + ringR3 * 0.94, sunY + ringR3 * 0.34],
      p1: [width * 0.575, height * 0.220],
      p2: [width * 0.625, height * 0.275],
      p3: [width * 0.625, height * 0.340],
      targetX: panels[4].colX,
      targetY: panels[4].centerY - panelH * 0.5,
    },
  ];

  for (let i = 0; i < opticalRoutes.length; i++) {
    const rt = opticalRoutes[i];

    // Smooth flaring trapezoidal optical beam cone starting at zero alpha (no flat top edge!)
    const neckW = panelW * 0.08;
    const baseConeW = panelW * (0.48 + 0.26 * beamStrength);
    const coneGrad = ctx.createLinearGradient(0, rt.p3[1], 0, rt.targetY);
    coneGrad.addColorStop(0, "rgba(255, 229, 127, 0)");
    coneGrad.addColorStop(0.28, `rgba(255, 210, 80, ${(0.015 + 0.035 * beamStrength).toFixed(3)})`);
    coneGrad.addColorStop(1, `rgba(255, 179, 0, ${(0.03 + 0.11 * beamStrength).toFixed(3)})`);

    ctx.beginPath();
    ctx.moveTo(rt.targetX - neckW * 0.5, rt.p3[1]);
    ctx.lineTo(rt.targetX + neckW * 0.5, rt.p3[1]);
    ctx.lineTo(rt.targetX + baseConeW * 0.5, rt.targetY);
    ctx.lineTo(rt.targetX - baseConeW * 0.5, rt.targetY);
    ctx.closePath();
    ctx.fillStyle = coneGrad;
    ctx.fill();

    // Crisp optical trajectory fiber line from sun ring straight to panel surface
    ctx.beginPath();
    ctx.moveTo(rt.p0[0], rt.p0[1]);
    ctx.bezierCurveTo(rt.p1[0], rt.p1[1], rt.p2[0], rt.p2[1], rt.p3[0], rt.p3[1]);
    ctx.lineTo(rt.targetX, rt.targetY);
    ctx.strokeStyle = `rgba(255, 179, 0, ${(0.14 + 0.34 * beamStrength).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0020;
    ctx.lineCap = "round";
    ctx.stroke();

    // Animated Photon Capsules descending cleanly along exact route
    if (photonStream > 0.02) {
      const photonsPerLane = 2;
      for (let p = 0; p < photonsPerLane; p++) {
        const s = (u * 5 + i * 0.17 + p * 0.5) % 1;
        let px, py, ang;
        if (s < 0.38) {
          const bT = s / 0.38;
          const pt = cubicBezierPoint(rt.p0, rt.p1, rt.p2, rt.p3, bT);
          const ptNext = cubicBezierPoint(rt.p0, rt.p1, rt.p2, rt.p3, Math.min(1, bT + 0.02));
          px = pt[0];
          py = pt[1];
          ang = Math.atan2(ptNext[1] - pt[1], ptNext[0] - pt[0]);
        } else {
          const vT = (s - 0.38) / 0.62;
          px = rt.targetX;
          py = lerp(rt.p3[1], rt.targetY, vT);
          ang = Math.PI * 0.5;
        }

        const fadeEdge = Math.sin(clamp01(s) * Math.PI);
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(ang);
        ctx.globalAlpha = photonStream * clamp01(fadeEdge * 1.6);
        ctx.fillStyle = "#FFF5B8";
        roundRectPath(-minSide * 0.011, -minSide * 0.0028, minSide * 0.022, minSide * 0.0056, minSide * 0.0028);
        ctx.fill();
        ctx.restore();
      }
    }
  }

  // =========================================================================
  // 6. MOUNTING PEDESTALS, HORIZONTAL BUSBAR & GROUND SUPPORTS
  // =========================================================================
  const busY = height * 0.785;
  const towerLeftX = width * 0.745;
  const busStartX = panels[0].colX;
  const busEndX = towerLeftX;

  for (let i = 0; i < panels.length; i++) {
    const pn = panels[i];
    const pBotY = pn.centerY + panelH * 0.5;
    const strutW = minSide * 0.010;

    ctx.fillStyle = "#22180F";
    ctx.fillRect(pn.colX - strutW * 0.5, pBotY, strutW, busY - pBotY);
    ctx.strokeStyle = "#6B4E2E";
    ctx.lineWidth = minSide * 0.0014;
    ctx.strokeRect(pn.colX - strutW * 0.5, pBotY, strutW, busY - pBotY);

    ctx.strokeStyle = `rgba(255, 179, 0, ${(0.25 + 0.70 * busFlow).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0026;
    ctx.beginPath();
    ctx.moveTo(pn.colX, pBotY);
    ctx.lineTo(pn.colX, busY);
    ctx.stroke();

    if (busFlow > 0.18) {
      const pPhase = (u * 5 + i * 0.19) % 1;
      const py = lerp(pBotY + minSide * 0.008, busY - minSide * 0.008, pPhase);
      ctx.fillStyle = "#FFE57F";
      roundRectPath(pn.colX - minSide * 0.0025, py - minSide * 0.007, minSide * 0.005, minSide * 0.014, minSide * 0.0025);
      ctx.fill();
    }
  }

  const supportXs = [panels[0].colX, panels[2].colX, panels[4].colX];
  for (let i = 0; i < supportXs.length; i++) {
    const sx = supportXs[i];
    const legW = minSide * 0.016;
    ctx.fillStyle = "#1A130C";
    ctx.fillRect(sx - legW * 0.5, busY, legW, datumY - busY);
    ctx.strokeStyle = "#4E3922";
    ctx.lineWidth = minSide * 0.0014;
    ctx.strokeRect(sx - legW * 0.5, busY, legW, datumY - busY);

    ctx.fillStyle = "#2E2114";
    ctx.fillRect(sx - legW * 1.1, datumY - minSide * 0.008, legW * 2.2, minSide * 0.008);
  }

  // Unified Horizontal Collector Busbar cleanly anchored flush from left leg to Storage Tower
  const busH = minSide * 0.014;
  ctx.fillStyle = "#1C140C";
  ctx.fillRect(busStartX, busY - busH * 0.5, busEndX - busStartX, busH);
  ctx.strokeStyle = busFlow > 0.5 ? "#FFB300" : "#6B4E2E";
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeRect(busStartX, busY - busH * 0.5, busEndX - busStartX, busH);

  ctx.strokeStyle = `rgba(255, 179, 0, ${(0.3 + 0.7 * busFlow).toFixed(3)})`;
  ctx.lineWidth = minSide * 0.0032;
  ctx.beginPath();
  ctx.moveTo(busStartX, busY);
  ctx.lineTo(busEndX, busY);
  ctx.stroke();

  if (busFlow > 0.16) {
    for (let k = 0; k < 4; k++) {
      const bPhase = (u * 5 + k * 0.25) % 1;
      const bx = lerp(busStartX + minSide * 0.012, busEndX - minSide * 0.012, bPhase);
      ctx.fillStyle = "#FFF5B8";
      roundRectPath(bx - minSide * 0.010, busY - minSide * 0.0030, minSide * 0.020, minSide * 0.0060, minSide * 0.0030);
      ctx.fill();
    }
  }

  // Clean machined T-junction collars at every pedestal-busbar intersection
  for (let i = 0; i < panels.length; i++) {
    const jx = panels[i].colX;
    const jSize = minSide * 0.020;
    roundRectPath(jx - jSize * 0.5, busY - jSize * 0.5, jSize, jSize, minSide * 0.004);
    ctx.fillStyle = "#2E2012";
    ctx.fill();
    ctx.strokeStyle = busFlow > 0.45 ? "#FFB300" : "#8A6228";
    ctx.lineWidth = minSide * 0.0016;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(jx, busY, minSide * 0.0034, 0, TAU);
    ctx.fillStyle = busFlow > 0.45 ? "#FFE57F" : "#8A6228";
    ctx.fill();
  }

  // =========================================================================
  // 7. RENDER 5 PHOTOVOLTAIC PANELS WITH CLIPPED HEXAGONAL CELL GRIDS
  // =========================================================================
  for (let i = 0; i < panels.length; i++) {
    const pn = panels[i];
    const px = pn.colX - panelW * 0.5;
    const py = pn.centerY - panelH * 0.5;

    const hingeW = minSide * 0.007;
    const hingeH = minSide * 0.018;
    ctx.fillStyle = "#3D2C1B";
    ctx.fillRect(px - hingeW * 0.6, pn.centerY - hingeH * 0.5, hingeW, hingeH);
    ctx.fillRect(px + panelW - hingeW * 0.4, pn.centerY - hingeH * 0.5, hingeW, hingeH);

    chamferRectPath(px, py, panelW, panelH, minSide * 0.009);
    const bezelGrad = ctx.createLinearGradient(px, py, px, py + panelH);
    bezelGrad.addColorStop(0, "#332416");
    bezelGrad.addColorStop(1, "#1A120A");
    ctx.fillStyle = bezelGrad;
    ctx.fill();
    ctx.strokeStyle = hexEnergy > 0.5 ? "#FFB300" : "#8A6228";
    ctx.lineWidth = minSide * 0.0020;
    ctx.stroke();

    const inset = minSide * 0.008;
    const innerX = px + inset;
    const innerY = py + inset;
    const innerW = panelW - inset * 2;
    const innerH = panelH - inset * 2;

    ctx.save();
    chamferRectPath(innerX, innerY, innerW, innerH, minSide * 0.005);
    ctx.fillStyle = "#110B06";
    ctx.fill();
    ctx.clip();

    const hexCols = 6;
    const hexRows = 4;
    const hexR = innerW / (hexCols * 1.58);
    const dx = hexR * 1.56;
    const dy = hexR * Math.sqrt(3) * 0.94 * apparentScaleY;
    const gridStartX = innerX + (innerW - (hexCols - 1) * dx) * 0.5;
    const gridStartY = innerY + (innerH - (hexRows - 1) * dy) * 0.5;

    const rippleSpeed = u * 4;
    const impactX = pn.colX;
    const impactY = innerY;

    for (let r = 0; r < hexRows; r++) {
      for (let c = 0; c < hexCols; c++) {
        const cx = gridStartX + c * dx;
        const cy = gridStartY + r * dy + (c % 2 === 1 ? dy * 0.5 : 0) - dy * 0.25;

        const distNorm = Math.hypot(cx - impactX, cy - impactY) / (innerW * 0.9);
        const rippleWave = 0.5 + 0.5 * Math.sin((rippleSpeed - distNorm * 0.85 - pn.order * 0.14) * TAU);
        const cellActive = clamp01(hexEnergy * (0.58 + 0.42 * rippleWave));

        ctx.beginPath();
        for (let v = 0; v < 6; v++) {
          const ang = (v * Math.PI) / 3;
          const vx = cx + Math.cos(ang) * hexR * 0.84;
          const vy = cy + Math.sin(ang) * hexR * 0.84 * apparentScaleY;
          if (v === 0) ctx.moveTo(vx, vy);
          else ctx.lineTo(vx, vy);
        }
        ctx.closePath();

        if (cellActive > 0.08) {
          const red = Math.round(lerp(42, 255, cellActive));
          const green = Math.round(lerp(28, 179, cellActive * 0.92));
          const blue = Math.round(lerp(14, 24, cellActive * 0.4));
          ctx.fillStyle = `rgba(${red}, ${green}, ${blue}, ${(0.22 + 0.65 * cellActive).toFixed(3)})`;
          ctx.fill();
        }

        ctx.strokeStyle = cellActive > 0.6 ? "#FFE57F" : `rgba(255, 179, 0, ${(0.25 + 0.45 * cellActive).toFixed(3)})`;
        ctx.lineWidth = minSide * 0.0011;
        ctx.stroke();
      }
    }

    if (scanSweep >= 0 && scanSweep <= 1) {
      const localScan = clamp01((scanSweep - pn.order * 0.08) / 0.65);
      if (localScan > 0 && localScan < 1) {
        const sx = lerp(innerX, innerX + innerW, localScan);
        const scanGrad = ctx.createLinearGradient(sx - minSide * 0.018, 0, sx + minSide * 0.006, 0);
        scanGrad.addColorStop(0, "rgba(255, 229, 127, 0)");
        scanGrad.addColorStop(0.75, "rgba(255, 229, 127, 0.55)");
        scanGrad.addColorStop(1, "rgba(255, 255, 255, 0.85)");
        ctx.fillStyle = scanGrad;
        ctx.fillRect(sx - minSide * 0.018, innerY, minSide * 0.024, innerH);
      }
    }

    const sheenShift = Math.sin(u * TAU) * innerW * 0.12;
    ctx.fillStyle = "rgba(255, 245, 200, 0.055)";
    ctx.beginPath();
    ctx.moveTo(innerX + innerW * 0.12 + sheenShift, innerY);
    ctx.lineTo(innerX + innerW * 0.34 + sheenShift, innerY);
    ctx.lineTo(innerX + innerW * 0.16 + sheenShift, innerY + innerH);
    ctx.lineTo(innerX - innerW * 0.06 + sheenShift, innerY + innerH);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // 8. RIGHT STAGE: ENERGY INVERTER & 12-CELL BATTERY STORAGE TOWER
  // =========================================================================
  const towerX = towerLeftX;
  const towerY = height * 0.115;
  const towerW = width * 0.180;
  const towerH = datumY - towerY;

  chamferRectPath(towerX, towerY, towerW, towerH, minSide * 0.016);
  const towerGrad = ctx.createLinearGradient(towerX, towerY, towerX + towerW, towerY + towerH);
  towerGrad.addColorStop(0, "#1D150D");
  towerGrad.addColorStop(1, "#0E0A06");
  ctx.fillStyle = towerGrad;
  ctx.fill();
  ctx.strokeStyle = storageCharge > 0.7 ? "#FFB300" : "#7D5828";
  ctx.lineWidth = minSide * 0.0024;
  ctx.stroke();

  const portH = minSide * 0.028;
  ctx.fillStyle = "#2E2012";
  ctx.fillRect(towerX - minSide * 0.008, busY - portH * 0.5, minSide * 0.016, portH);
  ctx.strokeStyle = "#FFB300";
  ctx.lineWidth = minSide * 0.0018;
  ctx.strokeRect(towerX - minSide * 0.008, busY - portH * 0.5, minSide * 0.016, portH);

  // 8a. Top Section: Circular Inverter Core Dial
  const gaugeCX = towerX + towerW * 0.5;
  const gaugeCY = towerY + towerH * 0.165;
  const gaugeR = minSide * 0.068;

  ctx.beginPath();
  ctx.arc(gaugeCX, gaugeCY, gaugeR * 1.16, 0, TAU);
  ctx.fillStyle = "#100B06";
  ctx.fill();
  ctx.strokeStyle = "#3D2C1B";
  ctx.lineWidth = minSide * 0.0018;
  ctx.stroke();

  for (let i = 0; i < 24; i++) {
    const ang = -Math.PI * 0.5 + (i / 24) * TAU;
    const isMajor = i % 3 === 0;
    const r0 = gaugeR * (isMajor ? 0.94 : 0.98);
    const r1 = gaugeR * 1.07;
    ctx.strokeStyle = i / 24 <= inverterPower ? "#FFE57F" : "rgba(255, 179, 0, 0.22)";
    ctx.lineWidth = minSide * (isMajor ? 0.0022 : 0.0013);
    ctx.beginPath();
    ctx.moveTo(gaugeCX + Math.cos(ang) * r0, gaugeCY + Math.sin(ang) * r0);
    ctx.lineTo(gaugeCX + Math.cos(ang) * r1, gaugeCY + Math.sin(ang) * r1);
    ctx.stroke();
  }

  ctx.beginPath();
  ctx.arc(gaugeCX, gaugeCY, gaugeR * 0.78, 0, TAU);
  ctx.strokeStyle = "rgba(255, 179, 0, 0.16)";
  ctx.lineWidth = minSide * 0.006;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(gaugeCX, gaugeCY, gaugeR * 0.78, -Math.PI * 0.5, -Math.PI * 0.5 + inverterPower * TAU);
  ctx.strokeStyle = "#FFB300";
  ctx.lineWidth = minSide * 0.006;
  ctx.lineCap = "round";
  ctx.stroke();

  ctx.save();
  ctx.translate(gaugeCX, gaugeCY);
  ctx.rotate(u * 3 * TAU);
  ctx.strokeStyle = "#FF6D00";
  ctx.lineWidth = minSide * 0.0024;
  for (let k = 0; k < 3; k++) {
    const a0 = k * (TAU / 3) + 0.22;
    ctx.beginPath();
    ctx.arc(0, 0, gaugeR * 0.54, a0, a0 + TAU / 3 - 0.44);
    ctx.stroke();
  }
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.arc(gaugeCX, gaugeCY, gaugeR * 0.40, 0, TAU);
  ctx.fillStyle = "#181109";
  ctx.fill();
  ctx.clip();

  ctx.beginPath();
  const waveSpan = gaugeR * 0.76;
  for (let s = 0; s <= 24; s++) {
    const wf = s / 24;
    const wx = gaugeCX - waveSpan * 0.5 + wf * waveSpan;
    const wy = gaugeCY + Math.sin(wf * 2 * TAU - u * 8 * TAU) * gaugeR * 0.18 * (0.4 + 0.6 * inverterPower);
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.strokeStyle = "#FFE57F";
  ctx.lineWidth = minSide * 0.0020;
  ctx.stroke();
  ctx.restore();

  // 8b. Mid Divider Plate with 3 Telemetry LED Nodes
  const divY = towerY + towerH * 0.315;
  ctx.strokeStyle = "#4A341E";
  ctx.lineWidth = minSide * 0.0018;
  ctx.beginPath();
  ctx.moveTo(towerX + towerW * 0.10, divY);
  ctx.lineTo(towerX + towerW * 0.90, divY);
  ctx.stroke();

  for (let li = 0; li < 3; li++) {
    const lx = gaugeCX + (li - 1) * towerW * 0.18;
    const activeLed = inverterPower > 0.25 + li * 0.28;
    ctx.beginPath();
    ctx.arc(lx, divY, minSide * 0.0045, 0, TAU);
    ctx.fillStyle = activeLed ? "#FFE57F" : "#3A2918";
    ctx.fill();
  }

  // 8c. Lower Section: 12 Segmented Battery Charge Cells (Bottom-to-Top Fill)
  const wellPadX = towerW * 0.14;
  const wellTopY = towerY + towerH * 0.355;
  const wellBotY = datumY - towerH * 0.045;
  const wellX = towerX + wellPadX;
  const wellW = towerW - wellPadX * 2;
  const wellH = wellBotY - wellTopY;

  roundRectPath(wellX, wellTopY, wellW, wellH, minSide * 0.008);
  ctx.fillStyle = "#0A0704";
  ctx.fill();
  ctx.strokeStyle = "#3A2918";
  ctx.lineWidth = minSide * 0.0016;
  ctx.stroke();

  const cellCount = 12;
  const cellPad = minSide * 0.010;
  const cellGap = minSide * 0.007;
  const availH = wellH - cellPad * 2 - cellGap * (cellCount - 1);
  const cellH = availH / cellCount;
  const cellW = wellW - cellPad * 2;
  const cellX = wellX + cellPad;

  for (let ci = 0; ci < cellCount; ci++) {
    const cy = wellBotY - cellPad - (ci + 1) * cellH - ci * cellGap;
    const cellFloor = ci / cellCount;
    const cellCeil = (ci + 1) / cellCount;
    const fillAlpha = clamp01((storageCharge - cellFloor) / (cellCeil - cellFloor));

    // Clean calibrated side level ticks flanking battery well
    const tickY = cy + cellH * 0.5;
    const tickLen = minSide * 0.006;
    ctx.strokeStyle = fillAlpha > 0.5 ? "#FFB300" : "#3D2C1B";
    ctx.lineWidth = minSide * 0.0015;
    ctx.beginPath();
    ctx.moveTo(wellX - tickLen - minSide * 0.004, tickY);
    ctx.lineTo(wellX - minSide * 0.004, tickY);
    ctx.moveTo(wellX + wellW + minSide * 0.004, tickY);
    ctx.lineTo(wellX + wellW + tickLen + minSide * 0.004, tickY);
    ctx.stroke();

    roundRectPath(cellX, cy, cellW, cellH, minSide * 0.004);
    ctx.fillStyle = "#19120A";
    ctx.fill();

    if (fillAlpha > 0.01) {
      const cGrad = ctx.createLinearGradient(cellX, cy, cellX + cellW, cy);
      if (ci >= 9) {
        cGrad.addColorStop(0, "#FFB300");
        cGrad.addColorStop(0.5, "#FFE57F");
        cGrad.addColorStop(1, "#FFB300");
      } else if (ci >= 4) {
        cGrad.addColorStop(0, "#FF6D00");
        cGrad.addColorStop(0.5, "#FFB300");
        cGrad.addColorStop(1, "#FF6D00");
      } else {
        cGrad.addColorStop(0, "#D95300");
        cGrad.addColorStop(0.5, "#FF6D00");
        cGrad.addColorStop(1, "#D95300");
      }

      ctx.save();
      ctx.globalAlpha = fillAlpha;
      roundRectPath(cellX, cy, cellW, cellH, minSide * 0.004);
      ctx.fillStyle = cGrad;
      ctx.fill();

      ctx.fillStyle = "rgba(255, 248, 214, 0.55)";
      ctx.fillRect(cellX + minSide * 0.004, cy + minSide * 0.002, cellW - minSide * 0.008, minSide * 0.0022);
      ctx.restore();
    }
  }

  // =========================================================================
  // 9. GROUND DATUM LINE (CLEAN ARCHITECTURAL ANCHOR, NO EDGE FRAME)
  // =========================================================================
  ctx.strokeStyle = "#8A6228";
  ctx.lineWidth = minSide * 0.0022;
  ctx.beginPath();
  ctx.moveTo(width * 0.055, datumY);
  ctx.lineTo(width * 0.945, datumY);
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, k) => a + (b - a) * k;
  const easeInOutCubic = (x) => {
    const c = clamp01(x);
    return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
  };
  const easeInOutSine = (x) => 0.5 - 0.5 * Math.cos(Math.PI * clamp01(x));

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function chamferRectPath(x, y, w, h, c) {
    const ch = Math.min(c, w * 0.4, h * 0.4);
    ctx.beginPath();
    ctx.moveTo(x + ch, y);
    ctx.lineTo(x + w - ch, y);
    ctx.lineTo(x + w, y + ch);
    ctx.lineTo(x + w, y + h - ch);
    ctx.lineTo(x + w - ch, y + h);
    ctx.lineTo(x + ch, y + h);
    ctx.lineTo(x, y + h - ch);
    ctx.lineTo(x, y + ch);
    ctx.closePath();
  }

  function drawPolylinePoints(pts) {
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
  }

  function samplePolyline(pts, s) {
    const segLens = [];
    let total = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const dx = pts[i + 1][0] - pts[i][0];
      const dy = pts[i + 1][1] - pts[i][1];
      const len = Math.hypot(dx, dy);
      segLens.push(len);
      total += len;
    }
    const target = clamp01(s) * total;
    let acc = 0;
    for (let i = 0; i < segLens.length; i++) {
      const len = segLens[i];
      if (acc + len >= target || i === segLens.length - 1) {
        const local = len > 0 ? (target - acc) / len : 0;
        const x = lerp(pts[i][0], pts[i + 1][0], local);
        const y = lerp(pts[i][1], pts[i + 1][1], local);
        const ang = Math.atan2(pts[i + 1][1] - pts[i][1], pts[i + 1][0] - pts[i][0]);
        return { x, y, ang };
      }
      acc += len;
    }
    return { x: pts[0][0], y: pts[0][1], ang: 0 };
  }

  // =========================================================================
  // 1. CLEAN DARK MODERN PREMIUM BACKGROUND (ZERO GLOW, ZERO EDGE FRAMES)
  // =========================================================================
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#050811");
  bgGrad.addColorStop(0.64, "#080E1C");
  bgGrad.addColorStop(1, "#05070E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Subtle flat atmospheric strata above horizon (zero glow)
  const skyStrataGrad = ctx.createLinearGradient(0, 0, 0, height * 0.64);
  skyStrataGrad.addColorStop(0, "rgba(14, 28, 54, 0.25)");
  skyStrataGrad.addColorStop(0.6, "rgba(10, 20, 40, 0.10)");
  skyStrataGrad.addColorStop(1, "rgba(8, 16, 32, 0.30)");
  ctx.fillStyle = skyStrataGrad;
  ctx.fillRect(0, 0, width, height * 0.64);

  // Clean subterranean dark slab below ground datum
  const groundY = height * 0.640;
  const subGrad = ctx.createLinearGradient(0, groundY, 0, height);
  subGrad.addColorStop(0, "#070C18");
  subGrad.addColorStop(1, "#04060D");
  ctx.fillStyle = subGrad;
  ctx.fillRect(0, groundY, width, height - groundY);

  // =========================================================================
  // 2. SEAMLESS MULTI-SCENE CHOREOGRAPHY ENVELOPES
  // =========================================================================
  let structureFill = 0.55;
  let windIntensity = 0.45;
  let slipstreamAlpha = 0.2;
  let towerFlowProgress = 0;
  let substationCharge = 0.2;
  let feederFlow = 0;
  let hubActive = 0.25;
  let gridFlow = 0;
  let moduleCharge = 0.16;

  if (currentScene === 0) {
    // Scene 1: Aerodynamic Ignition & Vector Solidification
    const e = easeInOutCubic(sceneProgress);
    structureFill = lerp(0.55, 1.0, e);
    windIntensity = lerp(0.45, 0.92, e);
    slipstreamAlpha = lerp(0.2, 0.65, e);
    towerFlowProgress = lerp(0.0, 0.35, e);
    substationCharge = lerp(0.2, 0.35, e);
    feederFlow = 0;
    hubActive = lerp(0.25, 0.4, e);
    gridFlow = 0;
    moduleCharge = 0.16;
  } else if (currentScene === 1) {
    // Scene 2: Peak Kinetic Generation & Vertical Conversion
    const e = easeInOutCubic(sceneProgress);
    const windPeak = Math.sin(sceneProgress * Math.PI);
    structureFill = 1.0;
    windIntensity = 0.92 + 0.08 * windPeak;
    slipstreamAlpha = lerp(0.65, 1.0, Math.sin(clamp01(sceneProgress * 1.1) * Math.PI * 0.5));
    towerFlowProgress = lerp(0.35, 1.0, clamp01(sceneProgress / 0.65));
    substationCharge = lerp(0.35, 1.0, easeInOutSine(clamp01((sceneProgress - 0.15) / 0.7)));
    feederFlow = easeInOutCubic(clamp01((sceneProgress - 0.35) / 0.65));
    hubActive = lerp(0.4, 0.95, easeInOutSine(clamp01((sceneProgress - 0.4) / 0.6)));
    gridFlow = 0;
    moduleCharge = lerp(0.16, 0.24, easeInOutSine(clamp01((sceneProgress - 0.6) / 0.4)));
  } else {
    // Scene 3: Smart Grid Power Dispatch & Graceful Return to Loop Baseline
    if (sceneProgress < 0.64) {
      const d = easeInOutCubic(clamp01(sceneProgress / 0.54));
      structureFill = 1.0;
      windIntensity = lerp(0.92, 0.78, d);
      slipstreamAlpha = lerp(0.95, 0.68, d);
      towerFlowProgress = 1.0;
      substationCharge = 1.0;
      feederFlow = 1.0;
      hubActive = lerp(0.95, 1.0, Math.sin(d * Math.PI * 0.5));
      gridFlow = d;
      moduleCharge = lerp(0.24, 1.0, easeInOutSine(clamp01((d - 0.18) / 0.76)));
    } else {
      const r = easeInOutSine((sceneProgress - 0.64) / 0.36);
      structureFill = lerp(1.0, 0.55, r);
      windIntensity = lerp(0.78, 0.45, r);
      slipstreamAlpha = lerp(0.68, 0.2, r);
      towerFlowProgress = lerp(1.0, 0.0, r);
      substationCharge = lerp(1.0, 0.2, r);
      feederFlow = lerp(1.0, 0.0, r);
      hubActive = lerp(1.0, 0.25, r);
      gridFlow = lerp(1.0, 0.0, r);
      moduleCharge = lerp(1.0, 0.16, r);
    }
  }

  // =========================================================================
  // 3. NON-OVERLAPPING AERODYNAMIC WIND CORRIDOR STREAMLINES
  // =========================================================================
  function drawWindStream(xStart, xEnd, baseY, amp, freq, phaseShift, speedCycles, strokeW, color, showChevron) {
    const steps = 48;
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const f = i / steps;
      const x = lerp(xStart, xEnd, f);
      const env = Math.sin(f * Math.PI);
      const y = baseY + Math.sin(f * freq * TAU - u * speedCycles * TAU + phaseShift) * amp * env;
      pts.push([x, y]);
    }

    ctx.strokeStyle = `rgba(41, 121, 255, ${(0.12 + 0.14 * windIntensity).toFixed(3)})`;
    ctx.lineWidth = strokeW * 0.55;
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    let totalLen = 0;
    for (let i = 1; i < pts.length; i++) {
      totalLen += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    }
    const dashLen = totalLen * 0.24;
    const gapLen = totalLen * 0.26;
    const cycleLen = dashLen + gapLen;
    const dashPhase = (u * speedCycles * cycleLen * 2 + phaseShift * 18) % cycleLen;

    ctx.save();
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.38 + 0.57 * windIntensity;
    ctx.lineWidth = strokeW;
    ctx.lineCap = "round";
    ctx.setLineDash([dashLen, gapLen]);
    ctx.lineDashOffset = -dashPhase;
    drawPolylinePoints(pts);
    ctx.stroke();
    ctx.restore();

    if (showChevron) {
      const p = (u * speedCycles + phaseShift * 0.15) % 1;
      const pos = samplePolyline(pts, p);
      const chevFade = Math.sin(p * Math.PI);
      const cs = minSide * 0.0052;
      ctx.save();
      ctx.translate(pos.x, pos.y);
      ctx.rotate(pos.ang);
      ctx.globalAlpha = chevFade * (0.35 + 0.60 * windIntensity);
      ctx.strokeStyle = color;
      ctx.lineWidth = strokeW * 0.85;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(-cs, -cs * 0.72);
      ctx.lineTo(cs * 0.4, 0);
      ctx.lineTo(-cs, cs * 0.72);
      ctx.stroke();
      ctx.restore();
    }
  }

  // Upper sky laminar wind lanes strictly above center rotor slipstream circle
  drawWindStream(width * 0.06, width * 0.94, height * 0.052, minSide * 0.006, 2.5, 0.2, 4, minSide * 0.0026, "#2979FF", true);
  drawWindStream(width * 0.08, width * 0.92, height * 0.088, minSide * 0.006, 2.0, 1.4, 5, minSide * 0.0032, "#00F0FF", true);

  // Sleek taut laminar air channel streams strictly inside open air corridors (zero overlap!)
  const airCorridors = [
    [width * 0.045, width * 0.112],
    [width * 0.305, width * 0.382],
    [width * 0.618, width * 0.695],
    [width * 0.888, width * 0.955],
  ];
  for (let c = 0; c < airCorridors.length; c++) {
    const [x0, x1] = airCorridors[c];
    drawWindStream(x0, x1, height * 0.285, minSide * 0.0022, 1.0, c * 0.9, 4, minSide * 0.0022, "#2979FF", true);
    drawWindStream(x0, x1, height * 0.355, minSide * 0.0024, 1.0, c * 0.9 + 1.3, 5, minSide * 0.0028, "#00F0FF", true);
    drawWindStream(x0, x1, height * 0.425, minSide * 0.0022, 1.0, c * 0.9 + 2.4, 4, minSide * 0.0022, "#E0F7FA", false);
  }

  // =========================================================================
  // 4. CLEAN TOPOGRAPHIC COASTAL STRATA IN OPEN HORIZON SPANS (ZERO TOWER OVERLAP)
  // =========================================================================
  // Strictly positioned in the clear open spans between turbine plinths & below blade bottom tips (y >= 0.565*H)
  const ridgeSpans = [
    { x0: width * 0.055, x1: width * 0.165, peak: 0.578, mid: 0.608 },
    { x0: width * 0.255, x1: width * 0.450, peak: 0.570, mid: 0.602 },
    { x0: width * 0.550, x1: width * 0.745, peak: 0.570, mid: 0.602 },
    { x0: width * 0.835, x1: width * 0.945, peak: 0.578, mid: 0.608 },
  ];
  for (let ri = 0; ri < ridgeSpans.length; ri++) {
    const rs = ridgeSpans[ri];
    const spanW = rs.x1 - rs.x0;
    // Distant geometric mountain contour facet (crisp vector polygon, zero glow)
    ctx.beginPath();
    ctx.moveTo(rs.x0, groundY);
    ctx.lineTo(rs.x0 + spanW * 0.24, height * rs.mid);
    ctx.lineTo(rs.x0 + spanW * 0.52, height * rs.peak);
    ctx.lineTo(rs.x0 + spanW * 0.80, height * (rs.mid + 0.008));
    ctx.lineTo(rs.x1, groundY);
    ctx.closePath();
    ctx.fillStyle = "rgba(15, 29, 58, 0.52)";
    ctx.fill();
    ctx.strokeStyle = `rgba(41, 121, 255, ${(0.25 + 0.25 * structureFill).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0012;
    ctx.stroke();

    // Inner clean topographic elevation line
    ctx.beginPath();
    ctx.moveTo(rs.x0 + spanW * 0.12, groundY - minSide * 0.012);
    ctx.lineTo(rs.x0 + spanW * 0.52, height * (rs.peak + 0.025));
    ctx.lineTo(rs.x0 + spanW * 0.90, groundY - minSide * 0.012);
    ctx.strokeStyle = `rgba(0, 240, 255, ${(0.12 + 0.18 * windIntensity).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0010;
    ctx.stroke();
  }

  // =========================================================================
  // 5. THREE OFFSHORE/HIGHLAND PREMIUM VECTOR WIND TURBINES
  // =========================================================================
  const turbines = [
    { x: width * 0.21, hubY: height * 0.365, r: minSide * 0.135, revs: 5, phase0: Math.PI / 7, scale: 0.84 },
    { x: width * 0.50, hubY: height * 0.320, r: minSide * 0.175, revs: 6, phase0: 0, scale: 1.0 },
    { x: width * 0.79, hubY: height * 0.365, r: minSide * 0.135, revs: 5, phase0: Math.PI / 3.5, scale: 0.84 },
  ];

  // C2-continuous periodic angular integral: angle(0) = phase0, angle(1) = phase0 + 2π * revs
  const integralCurve = u - (0.32 / TAU) * Math.sin(TAU * u);

  for (let ti = 0; ti < turbines.length; ti++) {
    const tb = turbines[ti];
    const plinthH = minSide * 0.022 * tb.scale;
    const plinthTopY = groundY - plinthH;
    const plinthWBot = minSide * 0.068 * tb.scale;
    const plinthWTop = minSide * 0.046 * tb.scale;

    // 5a. Foundation Plinth (sharp architectural trapezoid)
    ctx.beginPath();
    ctx.moveTo(tb.x - plinthWBot * 0.5, groundY);
    ctx.lineTo(tb.x - plinthWTop * 0.5, plinthTopY);
    ctx.lineTo(tb.x + plinthWTop * 0.5, plinthTopY);
    ctx.lineTo(tb.x + plinthWBot * 0.5, groundY);
    ctx.closePath();
    ctx.fillStyle = "#0F1B33";
    ctx.fill();
    ctx.strokeStyle = "#2979FF";
    ctx.lineWidth = minSide * 0.0018;
    ctx.stroke();

    ctx.fillStyle = `rgba(0, 240, 255, ${(0.25 + 0.55 * towerFlowProgress).toFixed(3)})`;
    ctx.fillRect(tb.x - plinthWTop * 0.38, plinthTopY + plinthH * 0.28, plinthWTop * 0.76, plinthH * 0.18);

    // 5b. Tapered Architectural Tower Mast
    const towerBotW = minSide * 0.032 * tb.scale;
    const towerTopW = minSide * 0.015 * tb.scale;
    const towerTopY = tb.hubY + minSide * 0.008 * tb.scale;

    ctx.beginPath();
    ctx.moveTo(tb.x - towerBotW * 0.5, plinthTopY);
    ctx.lineTo(tb.x - towerTopW * 0.5, towerTopY);
    ctx.lineTo(tb.x, towerTopY);
    ctx.lineTo(tb.x, plinthTopY);
    ctx.closePath();
    const leftTowerGrad = ctx.createLinearGradient(0, towerTopY, 0, plinthTopY);
    leftTowerGrad.addColorStop(0, `rgba(224, 247, 250, ${(0.35 + 0.6 * structureFill).toFixed(3)})`);
    leftTowerGrad.addColorStop(1, `rgba(41, 121, 255, ${(0.28 + 0.55 * structureFill).toFixed(3)})`);
    ctx.fillStyle = leftTowerGrad;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(tb.x, plinthTopY);
    ctx.lineTo(tb.x, towerTopY);
    ctx.lineTo(tb.x + towerTopW * 0.5, towerTopY);
    ctx.lineTo(tb.x + towerBotW * 0.5, plinthTopY);
    ctx.closePath();
    const rightTowerGrad = ctx.createLinearGradient(0, towerTopY, 0, plinthTopY);
    rightTowerGrad.addColorStop(0, `rgba(22, 42, 78, ${(0.55 + 0.4 * structureFill).toFixed(3)})`);
    rightTowerGrad.addColorStop(1, `rgba(14, 27, 52, ${(0.65 + 0.35 * structureFill).toFixed(3)})`);
    ctx.fillStyle = rightTowerGrad;
    ctx.fill();

    // Horizontal architectural tower section ring joints
    ctx.strokeStyle = `rgba(0, 240, 255, ${(0.28 + 0.30 * structureFill).toFixed(3)})`;
    ctx.lineWidth = minSide * 0.0012;
    for (let j = 1; j <= 3; j++) {
      const jf = j / 4;
      const jy = lerp(towerTopY, plinthTopY, jf);
      const jw = lerp(towerTopW, towerBotW, jf) * 0.5;
      ctx.beginPath();
      ctx.moveTo(tb.x - jw, jy);
      ctx.lineTo(tb.x + jw, jy);
      ctx.stroke();
    }

    // Crisp tower outline
    ctx.beginPath();
    ctx.moveTo(tb.x - towerBotW * 0.5, plinthTopY);
    ctx.lineTo(tb.x - towerTopW * 0.5, towerTopY);
    ctx.lineTo(tb.x + towerTopW * 0.5, towerTopY);
    ctx.lineTo(tb.x + towerBotW * 0.5, plinthTopY);
    ctx.closePath();
    ctx.strokeStyle = "#00F0FF";
    ctx.globalAlpha = 0.55 + 0.45 * structureFill;
    ctx.lineWidth = minSide * 0.0017;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // 5c. Internal Kinetic Energy Conduit Channel inside Tower
    const conduitTopY = towerTopY + minSide * 0.015 * tb.scale;
    const conduitBotY = plinthTopY - minSide * 0.005 * tb.scale;
    ctx.strokeStyle = "rgba(0, 240, 255, 0.25)";
    ctx.lineWidth = minSide * 0.003 * tb.scale;
    ctx.beginPath();
    ctx.moveTo(tb.x, conduitTopY);
    ctx.lineTo(tb.x, conduitBotY);
    ctx.stroke();

    if (towerFlowProgress > 0.01) {
      const pulseDropY = lerp(conduitTopY, conduitBotY, (u * 6 + ti * 0.33) % 1);
      const streamEnd = lerp(conduitTopY, conduitBotY, towerFlowProgress);
      ctx.strokeStyle = "#00F0FF";
      ctx.lineWidth = minSide * 0.0032 * tb.scale;
      ctx.beginPath();
      ctx.moveTo(tb.x, conduitTopY);
      ctx.lineTo(tb.x, streamEnd);
      ctx.stroke();

      if (pulseDropY <= streamEnd - minSide * 0.012 * tb.scale) {
        ctx.fillStyle = "#E0F7FA";
        roundRectPath(
          tb.x - minSide * 0.0032 * tb.scale,
          pulseDropY - minSide * 0.009 * tb.scale,
          minSide * 0.0064 * tb.scale,
          minSide * 0.018 * tb.scale,
          minSide * 0.003 * tb.scale
        );
        ctx.fill();
      }
    }

    // 5d. Outer Aerodynamic Slipstream Arcs (strictly OUTSIDE rotor circle, zero blade overlap)
    const slipR1 = tb.r + minSide * 0.014 * tb.scale;
    const slipR2 = tb.r + minSide * 0.024 * tb.scale;
    const rotAngle = tb.phase0 + tb.revs * TAU * integralCurve;

    ctx.save();
    ctx.globalAlpha = slipstreamAlpha * 0.55;
    ctx.strokeStyle = "#00F0FF";
    ctx.lineWidth = minSide * 0.0018 * tb.scale;
    ctx.lineCap = "round";
    for (let k = 0; k < 3; k++) {
      const baseA = rotAngle + k * (TAU / 3) - 0.16;
      ctx.beginPath();
      ctx.arc(tb.x, tb.hubY, slipR1, baseA - 0.42, baseA - 0.06);
      ctx.stroke();
    }
    ctx.globalAlpha = slipstreamAlpha * 0.30;
    ctx.strokeStyle = "#2979FF";
    ctx.lineWidth = minSide * 0.0014 * tb.scale;
    for (let k = 0; k < 3; k++) {
      const baseA = rotAngle + k * (TAU / 3) - 0.25;
      ctx.beginPath();
      ctx.arc(tb.x, tb.hubY, slipR2, baseA - 0.34, baseA - 0.08);
      ctx.stroke();
    }
    ctx.restore();

    // 5e. Nacelle Housing + Top Aviation Beacon
    const nacW = minSide * 0.036 * tb.scale;
    const nacH = minSide * 0.022 * tb.scale;
    roundRectPath(tb.x - nacW * 0.42, tb.hubY - nacH * 0.5, nacW, nacH, nacH * 0.45);
    ctx.fillStyle = "#162A4E";
    ctx.fill();
    ctx.strokeStyle = "#2979FF";
    ctx.lineWidth = minSide * 0.0016;
    ctx.stroke();

    // Top aviation status indicator dot on nacelle rear (strictly above nacelle)
    const beaconPulse = 0.45 + 0.55 * Math.sin(u * 5 * TAU + ti * 1.1);
    ctx.beginPath();
    ctx.arc(tb.x + nacW * 0.30, tb.hubY - nacH * 0.5 - minSide * 0.003 * tb.scale, minSide * 0.0026 * tb.scale, 0, TAU);
    ctx.fillStyle = `rgba(0, 240, 255, ${beaconPulse.toFixed(3)})`;
    ctx.fill();

    // 5f. Three Symmetrical Precision Airfoil Blades
    ctx.save();
    ctx.translate(tb.x, tb.hubY);
    ctx.rotate(rotAngle);

    for (let b = 0; b < 3; b++) {
      ctx.save();
      ctx.rotate(b * (TAU / 3));

      const rStart = minSide * 0.015 * tb.scale;
      const rEnd = tb.r;
      const rootW = minSide * 0.0075 * tb.scale;
      const maxChord = minSide * 0.019 * tb.scale;
      const tipW = minSide * 0.0022 * tb.scale;

      ctx.fillStyle = "#2979FF";
      ctx.fillRect(-rootW * 0.5, -rStart - minSide * 0.004 * tb.scale, rootW, minSide * 0.006 * tb.scale);

      ctx.beginPath();
      ctx.moveTo(-rootW * 0.5, -rStart);
      ctx.bezierCurveTo(
        -maxChord * 0.72, -lerp(rStart, rEnd, 0.24),
        -maxChord * 0.45, -lerp(rStart, rEnd, 0.62),
        -tipW * 0.5, -rEnd
      );
      ctx.lineTo(tipW * 0.5, -rEnd);
      ctx.bezierCurveTo(
        maxChord * 0.18, -lerp(rStart, rEnd, 0.62),
        maxChord * 0.22, -lerp(rStart, rEnd, 0.24),
        rootW * 0.5, -rStart
      );
      ctx.closePath();

      const bladeGrad = ctx.createLinearGradient(0, -rStart, 0, -rEnd);
      bladeGrad.addColorStop(0, `rgba(224, 247, 250, ${(0.55 + 0.45 * structureFill).toFixed(3)})`);
      bladeGrad.addColorStop(0.7, `rgba(162, 232, 255, ${(0.48 + 0.47 * structureFill).toFixed(3)})`);
      bladeGrad.addColorStop(1, "#00F0FF");
      ctx.fillStyle = bladeGrad;
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(0, -rStart);
      ctx.lineTo(0, -rEnd);
      ctx.lineTo(tipW * 0.5, -rEnd);
      ctx.bezierCurveTo(
        maxChord * 0.18, -lerp(rStart, rEnd, 0.62),
        maxChord * 0.22, -lerp(rStart, rEnd, 0.24),
        rootW * 0.5, -rStart
      );
      ctx.closePath();
      ctx.fillStyle = `rgba(28, 74, 152, ${(0.35 + 0.35 * structureFill).toFixed(3)})`;
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(-rootW * 0.5, -rStart);
      ctx.bezierCurveTo(
        -maxChord * 0.72, -lerp(rStart, rEnd, 0.24),
        -maxChord * 0.45, -lerp(rStart, rEnd, 0.62),
        -tipW * 0.5, -rEnd
      );
      ctx.lineTo(tipW * 0.5, -rEnd);
      ctx.bezierCurveTo(
        maxChord * 0.18, -lerp(rStart, rEnd, 0.62),
        maxChord * 0.22, -lerp(rStart, rEnd, 0.24),
        rootW * 0.5, -rStart
      );
      ctx.closePath();
      ctx.strokeStyle = "#00F0FF";
      ctx.lineWidth = minSide * 0.0014 * tb.scale;
      ctx.stroke();

      ctx.fillStyle = "#00F0FF";
      ctx.beginPath();
      ctx.moveTo(-tipW * 1.15, -rEnd * 0.92);
      ctx.lineTo(-tipW * 0.5, -rEnd);
      ctx.lineTo(tipW * 0.5, -rEnd);
      ctx.lineTo(tipW * 0.85, -rEnd * 0.92);
      ctx.closePath();
      ctx.fill();

      ctx.restore();
    }

    const hubR = minSide * 0.017 * tb.scale;
    ctx.beginPath();
    ctx.arc(0, 0, hubR, 0, TAU);
    ctx.fillStyle = "#E0F7FA";
    ctx.fill();
    ctx.strokeStyle = "#00F0FF";
    ctx.lineWidth = minSide * 0.002 * tb.scale;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, hubR * 0.45, 0, TAU);
    ctx.fillStyle = "#2979FF";
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // 6. HORIZON DATUM LINE (CLEAN VECTOR SEPARATOR)
  // =========================================================================
  ctx.strokeStyle = "#2979FF";
  ctx.lineWidth = minSide * 0.0022;
  ctx.beginPath();
  ctx.moveTo(width * 0.055, groundY);
  ctx.lineTo(width * 0.945, groundY);
  ctx.stroke();

  ctx.save();
  ctx.strokeStyle = "rgba(0, 240, 255, 0.28)";
  ctx.lineWidth = minSide * 0.0012;
  ctx.setLineDash([minSide * 0.014, minSide * 0.012]);
  ctx.beginPath();
  ctx.moveTo(width * 0.055, groundY + minSide * 0.008);
  ctx.lineTo(width * 0.945, groundY + minSide * 0.008);
  ctx.stroke();
  ctx.restore();

  // =========================================================================
  // 7. NON-CROSSING SMART GRID CIRCUIT ARCHITECTURE (45-DEG CHAMFERED PLANAR)
  // =========================================================================
  const subY = height * 0.692;
  const subW = width * 0.078;
  const subH = height * 0.048;
  const hubX = width * 0.50;
  const hubY = height * 0.785;
  const hubW = width * 0.125;
  const hubH = height * 0.058;

  for (let ti = 0; ti < turbines.length; ti++) {
    const sx = turbines[ti].x;
    const y0 = groundY;
    const y1 = subY - subH * 0.5;
    ctx.strokeStyle = "rgba(41, 121, 255, 0.45)";
    ctx.lineWidth = minSide * 0.003;
    ctx.beginPath();
    ctx.moveTo(sx, y0);
    ctx.lineTo(sx, y1);
    ctx.stroke();

    if (towerFlowProgress > 0.4) {
      ctx.strokeStyle = "#00F0FF";
      ctx.lineWidth = minSide * 0.003;
      ctx.beginPath();
      ctx.moveTo(sx, y0);
      ctx.lineTo(sx, lerp(y0, y1, clamp01((towerFlowProgress - 0.4) / 0.6)));
      ctx.stroke();
    }
  }

  const feederPaths = [
    [
      [turbines[0].x, subY + subH * 0.5],
      [turbines[0].x, hubY - minSide * 0.016],
      [turbines[0].x + minSide * 0.016, hubY],
      [hubX - hubW * 0.5, hubY],
    ],
    [
      [turbines[1].x, subY + subH * 0.5],
      [hubX, hubY - hubH * 0.5],
    ],
    [
      [turbines[2].x, subY + subH * 0.5],
      [turbines[2].x, hubY - minSide * 0.016],
      [turbines[2].x - minSide * 0.016, hubY],
      [hubX + hubW * 0.5, hubY],
    ],
  ];

  function drawCircuitTrace(pts, fillRatio, packetSpeedCycles, packetPhaseOffset) {
    ctx.strokeStyle = "rgba(41, 121, 255, 0.24)";
    ctx.lineWidth = minSide * 0.0030;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    drawPolylinePoints(pts);
    ctx.stroke();

    if (fillRatio > 0.005) {
      let totalLen = 0;
      for (let i = 1; i < pts.length; i++) {
        totalLen += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
      }
      ctx.save();
      ctx.strokeStyle = "#00F0FF";
      ctx.lineWidth = minSide * 0.0030;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.setLineDash([totalLen * fillRatio, totalLen]);
      drawPolylinePoints(pts);
      ctx.stroke();
      ctx.restore();

      const pktPhase = (u * packetSpeedCycles + packetPhaseOffset) % 1;
      if (pktPhase > 0.05 && pktPhase < Math.min(0.94, fillRatio - 0.03)) {
        const edgeFade = Math.sin(clamp01(pktPhase / Math.max(0.08, fillRatio)) * Math.PI);
        const pos = samplePolyline(pts, pktPhase);
        ctx.save();
        ctx.translate(pos.x, pos.y);
        ctx.rotate(pos.ang);
        ctx.globalAlpha = clamp01(edgeFade * 1.4);
        ctx.fillStyle = "#E0F7FA";
        roundRectPath(-minSide * 0.009, -minSide * 0.0028, minSide * 0.018, minSide * 0.0056, minSide * 0.0028);
        ctx.fill();
        ctx.restore();
      }
    }
  }

  for (let i = 0; i < feederPaths.length; i++) {
    drawCircuitTrace(feederPaths[i], feederFlow, 6, i * 0.25);
  }

  const modXs = [
    width * 0.115,
    width * 0.255,
    width * 0.395,
    width * 0.605,
    width * 0.745,
    width * 0.885,
  ];
  const modY = height * 0.892;
  const modW = width * 0.088;
  const modH = height * 0.056;
  const modTopY = modY - modH * 0.5;
  const hubBotY = hubY + hubH * 0.5;
  const ch = minSide * 0.009;

  // Nested 45-degree chamfered planar bus routing (strictly zero line crossings!)
  const gridPaths = [
    [
      [hubX - hubW * 0.34, hubBotY],
      [hubX - hubW * 0.34, height * 0.828 - ch],
      [hubX - hubW * 0.34 - ch, height * 0.828],
      [modXs[0] + ch, height * 0.828],
      [modXs[0], height * 0.828 + ch],
      [modXs[0], modTopY],
    ],
    [
      [hubX - hubW * 0.20, hubBotY],
      [hubX - hubW * 0.20, height * 0.839 - ch],
      [hubX - hubW * 0.20 - ch, height * 0.839],
      [modXs[1] + ch, height * 0.839],
      [modXs[1], height * 0.839 + ch],
      [modXs[1], modTopY],
    ],
    [
      [hubX - hubW * 0.06, hubBotY],
      [hubX - hubW * 0.06, height * 0.850 - ch],
      [hubX - hubW * 0.06 - ch, height * 0.850],
      [modXs[2] + ch, height * 0.850],
      [modXs[2], height * 0.850 + ch],
      [modXs[2], modTopY],
    ],
    [
      [hubX + hubW * 0.06, hubBotY],
      [hubX + hubW * 0.06, height * 0.850 - ch],
      [hubX + hubW * 0.06 + ch, height * 0.850],
      [modXs[3] - ch, height * 0.850],
      [modXs[3], height * 0.850 + ch],
      [modXs[3], modTopY],
    ],
    [
      [hubX + hubW * 0.20, hubBotY],
      [hubX + hubW * 0.20, height * 0.839 - ch],
      [hubX + hubW * 0.20 + ch, height * 0.839],
      [modXs[4] - ch, height * 0.839],
      [modXs[4], height * 0.839 + ch],
      [modXs[4], modTopY],
    ],
    [
      [hubX + hubW * 0.34, hubBotY],
      [hubX + hubW * 0.34, height * 0.828 - ch],
      [hubX + hubW * 0.34 + ch, height * 0.828],
      [modXs[5] - ch, height * 0.828],
      [modXs[5], height * 0.828 + ch],
      [modXs[5], modTopY],
    ],
  ];

  for (let i = 0; i < gridPaths.length; i++) {
    const distIdx = i < 3 ? 2 - i : i - 3;
    const localFlow = clamp01((gridFlow - distIdx * 0.08) / 0.72);
    drawCircuitTrace(gridPaths[i], localFlow, 6, distIdx * 0.22);

    // Crisp terminal anchor dot at module entry
    ctx.beginPath();
    ctx.arc(modXs[i], modTopY, minSide * 0.0032, 0, TAU);
    ctx.fillStyle = localFlow > 0.92 ? "#E0F7FA" : "#2979FF";
    ctx.fill();
  }

  // 7a. Render 3 Substation Converter Nodes
  for (let ti = 0; ti < turbines.length; ti++) {
    const sx = turbines[ti].x - subW * 0.5;
    const sy = subY - subH * 0.5;
    chamferRectPath(sx, sy, subW, subH, minSide * 0.008);
    ctx.fillStyle = "#0D172B";
    ctx.fill();
    ctx.strokeStyle = substationCharge > 0.5 ? "#00F0FF" : "#2979FF";
    ctx.lineWidth = minSide * 0.0018;
    ctx.stroke();

    const barCount = 5;
    const innerPadX = subW * 0.16;
    const innerPadY = subH * 0.26;
    const availW = subW - innerPadX * 2;
    const barGap = availW * 0.09;
    const barW = (availW - barGap * (barCount - 1)) / barCount;
    const barH = subH - innerPadY * 2;

    for (let bi = 0; bi < barCount; bi++) {
      const bx = sx + innerPadX + bi * (barW + barGap);
      const by = sy + innerPadY;
      const threshold = (bi + 0.5) / barCount;
      const barAlpha = clamp01((substationCharge - (threshold - 0.18)) / 0.18);

      roundRectPath(bx, by, barW, barH, barW * 0.22);
      ctx.fillStyle = "rgba(41, 121, 255, 0.16)";
      ctx.fill();

      if (barAlpha > 0.01) {
        roundRectPath(bx, by, barW, barH, barW * 0.22);
        ctx.fillStyle = bi >= 3 ? `rgba(0, 240, 255, ${barAlpha.toFixed(3)})` : `rgba(41, 121, 255, ${(0.35 + 0.65 * barAlpha).toFixed(3)})`;
        ctx.fill();
      }
    }
  }

  // 7b. Render Central Main Distribution Hub
  const hubLeft = hubX - hubW * 0.5;
  const hubTop = hubY - hubH * 0.5;
  chamferRectPath(hubLeft, hubTop, hubW, hubH, minSide * 0.012);
  ctx.fillStyle = "#0E1A32";
  ctx.fill();
  ctx.strokeStyle = hubActive > 0.5 ? "#00F0FF" : "#2979FF";
  ctx.lineWidth = minSide * 0.0022;
  ctx.stroke();

  const coreR = hubH * 0.32;
  ctx.beginPath();
  ctx.arc(hubX, hubY, coreR, 0, TAU);
  ctx.strokeStyle = "rgba(41, 121, 255, 0.35)";
  ctx.lineWidth = minSide * 0.0022;
  ctx.stroke();

  const hubSpin = u * 4 * TAU;
  ctx.save();
  ctx.translate(hubX, hubY);
  ctx.rotate(hubSpin);
  ctx.strokeStyle = "#00F0FF";
  ctx.lineWidth = minSide * 0.0028;
  ctx.lineCap = "round";
  for (let s = 0; s < 3; s++) {
    const a0 = s * (TAU / 3) + 0.18;
    const a1 = a0 + (TAU / 3) * 0.62 * clamp01(0.45 + 0.55 * hubActive);
    ctx.beginPath();
    ctx.arc(0, 0, coreR, a0, a1);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.arc(0, 0, coreR * 0.38, 0, TAU);
  ctx.fillStyle = hubActive > 0.6 ? "#E0F7FA" : "#00F0FF";
  ctx.fill();
  ctx.restore();

  for (let side = -1; side <= 1; side += 2) {
    for (let k = 0; k < 3; k++) {
      const bx = hubX + side * (coreR + minSide * 0.012 + k * minSide * 0.009) - minSide * 0.0025;
      const bh = hubH * (0.48 - k * 0.09);
      const by = hubY - bh * 0.5;
      roundRectPath(bx, by, minSide * 0.005, bh, minSide * 0.002);
      ctx.fillStyle = hubActive > 0.3 + k * 0.22 ? "#00F0FF" : "rgba(41, 121, 255, 0.25)";
      ctx.fill();
    }
  }

  // 7c. Render 6 Smart-City Distribution Modules with Symmetric Architectural Profiles
  const moduleProfiles = [
    [0.54, 0.86, 0.68, 0.48],
    [0.72, 0.56, 0.94, 0.64],
    [0.62, 0.96, 0.82, 0.58],
    [0.58, 0.82, 0.96, 0.62],
    [0.64, 0.94, 0.56, 0.72],
    [0.48, 0.68, 0.86, 0.54],
  ];

  for (let i = 0; i < modXs.length; i++) {
    const mx = modXs[i] - modW * 0.5;
    const my = modY - modH * 0.5;
    const distIdx = i < 3 ? 2 - i : i - 3;
    const localCharge = clamp01((moduleCharge - distIdx * 0.06) / 0.82);

    chamferRectPath(mx, my, modW, modH, minSide * 0.008);
    ctx.fillStyle = "#0C1528";
    ctx.fill();
    ctx.strokeStyle = localCharge > 0.5 ? "#00F0FF" : "#2979FF";
    ctx.lineWidth = minSide * 0.0018;
    ctx.stroke();

    const blockCount = 4;
    const padX = modW * 0.14;
    const padY = modH * 0.22;
    const innerW = modW - padX * 2;
    const gap = innerW * 0.10;
    const bw = (innerW - gap * (blockCount - 1)) / blockCount;
    const maxH = modH - padY * 2;
    const heightMultipliers = moduleProfiles[i];

    for (let bi = 0; bi < blockCount; bi++) {
      const bx = mx + padX + bi * (bw + gap);
      const targetH = maxH * heightMultipliers[bi];
      const baseBy = my + modH - padY;

      roundRectPath(bx, baseBy - targetH, bw, targetH, bw * 0.18);
      ctx.fillStyle = "rgba(41, 121, 255, 0.16)";
      ctx.fill();

      const activeH = targetH * clamp01(0.18 + 0.82 * localCharge);
      roundRectPath(bx, baseBy - activeH, bw, activeH, bw * 0.18);
      ctx.fillStyle = localCharge > 0.65 ? "#00F0FF" : "#2979FF";
      ctx.fill();

      if (localCharge > 0.75) {
        ctx.fillStyle = "#E0F7FA";
        ctx.fillRect(bx, baseBy - activeH, bw, minSide * 0.0022);
      }
    }
  }

  ctx.restore();
}
